window.AI_TOPICS=[{title_en:"Toothache",title_ar:"ألم الأسنان",description_en:"Tooth pain can come from decay, a damaged tooth or infection.\nSee a dentist if it lasts more than two days, or sooner with fever or swelling.\nTrouble breathing or swallowing with swelling needs emergency care.",description_ar:"وجع الأسنان ممكن يكون من تسوس أو سن مكسور أو عدوى.\nاكشف لو الوجع مستمر أكتر من يومين، وأسرع لو معاه حرارة أو ورم.\nصعوبة التنفس أو البلع مع الورم محتاجة طوارئ فوراً.",symptoms:{en:"Tooth pain, pain when biting, fever or swelling.",ar:"وجع سن، ألم مع العض، حرارة أو ورم."},treatment:{en:"A dentist identifies and treats the cause; soft food can help while waiting.",ar:"دكتور الأسنان بيحدد السبب ويعالجه؛ الأكل الطري ممكن يريحك لحد الكشف."},prevention:{en:"Brush twice daily with fluoride toothpaste, clean between teeth and limit sugar.",ar:"اغسل مرتين بمعجون فلورايد، ونضف بين الأسنان وقلل السكريات."},category:"Emergency",source_name:"NHS",source_url:"https://www.nhs.uk/symptoms/toothache/",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Toothache",ar:"ألم الأسنان",sen:"Tooth pain can come from decay, a damaged tooth or infection.\nSee a dentist if it lasts more than two days, or sooner with fever or swelling.\nTrouble breathing or swallowing with swelling needs emergency care.",sar:"وجع الأسنان ممكن يكون من تسوس أو سن مكسور أو عدوى.\nاكشف لو الوجع مستمر أكتر من يومين، وأسرع لو معاه حرارة أو ورم.\nصعوبة التنفس أو البلع مع الورم محتاجة طوارئ فوراً.",cat:"Emergency",src:"https://www.nhs.uk/symptoms/toothache/"},{title_en:"Tooth sensitivity",title_ar:"حساسية الأسنان",description_en:"Cold, hot or sweet food can hurt when sensitive tooth layers are exposed.\nWorn enamel, gum recession, decay or a crack may be involved.\nSee a dentist to identify the cause instead of assuming all sensitivity is harmless.",description_ar:"البارد أو السخن أو الحلو ممكن يوجعوا لما طبقات السن الحساسة تتكشف.\nالسبب ممكن يكون تآكل المينا أو انحسار اللثة أو تسوس أو شرخ.\nاكشف عشان تعرف السبب ومتعتبرش كل حساسية بسيطة.",symptoms:{en:"Pain triggered by hot, cold, sweet or sour foods.",ar:"وجع مع السخن أو البارد أو الحلو أو الحمضي."},treatment:{en:"A dentist may recommend desensitizing toothpaste, fluoride varnish or covering exposed roots.",ar:"الدكتور ممكن ينصح بمعجون حساسية أو فلورايد أو تغطية الجذور المكشوفة."},prevention:{en:"Use a soft brush gently and limit acidic foods.",ar:"استخدم فرشاة ناعمة برفق وقلل الأكل الحمضي."},category:"Oral health",source_name:"Cleveland Clinic",source_url:"https://my.clevelandclinic.org/health/symptoms/10954-teeth-sensitivity",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Tooth sensitivity",ar:"حساسية الأسنان",cat:"Oral health",sen:"Cold, hot or sweet food can hurt when sensitive tooth layers are exposed.\nWorn enamel, gum recession, decay or a crack may be involved.\nSee a dentist to identify the cause instead of assuming all sensitivity is harmless.",sar:"البارد أو السخن أو الحلو ممكن يوجعوا لما طبقات السن الحساسة تتكشف.\nالسبب ممكن يكون تآكل المينا أو انحسار اللثة أو تسوس أو شرخ.\nاكشف عشان تعرف السبب ومتعتبرش كل حساسية بسيطة.",src:"https://my.clevelandclinic.org/health/symptoms/10954-teeth-sensitivity"},{title_en:"Bleeding gums",title_ar:"نزيف اللثة",description_en:"Bleeding when brushing or cleaning between teeth can be a sign of gum disease.\nKeep cleaning gently rather than ignoring it.\nArrange a dental check, especially with sore or swollen gums.",description_ar:"نزيف اللثة مع الغسيل أو تنظيف بين الأسنان ممكن يكون علامة التهاب.\nكمل التنظيف برفق بدل ما تتجاهله.\nاحجز كشف، خصوصاً لو اللثة بتوجعك أو وارمة.",symptoms:{en:"Bleeding with brushing, red or swollen gums.",ar:"نزيف مع الفرشاة واحمرار أو ورم اللثة."},treatment:{en:"Dental examination and professional cleaning, depending on severity.",ar:"كشف وتنظيف عند الدكتور حسب شدة الحالة."},prevention:{en:"Daily cleaning between teeth, fluoride brushing and avoiding smoking.",ar:"تنظيف يومي بين الأسنان ومعجون فلورايد وتجنب التدخين."},category:"Gum disease",source_name:"NHS",source_url:"https://www.nhs.uk/conditions/gum-disease/",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Bleeding gums",ar:"نزيف اللثة",sen:"Bleeding when brushing or cleaning between teeth can be a sign of gum disease.\nKeep cleaning gently rather than ignoring it.\nArrange a dental check, especially with sore or swollen gums.",sar:"نزيف اللثة مع الغسيل أو تنظيف بين الأسنان ممكن يكون علامة التهاب.\nكمل التنظيف برفق بدل ما تتجاهله.\nاحجز كشف، خصوصاً لو اللثة بتوجعك أو وارمة.",cat:"Gum disease",src:"https://www.nhs.uk/conditions/gum-disease/"},{title_en:"Gum inflammation (gingivitis)",title_ar:"التهاب اللثة",description_en:"Plaque can build up and irritate the gums.\nGums may become red, swollen and bleed easily.\nA dentist can check the cause and recommend cleaning and care.",description_ar:"البلاك ممكن يتراكم ويهيج اللثة.\nاللثة ممكن تحمر وتتورم وتنزف بسهولة.\nالدكتور بيكشف السبب ويحدد التنظيف والعناية المناسبة.",symptoms:{en:"Red, sore, swollen or bleeding gums.",ar:"لثة حمرا أو مؤلمة أو وارمة أو بتنـزف."},treatment:{en:"Professional cleaning and advice on daily oral hygiene.",ar:"تنظيف عند الدكتور وإرشادات للعناية اليومية."},prevention:{en:"Brush twice a day and clean between teeth daily.",ar:"اغسل مرتين يومياً ونضف بين الأسنان كل يوم."},category:"Gum disease",source_name:"NHS",source_url:"https://www.nhs.uk/conditions/gum-disease/",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Gum inflammation (gingivitis)",ar:"التهاب اللثة",sen:"Plaque can build up and irritate the gums.\nGums may become red, swollen and bleed easily.\nA dentist can check the cause and recommend cleaning and care.",sar:"البلاك ممكن يتراكم ويهيج اللثة.\nاللثة ممكن تحمر وتتورم وتنزف بسهولة.\nالدكتور بيكشف السبب ويحدد التنظيف والعناية المناسبة.",cat:"Gum disease",src:"https://www.nhs.uk/conditions/gum-disease/"},{title_en:"Periodontitis",title_ar:"التهاب دواعم الأسنان",description_en:"Periodontitis damages tissues supporting the teeth.\nIt may lead to bone loss and loose teeth, sometimes with little pain.\nProfessional treatment and long-term maintenance are needed.",description_ar:"التهاب دواعم الأسنان بيضر الأنسجة اللي بتدعم السن.\nممكن يسبب فقدان عظم وحركة الأسنان وأحياناً من غير ألم واضح.\nمحتاج علاج عند مختص وعناية ومتابعة مستمرة.",symptoms:{en:"Bleeding or swollen gums, bad breath, recession or loose teeth.",ar:"نزيف أو ورم لثة أو رائحة فم أو انحسار أو حركة أسنان."},treatment:{en:"Deep cleaning or gum surgery depending on severity.",ar:"تنظيف عميق أو جراحة لثة حسب الشدة."},prevention:{en:"Maintain daily cleaning and personalised professional maintenance.",ar:"حافظ على التنظيف اليومي والمتابعة المهنية حسب حالتك."},category:"Gum disease",source_name:"Cleveland Clinic",source_url:"https://my.clevelandclinic.org/health/diseases/16620-periodontitis",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Periodontitis",ar:"التهاب دواعم الأسنان",cat:"Gum disease",sen:"Periodontitis damages tissues supporting the teeth.\nIt may lead to bone loss and loose teeth, sometimes with little pain.\nProfessional treatment and long-term maintenance are needed.",sar:"التهاب دواعم الأسنان بيضر الأنسجة اللي بتدعم السن.\nممكن يسبب فقدان عظم وحركة الأسنان وأحياناً من غير ألم واضح.\nمحتاج علاج عند مختص وعناية ومتابعة مستمرة.",src:"https://my.clevelandclinic.org/health/diseases/16620-periodontitis"},{title_en:"Cavities (tooth decay)",title_ar:"تسوس الأسنان",description_en:"Tooth decay can begin without pain and later form a hole.\nA dentist may use fluoride for early decay or a filling for a cavity.\nDo not wait for pain before getting a suspected cavity checked.",description_ar:"التسوس ممكن يبدأ من غير وجع وبعدها يعمل حفرة في السن.\nالدكتور ممكن يستخدم فلورايد للتسوس المبكر أو حشو لو فيه حفرة.\nمتستناش الألم لو شاكك إن عندك تسوس.",symptoms:{en:"Sensitivity, toothache or white, brown or black marks; sometimes no symptoms.",ar:"حساسية أو وجع أو بقع بيضا أو بنية أو سودا؛ وأحياناً من غير أعراض."},treatment:{en:"Fluoride, filling, root canal or extraction depending on how far decay has spread.",ar:"فلورايد أو حشو أو علاج جذور أو خلع حسب عمق التسوس."},prevention:{en:"Fluoride toothpaste, daily interdental cleaning, fewer sugary foods and regular checks.",ar:"معجون فلورايد وتنظيف بين الأسنان وتقليل السكر وكشوف منتظمة."},category:"Prevention",source_name:"NHS",source_url:"https://www.nhs.uk/conditions/tooth-decay/",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Cavities (tooth decay)",ar:"تسوس الأسنان",sen:"Tooth decay can begin without pain and later form a hole.\nA dentist may use fluoride for early decay or a filling for a cavity.\nDo not wait for pain before getting a suspected cavity checked.",sar:"التسوس ممكن يبدأ من غير وجع وبعدها يعمل حفرة في السن.\nالدكتور ممكن يستخدم فلورايد للتسوس المبكر أو حشو لو فيه حفرة.\nمتستناش الألم لو شاكك إن عندك تسوس.",cat:"Prevention",src:"https://www.nhs.uk/conditions/tooth-decay/"},{title_en:"Tooth erosion",title_ar:"تآكل الأسنان",description_en:"Enamel can gradually wear thin and cannot grow back once lost.\nAcidic drinks, reflux and other factors may contribute.\nSee a dentist for sensitivity, chips or changes in tooth colour.",description_ar:"المينا ممكن تترقق تدريجياً ومش بترجع تنمو بعد فقدانها.\nالمشروبات الحمضية والارتجاع وعوامل تانية ممكن تساهم.\nاكشف لو فيه حساسية أو تكسر أو تغير في لون الأسنان.",symptoms:{en:"Sensitivity, discoloration, chips or small pits.",ar:"حساسية أو تغير لون أو تكسر أو حفر صغيرة."},treatment:{en:"A dentist may use fluoride, bonding or restorations according to damage.",ar:"الدكتور ممكن يستخدم فلورايد أو ترميم حسب الضرر."},prevention:{en:"Limit acids, use fluoride toothpaste and avoid aggressive brushing.",ar:"قلل الأحماض واستخدم معجون فلورايد ومتغسلش بعنف."},category:"Oral health",source_name:"Cleveland Clinic",source_url:"https://my.clevelandclinic.org/health/diseases/tooth-erosion",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Tooth erosion",ar:"تآكل الأسنان",cat:"Oral health",sen:"Enamel can gradually wear thin and cannot grow back once lost.\nAcidic drinks, reflux and other factors may contribute.\nSee a dentist for sensitivity, chips or changes in tooth colour.",sar:"المينا ممكن تترقق تدريجياً ومش بترجع تنمو بعد فقدانها.\nالمشروبات الحمضية والارتجاع وعوامل تانية ممكن تساهم.\nاكشف لو فيه حساسية أو تكسر أو تغير في لون الأسنان.",src:"https://my.clevelandclinic.org/health/diseases/tooth-erosion"},{title_en:"Dental abscess",title_ar:"خراج الأسنان",description_en:"An abscess is a build-up of pus caused by infection.\nIt needs urgent dental treatment and will not go away on its own.\nTrouble breathing or swallowing, eye swelling or major mouth swelling needs emergency care.",description_ar:"الخراج تجمع صديد بسبب عدوى.\nمحتاج علاج أسنان عاجل ومش بيختفي لوحده.\nصعوبة التنفس أو البلع أو ورم العين أو ورم شديد بالفم محتاج طوارئ.",symptoms:{en:"Severe tooth or gum pain, bad taste, swelling or fever.",ar:"وجع شديد في السن أو اللثة وطعم وحش أو ورم أو حرارة."},treatment:{en:"A dentist may drain the infection and treat the tooth with root canal or extraction.",ar:"الدكتور ممكن يصرف الصديد ويعالج السن بعلاج جذور أو خلع."},prevention:{en:"Clean teeth and between teeth daily and attend regular dental checks.",ar:"نضف أسنانك وبينها يومياً وتابع عند دكتور الأسنان."},category:"Emergency",source_name:"NHS",source_url:"https://www.nhs.uk/conditions/dental-abscess/",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Dental abscess",ar:"خراج الأسنان",sen:"An abscess is a build-up of pus caused by infection.\nIt needs urgent dental treatment and will not go away on its own.\nTrouble breathing or swallowing, eye swelling or major mouth swelling needs emergency care.",sar:"الخراج تجمع صديد بسبب عدوى.\nمحتاج علاج أسنان عاجل ومش بيختفي لوحده.\nصعوبة التنفس أو البلع أو ورم العين أو ورم شديد بالفم محتاج طوارئ.",cat:"Emergency",src:"https://www.nhs.uk/conditions/dental-abscess/"},{title_en:"Wisdom teeth",title_ar:"ضرس العقل",description_en:"Wisdom teeth grow at the back of the mouth.\nA tooth with little space may cause pain, swelling or gum infection.\nTeeth causing no problems are usually monitored rather than automatically removed.",description_ar:"ضروس العقل بتطلع في آخر الفم.\nلو المساحة قليلة ممكن تسبب وجع أو ورم أو التهاب لثة.\nلو مش عاملة مشكلة، غالباً بتحتاج متابعة مش خلع تلقائي.",symptoms:{en:"Pain, swollen gum or food trapping around the back tooth.",ar:"وجع أو لثة وارمة أو أكل بيتحشر حوالين الضرس الخلفي."},treatment:{en:"A dentist may check the position with X-rays and advise monitoring or removal.",ar:"الدكتور ممكن يطلب أشعة ويحدد المتابعة أو الخلع."},prevention:{en:"Keep the area clean and have the tooth checked during routine visits.",ar:"حافظ على نظافة المنطقة وافحص الضرس في المتابعة الدورية."},category:"Surgery",source_name:"NHS",source_url:"https://www.nhs.uk/tests-and-treatments/wisdom-tooth-removal/",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Wisdom teeth",ar:"ضرس العقل",sen:"Wisdom teeth grow at the back of the mouth.\nA tooth with little space may cause pain, swelling or gum infection.\nTeeth causing no problems are usually monitored rather than automatically removed.",sar:"ضروس العقل بتطلع في آخر الفم.\nلو المساحة قليلة ممكن تسبب وجع أو ورم أو التهاب لثة.\nلو مش عاملة مشكلة، غالباً بتحتاج متابعة مش خلع تلقائي.",cat:"Surgery",src:"https://www.nhs.uk/tests-and-treatments/wisdom-tooth-removal/"},{title_en:"Impacted tooth",title_ar:"السن المدفون",description_en:"An impacted tooth remains trapped in gum tissue or jawbone.\nIt may cause symptoms or be found on a routine examination.\nNot every impacted tooth needs removal; the dentist assesses its risks.",description_ar:"السن المدفون بيبقى محبوس في اللثة أو عظم الفك.\nممكن يسبب أعراض أو يظهر في كشف دوري.\nمش كل سن مدفون لازم يتشال والدكتور بيقيم مخاطره.",symptoms:{en:"Pain, swelling, bad taste or difficulty opening the mouth; sometimes no symptoms.",ar:"ألم أو ورم أو طعم سيئ أو صعوبة فتح الفم وأحياناً من غير أعراض."},treatment:{en:"Monitoring, removal or help with eruption depending on the tooth.",ar:"متابعة أو خلع أو مساعدة على البزوغ حسب السن."},prevention:{en:"Impaction is not usually preventable; regular checks help detect complications.",ar:"الانطمار غالباً مش ممكن منعه والكشف بيساعد يكتشف مضاعفاته."},category:"Surgery",source_name:"Cleveland Clinic",source_url:"https://my.clevelandclinic.org/health/diseases/impacted-tooth",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Impacted tooth",ar:"السن المدفون",cat:"Surgery",sen:"An impacted tooth remains trapped in gum tissue or jawbone.\nIt may cause symptoms or be found on a routine examination.\nNot every impacted tooth needs removal; the dentist assesses its risks.",sar:"السن المدفون بيبقى محبوس في اللثة أو عظم الفك.\nممكن يسبب أعراض أو يظهر في كشف دوري.\nمش كل سن مدفون لازم يتشال والدكتور بيقيم مخاطره.",src:"https://my.clevelandclinic.org/health/diseases/impacted-tooth"},{title_en:"Teeth grinding (bruxism)",title_ar:"جز على الأسنان",description_en:"Grinding or clenching can happen while awake or asleep.\nIt may be linked to stress, sleep problems or other factors.\nA dentist should check tooth damage, sensitivity or jaw pain.",description_ar:"الجز أو الضغط على الأسنان ممكن يحصل وإنت صاحي أو نايم.\nممكن يرتبط بالتوتر أو مشاكل النوم أو عوامل تانية.\nاكشف لو فيه تآكل أو حساسية أو ألم بالفك.",symptoms:{en:"Worn or broken teeth, jaw pain, headaches or disturbed sleep.",ar:"تآكل أو كسر الأسنان أو وجع فك أو صداع أو نوم متقطع."},treatment:{en:"A dentist may recommend a fitted guard to protect teeth; other care addresses triggers.",ar:"الدكتور ممكن يوصي بواقي مناسب لحماية الأسنان مع التعامل مع العوامل المسببة."},prevention:{en:"Work on relaxation and sleep habits and reduce excess caffeine.",ar:"اهتم بالاسترخاء وعادات النوم وقلل الكافيين الزيادة."},category:"Oral health",source_name:"NHS",source_url:"https://www.nhs.uk/symptoms/teeth-grinding/",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Teeth grinding (bruxism)",ar:"جز على الأسنان",cat:"Oral health",sen:"Grinding or clenching can happen while awake or asleep.\nIt may be linked to stress, sleep problems or other factors.\nA dentist should check tooth damage, sensitivity or jaw pain.",sar:"الجز أو الضغط على الأسنان ممكن يحصل وإنت صاحي أو نايم.\nممكن يرتبط بالتوتر أو مشاكل النوم أو عوامل تانية.\nاكشف لو فيه تآكل أو حساسية أو ألم بالفك.",src:"https://www.nhs.uk/symptoms/teeth-grinding/"},{title_en:"Jaw clicking and TMD",title_ar:"طقطقة الفك واضطراب المفصل",description_en:"Jaw joint problems can cause clicking, pain or restricted movement.\nSoft foods and avoiding very wide opening may ease symptoms.\nSeek prompt medical advice for locking, trouble eating or drinking, or significant pain.",description_ar:"مشاكل مفصل الفك ممكن تسبب طقطقة أو ألم أو صعوبة حركة.\nالأكل الطري وتجنب فتح الفم بقوة ممكن يساعدوا.\nاطلب تقييم طبي سريع لو الفك بيقفل أو الأكل والشرب صعبين أو فيه ألم واضح.",symptoms:{en:"Clicking, pain around the jaw or ear, limited opening or locking.",ar:"طقطقة أو ألم حوالين الفك والأذن أو قلة فتح الفم أو قفل الفك."},treatment:{en:"A clinician assesses the cause; dental, physiotherapy or other care may be advised.",ar:"الطبيب بيقيم السبب وممكن ينصح بعلاج أسنان أو علاج طبيعي أو رعاية تانية."},prevention:{en:"Avoid gum chewing, nail biting and clenching; try relaxation.",ar:"تجنب اللبان وقضم الأظافر والضغط على الأسنان وجرب الاسترخاء."},category:"Oral health",source_name:"NHS",source_url:"https://www.nhs.uk/conditions/temporomandibular-disorder-tmd/",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Jaw clicking and TMD",ar:"طقطقة الفك واضطراب المفصل",cat:"Oral health",sen:"Jaw joint problems can cause clicking, pain or restricted movement.\nSoft foods and avoiding very wide opening may ease symptoms.\nSeek prompt medical advice for locking, trouble eating or drinking, or significant pain.",sar:"مشاكل مفصل الفك ممكن تسبب طقطقة أو ألم أو صعوبة حركة.\nالأكل الطري وتجنب فتح الفم بقوة ممكن يساعدوا.\nاطلب تقييم طبي سريع لو الفك بيقفل أو الأكل والشرب صعبين أو فيه ألم واضح.",src:"https://www.nhs.uk/conditions/temporomandibular-disorder-tmd/"},{title_en:"Bad breath",title_ar:"رائحة الفم",description_en:"Bad breath can be related to food, smoking or problems with teeth and gums.\nCleaning teeth, tongue and between teeth regularly can help.\nSee a dentist if it continues for a few weeks despite good care.",description_ar:"رائحة الفم ممكن ترتبط بالأكل أو التدخين أو مشاكل الأسنان واللثة.\nتنظيف الأسنان واللسان وبين الأسنان بانتظام ممكن يساعد.\nاكشف لو الرائحة مستمرة لأسابيع رغم العناية.",symptoms:{en:"Persistent unpleasant breath, sometimes with gum or tooth problems.",ar:"رائحة مستمرة وأحياناً معاها مشاكل لثة أو أسنان."},treatment:{en:"A dentist checks for dental causes and recommends appropriate care.",ar:"الدكتور بيفحص أسباب الأسنان ويحدد العناية المناسبة."},prevention:{en:"Brush gently twice daily, clean the tongue and between teeth, and avoid smoking.",ar:"اغسل برفق مرتين ونضف اللسان وبين الأسنان وتجنب التدخين."},category:"Oral health",source_name:"NHS",source_url:"https://www.nhs.uk/symptoms/bad-breath/",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Bad breath",ar:"رائحة الفم",cat:"Oral health",sen:"Bad breath can be related to food, smoking or problems with teeth and gums.\nCleaning teeth, tongue and between teeth regularly can help.\nSee a dentist if it continues for a few weeks despite good care.",sar:"رائحة الفم ممكن ترتبط بالأكل أو التدخين أو مشاكل الأسنان واللثة.\nتنظيف الأسنان واللسان وبين الأسنان بانتظام ممكن يساعد.\nاكشف لو الرائحة مستمرة لأسابيع رغم العناية.",src:"https://www.nhs.uk/symptoms/bad-breath/"},{title_en:"Dry mouth",title_ar:"جفاف الفم",description_en:"Dry mouth may be linked to dehydration, medicines or mouth breathing.\nRegular sips of water and sugar-free gum may help.\nIf it persists or makes eating difficult, see a clinician; do not stop prescribed medicine yourself.",description_ar:"جفاف الفم ممكن يرتبط بقلة الميه أو أدوية أو التنفس من الفم.\nرشفات ميه متكررة ولبان خالي من السكر ممكن يساعدوا.\nلو مستمر أو بيصعب الأكل راجع طبيب، ومتوقفش دواء موصوف من نفسك.",symptoms:{en:"Dry mouth, difficulty eating or speaking, or altered taste.",ar:"جفاف وصعوبة أكل أو كلام أو تغير التذوق."},treatment:{en:"A clinician checks the cause; a pharmacist can advise on suitable saliva substitutes.",ar:"الطبيب يراجع السبب والصيدلي ممكن ينصح ببدائل لعاب مناسبة."},prevention:{en:"Stay hydrated, avoid smoking and keep up fluoride brushing.",ar:"اشرب ميه وتجنب التدخين وحافظ على الغسيل بمعجون فلورايد."},category:"Oral health",source_name:"NHS",source_url:"https://www.nhs.uk/symptoms/dry-mouth/",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Dry mouth",ar:"جفاف الفم",sen:"Dry mouth may be linked to dehydration, medicines or mouth breathing.\nRegular sips of water and sugar-free gum may help.\nIf it persists or makes eating difficult, see a clinician; do not stop prescribed medicine yourself.",sar:"جفاف الفم ممكن يرتبط بقلة الميه أو أدوية أو التنفس من الفم.\nرشفات ميه متكررة ولبان خالي من السكر ممكن يساعدوا.\nلو مستمر أو بيصعب الأكل راجع طبيب، ومتوقفش دواء موصوف من نفسك.",cat:"Oral health",src:"https://www.nhs.uk/symptoms/dry-mouth/"},{title_en:"Mouth ulcers",title_ar:"تقرحات الفم",description_en:"Most mouth ulcers settle within one or two weeks.\nSoft foods and avoiding spicy or acidic food can reduce irritation.\nSee a dentist or doctor for an ulcer lasting over three weeks or becoming unusual, red or painful.",description_ar:"معظم قرح الفم بتخف خلال أسبوع أو اتنين.\nالأكل الطري وتجنب الحار والحمضي ممكن يقللوا التهيج.\nاكشف لو القرحة فضلت أكتر من ٣ أسابيع أو بقت مختلفة أو أشد احمراراً وألماً.",symptoms:{en:"Painful sores inside the lips, cheeks or on the tongue.",ar:"قرح مؤلمة جوه الشفايف أو الخد أو على اللسان."},treatment:{en:"Gentle care; a pharmacist or clinician can advise on symptom relief.",ar:"عناية برفق، والصيدلي أو الطبيب يحدد وسيلة مناسبة لتخفيف الألم."},prevention:{en:"Avoid repeated mouth injury and get rough teeth or poorly fitting dentures checked.",ar:"تجنب جرح الفم المتكرر واكشف على أي سن حاد أو طقم مش مناسب."},category:"Oral health",source_name:"NHS",source_url:"https://www.nhs.uk/conditions/mouth-ulcers/",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Mouth ulcers",ar:"تقرحات الفم",sen:"Most mouth ulcers settle within one or two weeks.\nSoft foods and avoiding spicy or acidic food can reduce irritation.\nSee a dentist or doctor for an ulcer lasting over three weeks or becoming unusual, red or painful.",sar:"معظم قرح الفم بتخف خلال أسبوع أو اتنين.\nالأكل الطري وتجنب الحار والحمضي ممكن يقللوا التهيج.\nاكشف لو القرحة فضلت أكتر من ٣ أسابيع أو بقت مختلفة أو أشد احمراراً وألماً.",cat:"Oral health",src:"https://www.nhs.uk/conditions/mouth-ulcers/"},{title_en:"Cold sores",title_ar:"قرح البرد",description_en:"Cold sores are caused by herpes simplex virus.\nTingling may be followed by painful small blisters and a crust.\nThey should start healing within ten days; seek advice if severe or not improving.",description_ar:"قرح البرد سببها فيروس الهربس البسيط.\nالوخز ممكن يتبعه فقاقيع صغيرة مؤلمة وبعدها قشرة.\nالمفروض تبدأ تلتئم خلال عشرة أيام؛ اطلب نصيحة لو شديدة أو مش بتتحسن.",symptoms:{en:"Tingling, itching, burning or blisters near the lips.",ar:"وخز أو حكة أو حرقان أو فقاقيع قرب الشفايف."},treatment:{en:"A pharmacist can advise on symptom care or antiviral creams.",ar:"الصيدلي يقدر ينصح بعناية الأعراض أو كريم مضاد فيروسات."},prevention:{en:"Avoid kissing while contagious, especially babies; wash hands after touching.",ar:"متبوسش حد وقت العدوى خصوصاً الرضع واغسل إيدك بعد اللمس."},category:"Oral health",source_name:"NHS",source_url:"https://www.nhs.uk/conditions/cold-sores/",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Cold sores",ar:"قرح البرد",cat:"Oral health",sen:"Cold sores are caused by herpes simplex virus.\nTingling may be followed by painful small blisters and a crust.\nThey should start healing within ten days; seek advice if severe or not improving.",sar:"قرح البرد سببها فيروس الهربس البسيط.\nالوخز ممكن يتبعه فقاقيع صغيرة مؤلمة وبعدها قشرة.\nالمفروض تبدأ تلتئم خلال عشرة أيام؛ اطلب نصيحة لو شديدة أو مش بتتحسن.",src:"https://www.nhs.uk/conditions/cold-sores/"},{title_en:"Oral thrush",title_ar:"فطريات الفم",description_en:"Oral thrush is a fungal infection that can cause white patches and soreness.\nIn adults, patches may leave red areas that bleed when wiped away.\nAsk a clinician or pharmacist about diagnosis and appropriate treatment.",description_ar:"فطريات الفم عدوى فطرية ممكن تعمل بقع بيضاء وألم.\nعند الكبار البقع ممكن تسيب مكان أحمر بينزف لما تتمسح.\nاسأل طبيب أو صيدلي عن التشخيص والعلاج المناسب.",symptoms:{en:"White patches, a red sore mouth or altered taste.",ar:"بقع بيضاء أو فم أحمر مؤلم أو تغير الطعم."},treatment:{en:"Antifungal treatment may be needed; seek medical advice for painful swallowing or weak immunity.",ar:"ممكن تحتاج مضاد فطريات؛ اطلب نصيحة طبية لو البلع مؤلم أو المناعة ضعيفة."},prevention:{en:"Clean teeth and dentures, remove dentures at night and do not smoke.",ar:"نضف الأسنان والأطقم وشيل الطقم بالليل ومتدخنش."},category:"Oral health",source_name:"NHS",source_url:"https://www.nhs.uk/conditions/oral-thrush-mouth-thrush/",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Oral thrush",ar:"فطريات الفم",cat:"Oral health",sen:"Oral thrush is a fungal infection that can cause white patches and soreness.\nIn adults, patches may leave red areas that bleed when wiped away.\nAsk a clinician or pharmacist about diagnosis and appropriate treatment.",sar:"فطريات الفم عدوى فطرية ممكن تعمل بقع بيضاء وألم.\nعند الكبار البقع ممكن تسيب مكان أحمر بينزف لما تتمسح.\nاسأل طبيب أو صيدلي عن التشخيص والعلاج المناسب.",src:"https://www.nhs.uk/conditions/oral-thrush-mouth-thrush/"},{title_en:"Dental plaque",title_ar:"بلاك الأسنان",description_en:"Plaque is a film of bacteria that coats teeth.\nIf not removed, it contributes to decay and gum disease.\nDaily brushing and cleaning between teeth help control plaque.",description_ar:"البلاك طبقة بكتيريا بتغطي الأسنان.\nلو متشالتش بتساهم في التسوس وأمراض اللثة.\nالغسيل والتنظيف بين الأسنان يومياً بيساعدوا يتحكموا فيها.",symptoms:{en:"Plaque can build up without pain.",ar:"البلاك ممكن يتراكم من غير ألم."},treatment:{en:"A dental professional can check cleaning and gum health.",ar:"مختص أسنان يراجع التنظيف وصحة اللثة."},prevention:{en:"Brush all surfaces twice daily with fluoride toothpaste and clean between teeth.",ar:"اغسل كل الأسطح مرتين بمعجون فلورايد ونضف بين الأسنان."},category:"Oral health",source_name:"NHS",source_url:"https://www.nhs.uk/live-well/healthy-teeth-and-gums/how-to-keep-your-teeth-clean/",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Dental plaque",ar:"بلاك الأسنان",cat:"Oral health",sen:"Plaque is a film of bacteria that coats teeth.\nIf not removed, it contributes to decay and gum disease.\nDaily brushing and cleaning between teeth help control plaque.",sar:"البلاك طبقة بكتيريا بتغطي الأسنان.\nلو متشالتش بتساهم في التسوس وأمراض اللثة.\nالغسيل والتنظيف بين الأسنان يومياً بيساعدوا يتحكموا فيها.",src:"https://www.nhs.uk/live-well/healthy-teeth-and-gums/how-to-keep-your-teeth-clean/"},{title_en:"Dental tartar",title_ar:"جير الأسنان",description_en:"Tartar is plaque that has hardened on teeth.\nBrushing and flossing cannot remove established tartar.\nA dental professional removes it safely and checks the gums.",description_ar:"الجير بلاك اتصلب على الأسنان.\nالفرشاة والخيط مش بيشيلوا الجير المتكون.\nمختص أسنان بيشيله بأمان ويفحص اللثة.",symptoms:{en:"A hard coating, stains, bad breath or bleeding gums.",ar:"طبقة صلبة أو تصبغات أو رائحة فم أو نزيف لثة."},treatment:{en:"Professional scaling, with gum treatment if needed.",ar:"إزالة جير عند مختص وعلاج لثة لو محتاج."},prevention:{en:"Brush and clean between teeth; never scrape tartar off yourself.",ar:"اغسل ونضف بين الأسنان ومتقشطش الجير بنفسك."},category:"Gum disease",source_name:"Cleveland Clinic",source_url:"https://my.clevelandclinic.org/health/diseases/25102-tartar",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Dental tartar",ar:"جير الأسنان",cat:"Gum disease",sen:"Tartar is plaque that has hardened on teeth.\nBrushing and flossing cannot remove established tartar.\nA dental professional removes it safely and checks the gums.",sar:"الجير بلاك اتصلب على الأسنان.\nالفرشاة والخيط مش بيشيلوا الجير المتكون.\nمختص أسنان بيشيله بأمان ويفحص اللثة.",src:"https://my.clevelandclinic.org/health/diseases/25102-tartar"},{title_en:"Scaling and polishing",title_ar:"تنظيف الجير والتلميع",description_en:"Routine cleaning removes plaque and tartar from tooth surfaces.\nPolishing can then smooth and clean the surfaces.\nYour dentist decides how often cleaning is needed from your risk.",description_ar:"التنظيف الدوري بيشيل البلاك والجير من أسطح الأسنان.\nالتلميع بعده ممكن ينعم وينضف الأسطح.\nالدكتور يحدد تكرار التنظيف حسب عوامل الخطورة.",symptoms:{en:"Tartar, surface staining or signs of gum inflammation.",ar:"جير أو تصبغات سطحية أو علامات التهاب لثة."},treatment:{en:"A dental professional uses suitable instruments and polishing tools.",ar:"مختص يستخدم أدوات مناسبة للتنظيف والتلميع."},prevention:{en:"Daily brushing and interdental cleaning reduce new buildup.",ar:"الفرشاة والتنظيف بين الأسنان يومياً بيقللوا التراكم الجديد."},category:"Treatment",source_name:"Cleveland Clinic",source_url:"https://my.clevelandclinic.org/health/diseases/25102-tartar",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Scaling and polishing",ar:"تنظيف الجير والتلميع",cat:"Treatment",sen:"Routine cleaning removes plaque and tartar from tooth surfaces.\nPolishing can then smooth and clean the surfaces.\nYour dentist decides how often cleaning is needed from your risk.",sar:"التنظيف الدوري بيشيل البلاك والجير من أسطح الأسنان.\nالتلميع بعده ممكن ينعم وينضف الأسطح.\nالدكتور يحدد تكرار التنظيف حسب عوامل الخطورة.",src:"https://my.clevelandclinic.org/health/diseases/25102-tartar"},{title_en:"Deep cleaning and root planing",title_ar:"التنظيف العميق وتسوية الجذور",description_en:"Deep cleaning reaches plaque and tartar below the gum line.\nRoot planing smooths the root surfaces as part of gum treatment.\nLocal anaesthesia may be used and follow-up care is important.",description_ar:"التنظيف العميق بيوصل للبلاك والجير تحت خط اللثة.\nتسوية الجذور بتنعم سطح الجذر كجزء من علاج اللثة.\nممكن يتعمل بتخدير موضعي والمتابعة مهمة.",symptoms:{en:"Bleeding, swollen gums or diagnosed periodontal disease.",ar:"لثة بتنـزف أو متورمة أو مرض دواعم أسنان متشخص."},treatment:{en:"Professional scaling and root planing based on a gum assessment.",ar:"تنظيف وتسوية جذور عند مختص بعد تقييم اللثة."},prevention:{en:"Follow aftercare and ongoing cleaning instructions.",ar:"اتبع تعليمات ما بعد العلاج والتنظيف المستمر."},category:"Treatment",source_name:"Cleveland Clinic",source_url:"https://my.clevelandclinic.org/health/treatments/23983-tooth-scaling-and-root-planing",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Deep cleaning and root planing",ar:"التنظيف العميق وتسوية الجذور",cat:"Treatment",sen:"Deep cleaning reaches plaque and tartar below the gum line.\nRoot planing smooths the root surfaces as part of gum treatment.\nLocal anaesthesia may be used and follow-up care is important.",sar:"التنظيف العميق بيوصل للبلاك والجير تحت خط اللثة.\nتسوية الجذور بتنعم سطح الجذر كجزء من علاج اللثة.\nممكن يتعمل بتخدير موضعي والمتابعة مهمة.",src:"https://my.clevelandclinic.org/health/treatments/23983-tooth-scaling-and-root-planing"},{title_en:"Dental fillings",title_ar:"حشو الأسنان",description_en:"A filling repairs a hole caused by tooth decay.\nMaterials include tooth-coloured fillings and amalgam.\nYour dentist chooses a suitable option after checking the tooth.",description_ar:"الحشو بيعالج حفرة سببها التسوس.\nفيه مواد بلون السن وفيه حشو أملجم.\nالدكتور بيحدد المادة المناسبة بعد فحص السن.",symptoms:{en:"A cavity may need repair even before it becomes painful.",ar:"الحفرة ممكن تحتاج حشو حتى قبل ما توجع."},treatment:{en:"A dentist repairs the cavity with an appropriate filling material.",ar:"الدكتور بيرمم الحفرة بمادة حشو مناسبة."},prevention:{en:"Ask your dentist how to care for the repaired tooth.",ar:"اسأل دكتورك عن العناية بالسن بعد ترميمه."},category:"Treatment",source_name:"NHS",source_url:"https://www.nhs.uk/live-well/healthy-teeth-and-gums/dental-treatments/",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Dental fillings",ar:"حشو الأسنان",sen:"A filling repairs a hole caused by tooth decay.\nMaterials include tooth-coloured fillings and amalgam.\nYour dentist chooses a suitable option after checking the tooth.",sar:"الحشو بيعالج حفرة سببها التسوس.\nفيه مواد بلون السن وفيه حشو أملجم.\nالدكتور بيحدد المادة المناسبة بعد فحص السن.",cat:"Treatment",src:"https://www.nhs.uk/live-well/healthy-teeth-and-gums/dental-treatments/"},{title_en:"Root canal treatment",title_ar:"علاج الجذور",description_en:"Root canal treatment removes infection from inside a tooth.\nThe tooth is cleaned, filled and sealed, sometimes with a crown afterward.\nKeep follow-up visits and contact your dentist if recovery is not improving.",description_ar:"علاج الجذور بيشيل العدوى من جوه السن.\nالسن بيتنضف ويتحشي ويتقفل، وأحياناً يحتاج تلبيسة بعده.\nالتزم بالمتابعة وكلم دكتورك لو التحسن مش ماشي كويس.",symptoms:{en:"An infected tooth may hurt; diagnosis requires a dental examination.",ar:"السن المصاب ممكن يوجع؛ التشخيص محتاج كشف أسنان."},treatment:{en:"The dentist removes infected pulp, cleans the canals and seals the tooth.",ar:"الدكتور بيشيل النسيج المصاب وينضف القنوات ويقفل السن."},prevention:{en:"Care for teeth and gums and attend recommended dental checks.",ar:"اعتني بالأسنان واللثة والتزم بالكشوف اللي دكتورك يحددها."},category:"Treatment",source_name:"NHS",source_url:"https://www.nhs.uk/tests-and-treatments/root-canal-treatment/",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Root canal treatment",ar:"علاج الجذور",sen:"Root canal treatment removes infection from inside a tooth.\nThe tooth is cleaned, filled and sealed, sometimes with a crown afterward.\nKeep follow-up visits and contact your dentist if recovery is not improving.",sar:"علاج الجذور بيشيل العدوى من جوه السن.\nالسن بيتنضف ويتحشي ويتقفل، وأحياناً يحتاج تلبيسة بعده.\nالتزم بالمتابعة وكلم دكتورك لو التحسن مش ماشي كويس.",cat:"Treatment",src:"https://www.nhs.uk/tests-and-treatments/root-canal-treatment/"},{title_en:"Dental crowns",title_ar:"تلبيس الأسنان",description_en:"A crown covers a weak, broken or decayed tooth.\nThe tooth usually needs reshaping before the crown is fitted.\nAsk your dentist which material suits your tooth and bite.",description_ar:"التلبيسة بتغطي سن ضعيف أو مكسور أو متسوس.\nغالباً السن بيحتاج تحضير قبل تركيبها.\nاسأل دكتورك عن المادة المناسبة للسن والعضة.",symptoms:{en:"Weak, broken or heavily damaged teeth may need protection.",ar:"السن الضعيف أو المكسور أو المتضرر ممكن يحتاج حماية."},treatment:{en:"The dentist prepares the tooth and fits a custom-made crown.",ar:"الدكتور بيحضر السن ويركب تلبيسة مصممة ليه."},prevention:{en:"Brush with fluoride toothpaste, clean between teeth and avoid chewing very hard objects.",ar:"اغسل بمعجون فلورايد ونضف بين الأسنان ومتعضش على حاجات شديدة الصلابة."},category:"Treatment",source_name:"Cleveland Clinic",source_url:"https://my.clevelandclinic.org/health/treatments/10923-dental-crowns",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Dental crowns",ar:"تلبيس الأسنان",sen:"A crown covers a weak, broken or decayed tooth.\nThe tooth usually needs reshaping before the crown is fitted.\nAsk your dentist which material suits your tooth and bite.",sar:"التلبيسة بتغطي سن ضعيف أو مكسور أو متسوس.\nغالباً السن بيحتاج تحضير قبل تركيبها.\nاسأل دكتورك عن المادة المناسبة للسن والعضة.",cat:"Treatment",src:"https://my.clevelandclinic.org/health/treatments/10923-dental-crowns"},{title_en:"Dental bridges",title_ar:"كوبري الأسنان",description_en:"A bridge is a fixed replacement for a missing tooth or teeth.\nIt is made to fit your mouth and supported by surrounding teeth.\nA dentist can explain whether a bridge is suitable for your gap.",description_ar:"الكوبري تعويض ثابت لسن مفقود أو أكتر.\nبيتعمل على مقاس فمك وبيستند على الأسنان المحيطة.\nالدكتور يشرح إذا كان مناسب للمكان الفاضي عندك.",symptoms:{en:"Missing teeth; suitability depends on a dental assessment.",ar:"أسنان مفقودة؛ الملاءمة محتاجة تقييم عند الدكتور."},treatment:{en:"Custom fitting of a fixed bridge after an examination.",ar:"كشف وبعده تجهيز وتركيب كوبري ثابت على المقاس."},prevention:{en:"Ask the dental team how to clean around and under your bridge.",ar:"اسأل فريق الأسنان عن تنظيف حوالين الكوبري وتحته."},category:"Treatment",source_name:"NHS",source_url:"https://www.nhs.uk/live-well/healthy-teeth-and-gums/dental-treatments/",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Dental bridges",ar:"كوبري الأسنان",sen:"A bridge is a fixed replacement for a missing tooth or teeth.\nIt is made to fit your mouth and supported by surrounding teeth.\nA dentist can explain whether a bridge is suitable for your gap.",sar:"الكوبري تعويض ثابت لسن مفقود أو أكتر.\nبيتعمل على مقاس فمك وبيستند على الأسنان المحيطة.\nالدكتور يشرح إذا كان مناسب للمكان الفاضي عندك.",cat:"Treatment",src:"https://www.nhs.uk/live-well/healthy-teeth-and-gums/dental-treatments/"},{title_en:"Dentures",title_ar:"أطقم الأسنان",description_en:"Dentures replace missing teeth and can be full or partial.\nThey are made to fit the gums and can be removed for cleaning.\nAsk your dentist about fit, cleaning and chewing with a new denture.",description_ar:"طقم الأسنان بيعوض الأسنان المفقودة وممكن يكون كامل أو جزئي.\nبيتعمل على مقاس اللثة وبيتـشال للتنظيف.\nاسأل الدكتور عن المقاس والتنظيف والمضغ بالطقم الجديد.",symptoms:{en:"Missing natural teeth may affect chewing.",ar:"فقدان الأسنان الطبيعية ممكن يصعب المضغ."},treatment:{en:"A dentist measures the mouth and fits a full or partial denture.",ar:"الدكتور بياخد مقاسات ويركب طقم كامل أو جزئي."},prevention:{en:"Clean removable dentures using the method recommended by the dental team.",ar:"نضف الطقم المتحرك بالطريقة اللي فريق الأسنان يوصي بيها."},category:"Treatment",source_name:"NHS",source_url:"https://www.nhs.uk/live-well/healthy-teeth-and-gums/dental-treatments/",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Dentures",ar:"أطقم الأسنان",sen:"Dentures replace missing teeth and can be full or partial.\nThey are made to fit the gums and can be removed for cleaning.\nAsk your dentist about fit, cleaning and chewing with a new denture.",sar:"طقم الأسنان بيعوض الأسنان المفقودة وممكن يكون كامل أو جزئي.\nبيتعمل على مقاس اللثة وبيتـشال للتنظيف.\nاسأل الدكتور عن المقاس والتنظيف والمضغ بالطقم الجديد.",cat:"Treatment",src:"https://www.nhs.uk/live-well/healthy-teeth-and-gums/dental-treatments/"},{title_en:"Dental implant",title_ar:"زراعة الأسنان",description_en:"A dental implant can support a replacement crown, bridge or denture.\nA titanium screw is placed in the jawbone as part of treatment.\nTreatment takes planning and more than one stage; ask a dentist about suitability.",description_ar:"زرعة الأسنان ممكن تشيل تاج أو كوبري أو طقم تعويضي.\nبيتثبت جزء من التيتانيوم في عظم الفك ضمن العلاج.\nالعلاج محتاج تخطيط ومراحل؛ اسأل دكتور الأسنان إذا كان مناسب ليك.",symptoms:{en:"Missing teeth; an examination is needed to assess replacement options.",ar:"فقدان أسنان؛ الكشف ضروري لتقييم طرق التعويض."},treatment:{en:"Planned placement of an implant and a fitted replacement tooth or teeth.",ar:"زراعة مخططة وبعدها تركيب تعويض مناسب للسن أو الأسنان."},prevention:{en:"Discuss ongoing cleaning and follow-up before choosing an implant.",ar:"ناقش التنظيف والمتابعة المطلوبة قبل اختيار الزراعة."},category:"Surgery",source_name:"NHS",source_url:"https://www.nhs.uk/live-well/healthy-teeth-and-gums/dental-treatments/",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Dental implant",ar:"زراعة الأسنان",sen:"A dental implant can support a replacement crown, bridge or denture.\nA titanium screw is placed in the jawbone as part of treatment.\nTreatment takes planning and more than one stage; ask a dentist about suitability.",sar:"زرعة الأسنان ممكن تشيل تاج أو كوبري أو طقم تعويضي.\nبيتثبت جزء من التيتانيوم في عظم الفك ضمن العلاج.\nالعلاج محتاج تخطيط ومراحل؛ اسأل دكتور الأسنان إذا كان مناسب ليك.",cat:"Surgery",src:"https://www.nhs.uk/live-well/healthy-teeth-and-gums/dental-treatments/"},{title_en:"Veneers",title_ar:"فينير الأسنان",description_en:"Veneers are thin facings used to disguise a chipped or discoloured tooth.\nSome types require a little tooth surface to be removed.\nDiscuss the benefits and tooth preparation with your dentist before deciding.",description_ar:"الفينير قشور رفيعة لتغطية لون متغير أو جزء مكسور من السن.\nبعض الأنواع بتحتاج إزالة جزء بسيط من سطح السن.\nناقش الفايدة وتحضير السن مع دكتورك قبل القرار.",symptoms:{en:"Cosmetic concerns such as discolouration or small chips.",ar:"مشكلة شكلية زي تغير اللون أو كسر بسيط."},treatment:{en:"A dentist prepares the tooth if needed and fits a thin facing.",ar:"الدكتور بيحضر السن عند اللزوم ويركب قشرة رفيعة."},prevention:{en:"Ask about alternatives and care before any tooth preparation.",ar:"اسأل عن البدائل والعناية قبل أي تحضير للسن."},category:"Cosmetic",source_name:"NHS",source_url:"https://www.nhs.uk/live-well/healthy-teeth-and-gums/dental-treatments/",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Veneers",ar:"فينير الأسنان",sen:"Veneers are thin facings used to disguise a chipped or discoloured tooth.\nSome types require a little tooth surface to be removed.\nDiscuss the benefits and tooth preparation with your dentist before deciding.",sar:"الفينير قشور رفيعة لتغطية لون متغير أو جزء مكسور من السن.\nبعض الأنواع بتحتاج إزالة جزء بسيط من سطح السن.\nناقش الفايدة وتحضير السن مع دكتورك قبل القرار.",cat:"Cosmetic",src:"https://www.nhs.uk/live-well/healthy-teeth-and-gums/dental-treatments/"},{title_en:"Teeth whitening",title_ar:"تبييض الأسنان",description_en:"Whitening lightens natural teeth using a bleaching gel.\nIt does not lighten crowns, dentures or implants.\nA dentist should check your teeth and gums first and explain temporary sensitivity risks.",description_ar:"التبييض بيفتح لون الأسنان الطبيعية بجل مخصص.\nمش بيفتح لون التيجان أو الأطقم أو الزرعات.\nالدكتور لازم يفحص الأسنان واللثة الأول ويوضح احتمال الحساسية المؤقتة.",symptoms:{en:"Stained or darker natural teeth; this is a cosmetic choice.",ar:"لون متغير أو أغمق للأسنان الطبيعية؛ ده اختيار تجميلي."},treatment:{en:"Dentist-supervised trays or in-clinic whitening after an examination.",ar:"قوالب بإشراف الدكتور أو تبييض بالعيادة بعد الكشف."},prevention:{en:"Follow your dentist’s instructions and avoid unregulated whitening.",ar:"التزم بتعليمات دكتورك وتجنب التبييض غير المضمون."},category:"Cosmetic",source_name:"NHS",source_url:"https://www.nhs.uk/tests-and-treatments/teeth-whitening/",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Teeth whitening",ar:"تبييض الأسنان",cat:"Cosmetic",sen:"Whitening lightens natural teeth using a bleaching gel.\nIt does not lighten crowns, dentures or implants.\nA dentist should check your teeth and gums first and explain temporary sensitivity risks.",sar:"التبييض بيفتح لون الأسنان الطبيعية بجل مخصص.\nمش بيفتح لون التيجان أو الأطقم أو الزرعات.\nالدكتور لازم يفحص الأسنان واللثة الأول ويوضح احتمال الحساسية المؤقتة.",src:"https://www.nhs.uk/tests-and-treatments/teeth-whitening/"},{title_en:"Metal braces",title_ar:"التقويم المعدني",description_en:"Metal brackets and a wire gradually move teeth into position.\nBraces may help crowded teeth, gaps or bite problems.\nAn orthodontist checks your teeth and plans treatment for your needs.",description_ar:"الحاصرات المعدنية والسلك بيحركوا الأسنان تدريجياً لمكانها.\nالتقويم ممكن يساعد في التزاحم والفراغات ومشاكل العضة.\nأخصائي التقويم بيفحص الأسنان ويخطط العلاج المناسب ليك.",symptoms:{en:"Crowding, gaps or difficulty chewing because of tooth position.",ar:"تزاحم أو فراغات أو صعوبة مضغ بسبب وضع الأسنان."},treatment:{en:"Fitted braces and regular orthodontic adjustments.",ar:"تركيب التقويم وتعديلات منتظمة عند الأخصائي."},prevention:{en:"Fluoride brushing, interdental cleaning and avoiding hard or sticky foods.",ar:"غسيل بالفلورايد وتنظيف بين الأسنان وتجنب الأكل الصلب واللزق."},category:"Orthodontics",source_name:"NHS",source_url:"https://www.nhs.uk/tests-and-treatments/braces/",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",legacy_source_url:"https://www.mouthhealthy.org/all-topics-a-z/braces",en:"Metal braces",ar:"التقويم المعدني",sen:"Metal brackets and a wire gradually move teeth into position.\nBraces may help crowded teeth, gaps or bite problems.\nAn orthodontist checks your teeth and plans treatment for your needs.",sar:"الحاصرات المعدنية والسلك بيحركوا الأسنان تدريجياً لمكانها.\nالتقويم ممكن يساعد في التزاحم والفراغات ومشاكل العضة.\nأخصائي التقويم بيفحص الأسنان ويخطط العلاج المناسب ليك.",cat:"Orthodontics",src:"https://www.nhs.uk/tests-and-treatments/braces/"},{title_en:"Clear aligners",title_ar:"تقويم شفاف",description_en:"Clear aligners use removable trays to move teeth gradually.\nThey need consistent daily wear and regular checks.\nAn orthodontist decides whether trays or fixed braces suit your case.",description_ar:"التقويم الشفاف قوالب متحركة بتحرك الأسنان تدريجياً.\nمحتاج التزام يومي باللبس ومتابعة منتظمة.\nالأخصائي يحدد إذا كانت القوالب أو التقويم الثابت أنسب لحالتك.",symptoms:{en:"Crowded, spaced or misaligned teeth.",ar:"تزاحم أو فراغات أو عدم انتظام الأسنان."},treatment:{en:"A series of custom trays following an orthodontic assessment.",ar:"قوالب على المقاس بعد تقييم التقويم."},prevention:{en:"Clean trays daily and follow the prescribed wear schedule.",ar:"نضف القوالب يومياً والتزم بجدول اللبس المحدد."},category:"Orthodontics",source_name:"Cleveland Clinic",source_url:"https://my.clevelandclinic.org/health/treatments/24601-teeth-braces",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Clear aligners",ar:"تقويم شفاف",cat:"Orthodontics",sen:"Clear aligners use removable trays to move teeth gradually.\nThey need consistent daily wear and regular checks.\nAn orthodontist decides whether trays or fixed braces suit your case.",sar:"التقويم الشفاف قوالب متحركة بتحرك الأسنان تدريجياً.\nمحتاج التزام يومي باللبس ومتابعة منتظمة.\nالأخصائي يحدد إذا كانت القوالب أو التقويم الثابت أنسب لحالتك.",src:"https://my.clevelandclinic.org/health/treatments/24601-teeth-braces"},{title_en:"Retainers",title_ar:"مثبت التقويم",description_en:"A retainer helps keep teeth in place after braces are removed.\nWithout it, teeth may move back toward their old position.\nFollow the wear schedule your orthodontist gives you.",description_ar:"المثبت بيساعد الأسنان تفضل في مكانها بعد فك التقويم.\nمن غيره الأسنان ممكن تتحرك ناحية وضعها القديم.\nالتزم بجدول اللبس اللي أخصائي التقويم يحدده.",symptoms:{en:"Teeth may shift after active orthodontic treatment.",ar:"الأسنان ممكن تتحرك بعد انتهاء علاج التقويم."},treatment:{en:"Use a prescribed retainer after braces.",ar:"استخدم المثبت الموصوف بعد التقويم."},prevention:{en:"Ask your orthodontist about wear time and care.",ar:"اسأل الأخصائي عن وقت اللبس وطريقة العناية."},category:"Orthodontics",source_name:"NHS",source_url:"https://www.nhs.uk/tests-and-treatments/braces/",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",legacy_source_url:"https://www.mouthhealthy.org/all-topics-a-z/retainers",en:"Retainers",ar:"مثبت التقويم",sen:"A retainer helps keep teeth in place after braces are removed.\nWithout it, teeth may move back toward their old position.\nFollow the wear schedule your orthodontist gives you.",sar:"المثبت بيساعد الأسنان تفضل في مكانها بعد فك التقويم.\nمن غيره الأسنان ممكن تتحرك ناحية وضعها القديم.\nالتزم بجدول اللبس اللي أخصائي التقويم يحدده.",cat:"Orthodontics",src:"https://www.nhs.uk/tests-and-treatments/braces/"},{title_en:"Tooth extraction",title_ar:"خلع الأسنان",description_en:"Extraction removes a tooth from its socket.\nIt may be needed when damage cannot be repaired or for other clinical reasons.\nThe dentist discusses the procedure, risks and any replacement needs.",description_ar:"الخلع بيشيل السن من مكانه في العظم.\nممكن يلزم لو الضرر مش قابل للإصلاح أو لأسباب علاجية تانية.\nالدكتور يناقش الخطوات والمخاطر واحتياج التعويض.",symptoms:{en:"Severe decay, fracture, impaction or advanced gum disease may lead to assessment.",ar:"تسوس شديد أو كسر أو انطمار أو مرض لثة متقدم ممكن يستدعوا تقييم."},treatment:{en:"Removal under suitable anaesthesia, sometimes by a specialist.",ar:"خلع بتخدير مناسب وأحياناً عند مختص."},prevention:{en:"Treat dental problems early and follow all extraction aftercare.",ar:"عالج المشاكل بدري واتبع تعليمات ما بعد الخلع."},category:"Surgery",source_name:"Cleveland Clinic",source_url:"https://my.clevelandclinic.org/health/treatments/22120-tooth-extraction",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Tooth extraction",ar:"خلع الأسنان",cat:"Surgery",sen:"Extraction removes a tooth from its socket.\nIt may be needed when damage cannot be repaired or for other clinical reasons.\nThe dentist discusses the procedure, risks and any replacement needs.",sar:"الخلع بيشيل السن من مكانه في العظم.\nممكن يلزم لو الضرر مش قابل للإصلاح أو لأسباب علاجية تانية.\nالدكتور يناقش الخطوات والمخاطر واحتياج التعويض.",src:"https://my.clevelandclinic.org/health/treatments/22120-tooth-extraction"},{title_en:"Dry socket",title_ar:"التهاب السنخ الجاف بعد الخلع",description_en:"A protective clot may fail to form or come away after extraction.\nExposed tissue can cause severe pain and delay healing.\nContact the dentist promptly for significant or worsening pain after extraction.",description_ar:"الجلطة الواقية ممكن متتكونش أو تتحرك بعد الخلع.\nالنسيج المكشوف ممكن يسبب وجع شديد ويأخر الالتئام.\nكلم الدكتور بسرعة لو الألم شديد أو بيزيد بعد الخلع.",symptoms:{en:"Severe socket or facial pain, unpleasant taste or bad breath.",ar:"ألم شديد بمكان الخلع أو الوجه أو طعم وحش أو رائحة فم."},treatment:{en:"A dentist may clean the socket, place a dressing and advise pain relief.",ar:"الدكتور ممكن ينضف المكان ويحط ضمادة وينصح بتسكين مناسب."},prevention:{en:"Do not smoke, use straws or rinse forcefully; follow aftercare.",ar:"متدخنش ومتستخدمش شفاط ومتتمضمضش بعنف واتبع العناية."},category:"Surgery",source_name:"Cleveland Clinic",source_url:"https://my.clevelandclinic.org/health/diseases/17731-dry-socket",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Dry socket",ar:"التهاب السنخ الجاف بعد الخلع",cat:"Surgery",sen:"A protective clot may fail to form or come away after extraction.\nExposed tissue can cause severe pain and delay healing.\nContact the dentist promptly for significant or worsening pain after extraction.",sar:"الجلطة الواقية ممكن متتكونش أو تتحرك بعد الخلع.\nالنسيج المكشوف ممكن يسبب وجع شديد ويأخر الالتئام.\nكلم الدكتور بسرعة لو الألم شديد أو بيزيد بعد الخلع.",src:"https://my.clevelandclinic.org/health/diseases/17731-dry-socket"},{title_en:"Gum recession",title_ar:"انحسار اللثة",description_en:"Receding gums uncover the roots of teeth.\nExposed roots may become sensitive and more vulnerable to decay.\nA dentist or gum specialist checks the extent and discusses monitoring or treatment.",description_ar:"انحسار اللثة بيكشف جذور الأسنان.\nالجذور المكشوفة ممكن تبقى حساسة وأكثر عرضة للتسوس.\nالدكتور أو أخصائي اللثة يقيم الدرجة ويناقش المتابعة أو العلاج.",symptoms:{en:"Visible roots, sensitive teeth or thin painful gums.",ar:"جذور ظاهرة أو حساسية أسنان أو لثة رفيعة ومؤلمة."},treatment:{en:"Some cases need monitoring; others may benefit from gum grafting.",ar:"حالات ممكن تحتاج متابعة وحالات تستفيد من ترقيع اللثة."},prevention:{en:"Avoid aggressive brushing and keep regular dental care.",ar:"تجنب الغسيل بعنف وحافظ على رعاية الأسنان المنتظمة."},category:"Gum disease",source_name:"Cleveland Clinic",source_url:"https://my.clevelandclinic.org/health/treatments/23504-gum-graft-surgery",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Gum recession",ar:"انحسار اللثة",cat:"Gum disease",sen:"Receding gums uncover the roots of teeth.\nExposed roots may become sensitive and more vulnerable to decay.\nA dentist or gum specialist checks the extent and discusses monitoring or treatment.",sar:"انحسار اللثة بيكشف جذور الأسنان.\nالجذور المكشوفة ممكن تبقى حساسة وأكثر عرضة للتسوس.\nالدكتور أو أخصائي اللثة يقيم الدرجة ويناقش المتابعة أو العلاج.",src:"https://my.clevelandclinic.org/health/treatments/23504-gum-graft-surgery"},{title_en:"Gum graft surgery",title_ar:"ترقيع اللثة",description_en:"A graft replaces missing gum tissue around exposed roots.\nTissue may come from the palate or a suitable substitute.\nThe specialist explains expected healing, bleeding, infection and graft-failure risks.",description_ar:"الترقيع بيعوض نسيج اللثة المفقود حوالين الجذور المكشوفة.\nالنسيج ممكن ييجي من سقف الفم أو بديل مناسب.\nالأخصائي يشرح الالتئام المتوقع ومخاطر النزيف والعدوى وفشل الطعم.",symptoms:{en:"Gum recession and exposed roots, sometimes with sensitivity.",ar:"انحسار لثة وجذور مكشوفة وأحياناً حساسية."},treatment:{en:"A gum specialist assesses and places tissue over the area.",ar:"أخصائي اللثة يقيم الحالة ويحط النسيج فوق المنطقة."},prevention:{en:"Follow surgical cleaning instructions and do not brush directly over the graft until cleared.",ar:"اتبع تعليمات التنظيف ومتغسلش فوق الطعم مباشرة لحد سماح الجراح."},category:"Surgery",source_name:"Cleveland Clinic",source_url:"https://my.clevelandclinic.org/health/treatments/23504-gum-graft-surgery",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Gum graft surgery",ar:"ترقيع اللثة",cat:"Surgery",sen:"A graft replaces missing gum tissue around exposed roots.\nTissue may come from the palate or a suitable substitute.\nThe specialist explains expected healing, bleeding, infection and graft-failure risks.",sar:"الترقيع بيعوض نسيج اللثة المفقود حوالين الجذور المكشوفة.\nالنسيج ممكن ييجي من سقف الفم أو بديل مناسب.\nالأخصائي يشرح الالتئام المتوقع ومخاطر النزيف والعدوى وفشل الطعم.",src:"https://my.clevelandclinic.org/health/treatments/23504-gum-graft-surgery"},{title_en:"Dental bone graft",title_ar:"ترقيع عظم الفك",description_en:"A graft adds material where jawbone is missing or thin.\nIt may prepare an area for implants or support other dental care.\nHealing takes time; a surgeon explains the material, risks and follow-up.",description_ar:"الترقيع بيضيف مادة في أماكن عظم الفك المفقود أو الضعيف.\nممكن يجهز مكان للزرعات أو يدعم علاج أسنان تاني.\nالالتئام بياخد وقت؛ الجراح يشرح المادة والمخاطر والمتابعة.",symptoms:{en:"Jawbone loss is assessed with a dental examination.",ar:"فقدان عظم الفك بيتقيم بكشف أسنان."},treatment:{en:"Planned graft placement, sometimes before implant treatment.",ar:"وضع طعم بشكل مخطط وأحياناً قبل الزراعة."},prevention:{en:"Do not smoke or disturb the site; follow the surgeon’s instructions.",ar:"متدخنش ومتعبثش بمكان الجراحة واتبع تعليمات الجراح."},category:"Surgery",source_name:"Cleveland Clinic",source_url:"https://my.clevelandclinic.org/health/treatments/21727-dental-bone-graft",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Dental bone graft",ar:"ترقيع عظم الفك",cat:"Surgery",sen:"A graft adds material where jawbone is missing or thin.\nIt may prepare an area for implants or support other dental care.\nHealing takes time; a surgeon explains the material, risks and follow-up.",sar:"الترقيع بيضيف مادة في أماكن عظم الفك المفقود أو الضعيف.\nممكن يجهز مكان للزرعات أو يدعم علاج أسنان تاني.\nالالتئام بياخد وقت؛ الجراح يشرح المادة والمخاطر والمتابعة.",src:"https://my.clevelandclinic.org/health/treatments/21727-dental-bone-graft"},{title_en:"Sinus lift",title_ar:"رفع الجيب الفكي",description_en:"Some upper-jaw implant sites need extra bone near the sinus.\nA sinus lift is one type of grafting used in selected cases.\nAsk the surgeon why it is needed and what healing and risks to expect.",description_ar:"بعض أماكن الزراعة في الفك العلوي محتاجة عظم زيادة قرب الجيب الفكي.\nرفع الجيب نوع من الترقيع لحالات مختارة.\nاسأل الجراح عن سبب الاحتياج والالتئام والمخاطر المتوقعة.",symptoms:{en:"Not a symptom-based diagnosis; imaging and assessment guide planning.",ar:"مش تشخيص بالأعراض؛ الأشعة والتقييم أساس التخطيط."},treatment:{en:"A specialist plans whether sinus augmentation is suitable.",ar:"المختص بيحدد ملاءمة رفع الجيب الفكي."},prevention:{en:"Follow graft aftercare and attend review appointments.",ar:"اتبع عناية ما بعد الترقيع والتزم بالمتابعة."},category:"Surgery",source_name:"Cleveland Clinic",source_url:"https://my.clevelandclinic.org/health/treatments/21727-dental-bone-graft",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Sinus lift",ar:"رفع الجيب الفكي",cat:"Surgery",sen:"Some upper-jaw implant sites need extra bone near the sinus.\nA sinus lift is one type of grafting used in selected cases.\nAsk the surgeon why it is needed and what healing and risks to expect.",sar:"بعض أماكن الزراعة في الفك العلوي محتاجة عظم زيادة قرب الجيب الفكي.\nرفع الجيب نوع من الترقيع لحالات مختارة.\nاسأل الجراح عن سبب الاحتياج والالتئام والمخاطر المتوقعة.",src:"https://my.clevelandclinic.org/health/treatments/21727-dental-bone-graft"},{title_en:"Fluoride",title_ar:"الفلورايد",description_en:"Fluoride exposure helps prevent tooth decay.\nTwice-daily brushing with fluoride toothpaste is a key protective habit.\nAsk your dentist about a suitable toothpaste for you or your child.",description_ar:"الفلورايد بيساعد في الوقاية من التسوس.\nالغسيل مرتين يومياً بمعجون فلورايد عادة مهمة للحماية.\nاسأل دكتورك عن المعجون المناسب ليك أو لطفلك.",symptoms:{en:"Prevention is useful even without pain or visible decay.",ar:"الوقاية مهمة حتى من غير ألم أو تسوس ظاهر."},treatment:{en:"A dentist assesses decay and recommends appropriate preventive care.",ar:"الدكتور بيقيم التسوس ويوصي بالوقاية المناسبة."},prevention:{en:"Combine fluoride brushing with reducing free sugars.",ar:"اجمع غسيل الفلورايد مع تقليل السكريات الحرة."},category:"Prevention",source_name:"WHO",source_url:"https://www.who.int/news-room/fact-sheets/detail/oral-health",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Fluoride",ar:"الفلورايد",cat:"Prevention",sen:"Fluoride exposure helps prevent tooth decay.\nTwice-daily brushing with fluoride toothpaste is a key protective habit.\nAsk your dentist about a suitable toothpaste for you or your child.",sar:"الفلورايد بيساعد في الوقاية من التسوس.\nالغسيل مرتين يومياً بمعجون فلورايد عادة مهمة للحماية.\nاسأل دكتورك عن المعجون المناسب ليك أو لطفلك.",src:"https://www.who.int/news-room/fact-sheets/detail/oral-health"},{title_en:"Dental sealants",title_ar:"سد شقوق الأسنان الوقائي",description_en:"Sealants coat the grooves on the chewing surfaces of back teeth.\nThey help keep cavity-causing bacteria out of deep pits.\nA dentist checks whether a tooth is suitable and reviews the sealant later.",description_ar:"المادة الوقائية بتغطي شقوق سطح المضغ في الأسنان الخلفية.\nبتساعد تمنع بكتيريا التسوس من دخول الحفر العميقة.\nالدكتور يحدد ملاءمة السن ويراجع المادة بعد كده.",symptoms:{en:"Deep tooth grooves or a higher decay risk; pain is not required.",ar:"شقوق عميقة أو قابلية أعلى للتسوس ومش لازم يكون فيه وجع."},treatment:{en:"A clinician cleans, dries and coats the tooth then hardens the material.",ar:"المختص ينضف ويجفف السن ويحط المادة ويصلبها."},prevention:{en:"Keep brushing and cleaning between teeth; sealants are not a substitute.",ar:"كمل الغسيل والتنظيف بين الأسنان؛ المادة مش بديل للنظافة."},category:"Prevention",source_name:"Cleveland Clinic",source_url:"https://my.clevelandclinic.org/health/treatments/10912-sealants",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Dental sealants",ar:"سد شقوق الأسنان الوقائي",cat:"Prevention",sen:"Sealants coat the grooves on the chewing surfaces of back teeth.\nThey help keep cavity-causing bacteria out of deep pits.\nA dentist checks whether a tooth is suitable and reviews the sealant later.",sar:"المادة الوقائية بتغطي شقوق سطح المضغ في الأسنان الخلفية.\nبتساعد تمنع بكتيريا التسوس من دخول الحفر العميقة.\nالدكتور يحدد ملاءمة السن ويراجع المادة بعد كده.",src:"https://my.clevelandclinic.org/health/treatments/10912-sealants"},{title_en:"Dental X-rays",title_ar:"أشعة الأسنان",description_en:"Dental X-rays show areas that a visual check cannot fully assess.\nThey can help find decay, bone loss or infections and plan treatment.\nYour dentist chooses the type and timing based on clinical need.",description_ar:"أشعة الأسنان بتوضح أماكن الكشف بالنظر مش بيقيمها بالكامل.\nبتساعد في اكتشاف التسوس أو فقدان العظم أو العدوى وتخطيط العلاج.\nالدكتور يختار النوع والموعد حسب الاحتياج الطبي.",symptoms:{en:"Sometimes needed without symptoms; pain or suspected hidden disease may prompt imaging.",ar:"ممكن تلزم من غير أعراض؛ الألم أو الشك في مشكلة مخفية ممكن يستدعيها."},treatment:{en:"Imaging supports diagnosis and does not itself treat the problem.",ar:"الأشعة بتدعم التشخيص ومش بتعالج المشكلة بنفسها."},prevention:{en:"Discuss prior images and pregnancy with your dentist; avoid unnecessary repeat imaging.",ar:"ناقش الأشعة السابقة والحمل مع دكتورك وتجنب التكرار غير الضروري."},category:"Treatment",source_name:"Cleveland Clinic",source_url:"https://my.clevelandclinic.org/health/diagnostics/11199-dental-x-rays",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Dental X-rays",ar:"أشعة الأسنان",cat:"Treatment",sen:"Dental X-rays show areas that a visual check cannot fully assess.\nThey can help find decay, bone loss or infections and plan treatment.\nYour dentist chooses the type and timing based on clinical need.",sar:"أشعة الأسنان بتوضح أماكن الكشف بالنظر مش بيقيمها بالكامل.\nبتساعد في اكتشاف التسوس أو فقدان العظم أو العدوى وتخطيط العلاج.\nالدكتور يختار النوع والموعد حسب الاحتياج الطبي.",src:"https://my.clevelandclinic.org/health/diagnostics/11199-dental-x-rays"},{title_en:"Baby teeth care",title_ar:"أسنان الأطفال اللبنية",description_en:"Start brushing when the first baby tooth appears.\nA parent should help with a small, soft toothbrush and fluoride toothpaste.\nArrange the first dental visit with the first teeth or before the first birthday.",description_ar:"ابدأ تنظيف الأسنان أول ما أول سن لبني يظهر.\nالأهل يساعدوا بفرشاة صغيرة وناعمة ومعجون فلورايد.\nأول زيارة أسنان مع ظهور الأسنان الأولى أو قبل عيد الميلاد الأول.",symptoms:{en:"This is routine care, even when a child has no tooth pain.",ar:"دي عناية روتينية حتى لو الطفل مش بيشتكي من وجع."},treatment:{en:"A dentist checks early tooth development and gives prevention advice.",ar:"الدكتور بيفحص تطور الأسنان ويدي نصائح للوقاية."},prevention:{en:"Brush twice daily and supervise brushing while children learn.",ar:"غسيل مرتين يومياً والإشراف على الطفل وهو بيتعلم."},category:"Pediatric",source_name:"NHS",source_url:"https://www.nhs.uk/live-well/healthy-teeth-and-gums/taking-care-of-childrens-teeth/",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",legacy_source_url:"https://www.mouthhealthy.org/all-topics-a-z/baby-teeth",en:"Baby teeth care",ar:"أسنان الأطفال اللبنية",sen:"Start brushing when the first baby tooth appears.\nA parent should help with a small, soft toothbrush and fluoride toothpaste.\nArrange the first dental visit with the first teeth or before the first birthday.",sar:"ابدأ تنظيف الأسنان أول ما أول سن لبني يظهر.\nالأهل يساعدوا بفرشاة صغيرة وناعمة ومعجون فلورايد.\nأول زيارة أسنان مع ظهور الأسنان الأولى أو قبل عيد الميلاد الأول.",cat:"Pediatric",src:"https://www.nhs.uk/live-well/healthy-teeth-and-gums/taking-care-of-childrens-teeth/"},{title_en:"Teething",title_ar:"التسنين",description_en:"Eruption discomfort around 6 months to 3 years: drooling, gum rubbing, mild irritability. Chilled (not frozen) teething rings help; teething gels with benzocaine are not recommended for infants.",description_ar:"انزعاج بظهور الأسنان من ٦ شهور لـ٣ سنين: لعاب سايل وحك في اللثة وعصبية بسيطة. حلقة تسنين مبردة (مش مجمدة) بتريح؛ جل التسنين اللي فيه بنزوكايين مش مفضل للرضع.",symptoms:{en:"",ar:""},treatment:{en:"",ar:""},prevention:{en:"",ar:""},category:"Kids",source_name:null,source_url:null,last_updated:null,verification_status:"pending_review",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",legacy_source_url:"https://www.mouthhealthy.org/all-topics-a-z/teething",en:"Teething",ar:"التسنين",sen:"Eruption discomfort around 6 months to 3 years: drooling, gum rubbing, mild irritability. Chilled (not frozen) teething rings help; teething gels with benzocaine are not recommended for infants.",sar:"انزعاج بظهور الأسنان من ٦ شهور لـ٣ سنين: لعاب سايل وحك في اللثة وعصبية بسيطة. حلقة تسنين مبردة (مش مجمدة) بتريح؛ جل التسنين اللي فيه بنزوكايين مش مفضل للرضع.",cat:"Kids",src:null},{title_en:"Thumb sucking",title_ar:"مص الإصبع",description_en:"Normal in infants; if it continues past age 4-5 it can push front teeth forward and affect the bite. Gentle positive reinforcement works better than punishment.",description_ar:"طبيعي في الرضع؛ لو استمر بعد ٤-٥ سنين ممكن يقدم الأسنان الأمامية ويأثر على الإطباقة. التشجيع الإيجابي الهادي أفضل من العقاب.",symptoms:{en:"",ar:""},treatment:{en:"",ar:""},prevention:{en:"",ar:""},category:"Kids",source_name:null,source_url:null,last_updated:null,verification_status:"pending_review",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",legacy_source_url:"https://www.mouthhealthy.org/all-topics-a-z/thumb-sucking",en:"Thumb sucking",ar:"مص الإصبع",sen:"Normal in infants; if it continues past age 4-5 it can push front teeth forward and affect the bite. Gentle positive reinforcement works better than punishment.",sar:"طبيعي في الرضع؛ لو استمر بعد ٤-٥ سنين ممكن يقدم الأسنان الأمامية ويأثر على الإطباقة. التشجيع الإيجابي الهادي أفضل من العقاب.",cat:"Kids",src:null},{title_en:"Pregnancy and gum health",title_ar:"الحمل وصحة اللثة",description_en:"Hormonal changes during pregnancy can increase gum-disease risk.\nBleeding or swollen gums still need a dental check.\nTell the dental team about pregnancy and any medicines.",description_ar:"التغيرات الهرمونية في الحمل ممكن تزود خطورة مرض اللثة.\nنزيف أو ورم اللثة لسه محتاج كشف أسنان.\nبلغي فريق الأسنان بالحمل وأي أدوية.",symptoms:{en:"Tender, bleeding or swollen gums.",ar:"لثة مؤلمة أو بتنـزف أو متورمة."},treatment:{en:"A dental assessment guides a suitable treatment and care plan.",ar:"كشف الأسنان يحدد خطة علاج وعناية مناسبة."},prevention:{en:"Maintain oral hygiene and do not skip dental care because of pregnancy.",ar:"حافظي على نظافة الفم ومتتجاهليش رعاية الأسنان بسبب الحمل."},category:"Gum disease",source_name:"Cleveland Clinic",source_url:"https://my.clevelandclinic.org/health/diseases/16620-periodontitis",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Pregnancy and gum health",ar:"الحمل وصحة اللثة",cat:"Gum disease",sen:"Hormonal changes during pregnancy can increase gum-disease risk.\nBleeding or swollen gums still need a dental check.\nTell the dental team about pregnancy and any medicines.",sar:"التغيرات الهرمونية في الحمل ممكن تزود خطورة مرض اللثة.\nنزيف أو ورم اللثة لسه محتاج كشف أسنان.\nبلغي فريق الأسنان بالحمل وأي أدوية.",src:"https://my.clevelandclinic.org/health/diseases/16620-periodontitis"},{title_en:"Diabetes and gums",title_ar:"السكري وصحة اللثة",description_en:"Diabetes and gum disease are linked in both directions.\nGum disease may cause bleeding, swelling and eventually loose teeth.\nTell your dentist about diabetes and follow both medical and dental care.",description_ar:"السكري وأمراض اللثة بينهم ارتباط في الاتجاهين.\nمرض اللثة ممكن يسبب نزيف وورم ومع الوقت حركة الأسنان.\nبلغ دكتور الأسنان بالسكري والتزم بالمتابعة الطبية والأسنان.",symptoms:{en:"Bleeding or swollen gums, pain or loose teeth.",ar:"نزيف أو ورم اللثة أو وجع أو حركة الأسنان."},treatment:{en:"Dental assessment and coordinated care for gum disease and diabetes.",ar:"تقييم أسنان ورعاية منسقة للثة والسكري."},prevention:{en:"Maintain oral hygiene, avoid tobacco and attend regular checks.",ar:"حافظ على نظافة الفم وتجنب التبغ والتزم بالمتابعة."},category:"Gum disease",source_name:"WHO",source_url:"https://www.who.int/news-room/fact-sheets/detail/oral-health",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Diabetes and gums",ar:"السكري وصحة اللثة",cat:"Gum disease",sen:"Diabetes and gum disease are linked in both directions.\nGum disease may cause bleeding, swelling and eventually loose teeth.\nTell your dentist about diabetes and follow both medical and dental care.",sar:"السكري وأمراض اللثة بينهم ارتباط في الاتجاهين.\nمرض اللثة ممكن يسبب نزيف وورم ومع الوقت حركة الأسنان.\nبلغ دكتور الأسنان بالسكري والتزم بالمتابعة الطبية والأسنان.",src:"https://www.who.int/news-room/fact-sheets/detail/oral-health"},{title_en:"Smoking and oral health",title_ar:"التدخين وصحة الفم",description_en:"Tobacco increases the risk of gum disease and oral cancer.\nStopping tobacco supports oral and general health.\nAsk a healthcare professional for help quitting and keep dental checks.",description_ar:"التبغ بيزود خطر أمراض اللثة وسرطان الفم.\nالتوقف عنه بيدعم صحة الفم والصحة العامة.\nاطلب مساعدة مختص للإقلاع والتزم بكشوف الأسنان.",symptoms:{en:"Oral disease may not be obvious early; symptoms need assessment.",ar:"مرض الفم ممكن ميكونش واضح في البداية؛ الأعراض محتاجة تقييم."},treatment:{en:"A clinician can help with quitting and a dentist checks oral problems.",ar:"الطبيب يساعدك في الإقلاع والدكتور يفحص مشاكل الفم."},prevention:{en:"Avoid all forms of tobacco and maintain daily cleaning.",ar:"تجنب كل أشكال التبغ وحافظ على التنظيف اليومي."},category:"Prevention",source_name:"WHO",source_url:"https://www.who.int/news-room/fact-sheets/detail/oral-health",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Smoking and oral health",ar:"التدخين وصحة الفم",cat:"Prevention",sen:"Tobacco increases the risk of gum disease and oral cancer.\nStopping tobacco supports oral and general health.\nAsk a healthcare professional for help quitting and keep dental checks.",sar:"التبغ بيزود خطر أمراض اللثة وسرطان الفم.\nالتوقف عنه بيدعم صحة الفم والصحة العامة.\nاطلب مساعدة مختص للإقلاع والتزم بكشوف الأسنان.",src:"https://www.who.int/news-room/fact-sheets/detail/oral-health"},{title_en:"Oral cancer warning signs",title_ar:"علامات تستدعي فحص سرطان الفم",description_en:"An ulcer lasting more than three weeks needs a dental or medical check.\nRed or white patches, a lump or persistent mouth pain also need assessment.\nThese symptoms have many causes and do not by themselves mean cancer.",description_ar:"القرحة اللي مستمرة أكتر من تلات أسابيع محتاجة كشف أسنان أو طبي.\nالبقع الحمرا أو البيضاء أو كتلة أو ألم مستمر محتاجين تقييم برضه.\nالأعراض ليها أسباب كتير ومش معناها لوحدها وجود سرطان.",symptoms:{en:"Persistent ulcer, patch, lump, mouth pain or trouble swallowing or speaking.",ar:"قرحة مستمرة أو بقعة أو كتلة أو ألم بالفم أو صعوبة بلع أو كلام."},treatment:{en:"A clinician examines the mouth and may refer for specialist tests.",ar:"الطبيب يفحص الفم وممكن يحولك لفحوصات عند مختص."},prevention:{en:"Do not delay assessment of persistent changes.",ar:"متأجلش كشف التغيرات المستمرة."},category:"Oral health",source_name:"NHS",source_url:"https://www.nhs.uk/conditions/mouth-cancer/symptoms/",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Oral cancer warning signs",ar:"علامات تستدعي فحص سرطان الفم",cat:"Oral health",sen:"An ulcer lasting more than three weeks needs a dental or medical check.\nRed or white patches, a lump or persistent mouth pain also need assessment.\nThese symptoms have many causes and do not by themselves mean cancer.",sar:"القرحة اللي مستمرة أكتر من تلات أسابيع محتاجة كشف أسنان أو طبي.\nالبقع الحمرا أو البيضاء أو كتلة أو ألم مستمر محتاجين تقييم برضه.\nالأعراض ليها أسباب كتير ومش معناها لوحدها وجود سرطان.",src:"https://www.nhs.uk/conditions/mouth-cancer/symptoms/"},{title_en:"Jaw pain",title_ar:"ألم الفك",description_en:"Can come from the joint, chewing muscles, teeth or rarely the heart (left-sided with exertion is medical urgent). Dental causes include grinding, infection and wisdom teeth.",description_ar:"ممكن يكون من المفصل أو عضلات المضغ أو الأسنان أو نادرًا القلب (ألم ناحية الشمال مع مجهود محتاج طوارئ طبية). الأسباب السنية تشمل الصرير والتهابات وضرس العقل.",symptoms:{en:"",ar:""},treatment:{en:"",ar:""},prevention:{en:"",ar:""},category:"Jaw",source_name:null,source_url:null,last_updated:null,verification_status:"pending_review",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",legacy_source_url:"https://www.mouthhealthy.org/all-topics-a-z/jaw-pain",en:"Jaw pain",ar:"ألم الفك",sen:"Can come from the joint, chewing muscles, teeth or rarely the heart (left-sided with exertion is medical urgent). Dental causes include grinding, infection and wisdom teeth.",sar:"ممكن يكون من المفصل أو عضلات المضغ أو الأسنان أو نادرًا القلب (ألم ناحية الشمال مع مجهود محتاج طوارئ طبية). الأسباب السنية تشمل الصرير والتهابات وضرس العقل.",cat:"Jaw",src:null},{title_en:"Chipped or broken tooth",title_ar:"سن مكسور أو مشروخ",description_en:"A chipped, cracked or broken tooth needs a dental check.\nKeep a broken fragment in milk or saliva and take it with you.\nThe dentist may reattach it or use a filling, crown or root canal treatment.",description_ar:"السن المكسور أو المشروخ محتاج كشف أسنان.\nاحفظ الجزء المكسور في لبن أو لعاب وخده معاك.\nالدكتور ممكن يلزقه أو يستخدم حشوة أو تلبيسة أو علاج جذور.",symptoms:{en:"A missing piece, a crack or a rough broken edge.",ar:"جزء ناقص أو شرخ أو حافة مكسورة خشنة."},treatment:{en:"Dental examination and restoration based on the depth of damage.",ar:"كشف وترميم حسب عمق الضرر."},prevention:{en:"Keep the fragment safe and do not try household glue.",ar:"احفظ الجزء بأمان ومتستخدمش لزق منزلي."},category:"Emergency",source_name:"NHS",source_url:"https://www.nhs.uk/conditions/chipped-broken-or-cracked-tooth/",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Chipped or broken tooth",ar:"سن مكسور أو مشروخ",cat:"Emergency",sen:"A chipped, cracked or broken tooth needs a dental check.\nKeep a broken fragment in milk or saliva and take it with you.\nThe dentist may reattach it or use a filling, crown or root canal treatment.",sar:"السن المكسور أو المشروخ محتاج كشف أسنان.\nاحفظ الجزء المكسور في لبن أو لعاب وخده معاك.\nالدكتور ممكن يلزقه أو يستخدم حشوة أو تلبيسة أو علاج جذور.",src:"https://www.nhs.uk/conditions/chipped-broken-or-cracked-tooth/"},{title_en:"Knocked-out adult tooth",title_ar:"خروج سن دائم بالكامل بعد إصابة",description_en:"A knocked-out adult tooth is a dental emergency.\nHold the crown, not the root; if not replaced, keep it in milk or saliva.\nSee a dentist immediately, even if you cannot find the tooth.",description_ar:"خروج سن دائم بالكامل حالة طوارئ أسنان.\nامسك التاج مش الجذر؛ لو مش راجع مكانه احفظه في لبن أو لعاب.\nروح لدكتور أسنان فوراً حتى لو مش لاقي السن.",symptoms:{en:"A permanent tooth is completely out of its socket after injury.",ar:"سن دائم خرج بالكامل من مكانه بعد إصابة."},treatment:{en:"A dentist may reposition and splint the tooth and arrange follow-up care.",ar:"الدكتور ممكن يرجع السن ويثبته ويرتب متابعة."},prevention:{en:"Handle gently, avoid touching the root and never reinsert a baby tooth.",ar:"اتعامل برفق ومتلمسش الجذر ومترجعش سن لبني مكانه أبداً."},category:"Emergency",source_name:"NHS",source_url:"https://www.nhs.uk/conditions/knocked-out-tooth/",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Knocked-out adult tooth",ar:"خروج سن دائم بالكامل بعد إصابة",cat:"Emergency",sen:"A knocked-out adult tooth is a dental emergency.\nHold the crown, not the root; if not replaced, keep it in milk or saliva.\nSee a dentist immediately, even if you cannot find the tooth.",sar:"خروج سن دائم بالكامل حالة طوارئ أسنان.\nامسك التاج مش الجذر؛ لو مش راجع مكانه احفظه في لبن أو لعاب.\nروح لدكتور أسنان فوراً حتى لو مش لاقي السن.",src:"https://www.nhs.uk/conditions/knocked-out-tooth/"},{title_en:"Loose adult tooth",title_ar:"حركة سن دائم",description_en:"A loose adult tooth needs a dental examination.\nLoss of supporting gum tissue and bone can be one cause.\nTreatment depends on the cause and how much support remains.",description_ar:"حركة السن الدائم محتاجة كشف أسنان.\nفقدان نسيج اللثة والعظم الداعم ممكن يكون سبب.\nالعلاج حسب السبب وكمية الدعم المتبقية.",symptoms:{en:"A wobbly permanent tooth, sometimes with gum bleeding or chewing pain.",ar:"سن دائم بيتحرك وأحياناً مع نزيف لثة أو ألم مضغ."},treatment:{en:"The dentist checks gums, bone support and the tooth.",ar:"الدكتور يفحص اللثة والعظم الداعم والسن."},prevention:{en:"Do not ignore movement; keep up cleaning and dental reviews.",ar:"متتجاهلش الحركة وحافظ على التنظيف والمتابعة."},category:"Gum disease",source_name:"Cleveland Clinic",source_url:"https://my.clevelandclinic.org/health/diseases/16620-periodontitis",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Loose adult tooth",ar:"حركة سن دائم",cat:"Gum disease",sen:"A loose adult tooth needs a dental examination.\nLoss of supporting gum tissue and bone can be one cause.\nTreatment depends on the cause and how much support remains.",sar:"حركة السن الدائم محتاجة كشف أسنان.\nفقدان نسيج اللثة والعظم الداعم ممكن يكون سبب.\nالعلاج حسب السبب وكمية الدعم المتبقية.",src:"https://my.clevelandclinic.org/health/diseases/16620-periodontitis"},{title_en:"Periodontal pockets",title_ar:"جيوب اللثة",description_en:"Gum disease can create deeper spaces around teeth.\nA dentist measures these pockets and checks for bone loss.\nDepth alone does not tell you the full diagnosis at home.",description_ar:"مرض اللثة ممكن يعمل فراغات أعمق حوالين الأسنان.\nالدكتور يقيس الجيوب ويفحص فقدان العظم.\nالعمق لوحده مش تشخيص كامل تعمله في البيت.",symptoms:{en:"Bleeding, swelling, bad breath or loose teeth may occur.",ar:"ممكن يحصل نزيف أو ورم أو رائحة فم أو حركة أسنان."},treatment:{en:"Treatment may include deep cleaning or specialist surgery.",ar:"العلاج ممكن يشمل تنظيف عميق أو جراحة عند مختص."},prevention:{en:"Daily cleaning and planned maintenance help control recurrence.",ar:"التنظيف اليومي والصيانة المخططة بيساعدوا يتحكموا في الرجوع."},category:"Gum disease",source_name:"Cleveland Clinic",source_url:"https://my.clevelandclinic.org/health/diseases/16620-periodontitis",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Periodontal pockets",ar:"جيوب اللثة",cat:"Gum disease",sen:"Gum disease can create deeper spaces around teeth.\nA dentist measures these pockets and checks for bone loss.\nDepth alone does not tell you the full diagnosis at home.",sar:"مرض اللثة ممكن يعمل فراغات أعمق حوالين الأسنان.\nالدكتور يقيس الجيوب ويفحص فقدان العظم.\nالعمق لوحده مش تشخيص كامل تعمله في البيت.",src:"https://my.clevelandclinic.org/health/diseases/16620-periodontitis"},{title_en:"Mouth guards",title_ar:"واقي الفم الرياضي",description_en:"A fitted guard worn for contact sports prevents broken and knocked-out teeth. Custom guards from a dentist fit and protect better than boil-and-bite ones.",description_ar:"واقي مفصل بيتلبس في الرياضات العنيفة بيمنع كسر ووقوع الأسنان. الواقي المخصص من الدكتور أريح وأفضل حماية من الجاهز.",symptoms:{en:"",ar:""},treatment:{en:"",ar:""},prevention:{en:"",ar:""},category:"Prevention",source_name:null,source_url:null,last_updated:null,verification_status:"pending_review",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",legacy_source_url:"https://www.mouthhealthy.org/all-topics-a-z/mouthguards",en:"Mouth guards",ar:"واقي الفم الرياضي",sen:"A fitted guard worn for contact sports prevents broken and knocked-out teeth. Custom guards from a dentist fit and protect better than boil-and-bite ones.",sar:"واقي مفصل بيتلبس في الرياضات العنيفة بيمنع كسر ووقوع الأسنان. الواقي المخصص من الدكتور أريح وأفضل حماية من الجاهز.",cat:"Prevention",src:null},{title_en:"Night guard for grinding",title_ar:"الواقي الليلي للجز",description_en:"A fitted guard or splint can protect teeth from grinding damage at night.\nIt is not needed for every person who grinds their teeth.\nA dentist checks the teeth and decides whether it may help.",description_ar:"الواقي أو الجبيرة المناسبة ممكن تحمي الأسنان من ضرر الجز بالليل.\nمش كل شخص بيجز محتاجها.\nالدكتور بيفحص الأسنان ويقرر إذا كانت مفيدة.",symptoms:{en:"Grinding with tooth damage, sensitivity or jaw discomfort.",ar:"جز مع ضرر بالأسنان أو حساسية أو وجع فك."},treatment:{en:"A dentist-made guard fits over upper or lower teeth.",ar:"واقي بيعمله الدكتور على مقاس الفك العلوي أو السفلي."},prevention:{en:"Attend dental checks and address stress and sleep issues.",ar:"تابع عند الدكتور واهتم بالتوتر ومشاكل النوم."},category:"Treatment",source_name:"NHS",source_url:"https://www.nhs.uk/symptoms/teeth-grinding/",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Night guard for grinding",ar:"الواقي الليلي للجز",cat:"Treatment",sen:"A fitted guard or splint can protect teeth from grinding damage at night.\nIt is not needed for every person who grinds their teeth.\nA dentist checks the teeth and decides whether it may help.",sar:"الواقي أو الجبيرة المناسبة ممكن تحمي الأسنان من ضرر الجز بالليل.\nمش كل شخص بيجز محتاجها.\nالدكتور بيفحص الأسنان ويقرر إذا كانت مفيدة.",src:"https://www.nhs.uk/symptoms/teeth-grinding/"},{title_en:"Dental anxiety",title_ar:"الخوف من دكتور الأسنان",description_en:"Very common and manageable: tell the team, agree a stop signal, start with a simple visit. Options range from distraction techniques to sedation for severe cases.",description_ar:"شائع جدًا وله حل: قول للفريق، اتفق على إشارة إيقاف، وابدأ بزيارة بسيطة. الحلول من تشتيت الانتباه للتهدئة الدوائية في الحالات الشديدة.",symptoms:{en:"",ar:""},treatment:{en:"",ar:""},prevention:{en:"",ar:""},category:"Special care",source_name:null,source_url:null,last_updated:null,verification_status:"pending_review",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",legacy_source_url:"https://www.mouthhealthy.org/all-topics-a-z/dental-anxiety",en:"Dental anxiety",ar:"الخوف من دكتور الأسنان",sen:"Very common and manageable: tell the team, agree a stop signal, start with a simple visit. Options range from distraction techniques to sedation for severe cases.",sar:"شائع جدًا وله حل: قول للفريق، اتفق على إشارة إيقاف، وابدأ بزيارة بسيطة. الحلول من تشتيت الانتباه للتهدئة الدوائية في الحالات الشديدة.",cat:"Special care",src:null},{title_en:"How to brush teeth",title_ar:"طريقة غسل الأسنان",description_en:"Brush twice daily for about two minutes, including before bed.\nClean the inside, outside and chewing surfaces of every tooth.\nSpit out toothpaste after brushing and do not rinse immediately.",description_ar:"اغسل مرتين يومياً حوالي دقيقتين ومنهم مرة قبل النوم.\nنضف الأسطح الداخلية والخارجية وأسطح المضغ لكل سن.\nابصق المعجون بعد الغسيل ومتتمضمضش فوراً.",symptoms:{en:"Preventive care is useful even without symptoms.",ar:"الوقاية مهمة حتى من غير أعراض."},treatment:{en:"Ask a dentist or hygienist to demonstrate brushing for your needs.",ar:"اطلب من الدكتور أو أخصائي النظافة يوضح الطريقة المناسبة ليك."},prevention:{en:"Use fluoride toothpaste and include daily cleaning between teeth.",ar:"استخدم معجون فلورايد ونضف بين الأسنان يومياً."},category:"Prevention",source_name:"NHS",source_url:"https://www.nhs.uk/live-well/healthy-teeth-and-gums/how-to-keep-your-teeth-clean/",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"How to brush teeth",ar:"طريقة غسل الأسنان",cat:"Prevention",sen:"Brush twice daily for about two minutes, including before bed.\nClean the inside, outside and chewing surfaces of every tooth.\nSpit out toothpaste after brushing and do not rinse immediately.",sar:"اغسل مرتين يومياً حوالي دقيقتين ومنهم مرة قبل النوم.\nنضف الأسطح الداخلية والخارجية وأسطح المضغ لكل سن.\nابصق المعجون بعد الغسيل ومتتمضمضش فوراً.",src:"https://www.nhs.uk/live-well/healthy-teeth-and-gums/how-to-keep-your-teeth-clean/"},{title_en:"How to floss",title_ar:"طريقة استخدام خيط الأسنان",description_en:"Floss helps remove plaque and food between teeth.\nCurve it into a C shape against each tooth and move gently up and down.\nAsk a dental professional to show you if the technique is difficult.",description_ar:"الخيط بيساعد يشيل البلاك والأكل بين الأسنان.\nلفه بشكل حرف C على كل سن وحركه برفق فوق وتحت.\nاطلب من مختص يوريك الطريقة لو صعبة عليك.",symptoms:{en:"Food trapping may occur, but plaque removal matters even without it.",ar:"ممكن الأكل يتحشر لكن إزالة البلاك مهمة حتى من غير ده."},treatment:{en:"Choose floss or another suitable interdental aid with professional advice.",ar:"اختار خيط أو وسيلة مناسبة للتنظيف بين الأسنان بنصيحة مختص."},prevention:{en:"Clean between teeth daily and avoid forcing tools into the gums.",ar:"نضف بين الأسنان يومياً ومتزقش الأدوات بعنف في اللثة."},category:"Prevention",source_name:"NHS",source_url:"https://www.nhs.uk/live-well/healthy-teeth-and-gums/how-to-keep-your-teeth-clean/",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"How to floss",ar:"طريقة استخدام خيط الأسنان",cat:"Prevention",sen:"Floss helps remove plaque and food between teeth.\nCurve it into a C shape against each tooth and move gently up and down.\nAsk a dental professional to show you if the technique is difficult.",sar:"الخيط بيساعد يشيل البلاك والأكل بين الأسنان.\nلفه بشكل حرف C على كل سن وحركه برفق فوق وتحت.\nاطلب من مختص يوريك الطريقة لو صعبة عليك.",src:"https://www.nhs.uk/live-well/healthy-teeth-and-gums/how-to-keep-your-teeth-clean/"},{title_en:"Mouthwash",title_ar:"غسول الفم",description_en:"A fluoride mouthwash may help prevent tooth decay.\nUse it at a different time from brushing, not straight afterwards.\nIt does not replace brushing and cleaning between teeth.",description_ar:"غسول الفلورايد ممكن يساعد يمنع التسوس.\nاستخدمه في وقت مختلف عن الغسيل مش بعده مباشرة.\nمش بديل للفرشاة والتنظيف بين الأسنان.",symptoms:{en:"This is preventive advice, not treatment for an unexplained sore mouth.",ar:"دي نصيحة وقاية مش علاج لألم فم غير معروف السبب."},treatment:{en:"Ask your dentist which product, if any, suits your needs.",ar:"اسأل دكتورك عن المنتج المناسب لو محتاجه."},prevention:{en:"Avoid eating or drinking for thirty minutes after fluoride mouthwash.",ar:"تجنب الأكل والشرب نص ساعة بعد غسول الفلورايد."},category:"Prevention",source_name:"NHS",source_url:"https://www.nhs.uk/live-well/healthy-teeth-and-gums/how-to-keep-your-teeth-clean/",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Mouthwash",ar:"غسول الفم",cat:"Prevention",sen:"A fluoride mouthwash may help prevent tooth decay.\nUse it at a different time from brushing, not straight afterwards.\nIt does not replace brushing and cleaning between teeth.",sar:"غسول الفلورايد ممكن يساعد يمنع التسوس.\nاستخدمه في وقت مختلف عن الغسيل مش بعده مباشرة.\nمش بديل للفرشاة والتنظيف بين الأسنان.",src:"https://www.nhs.uk/live-well/healthy-teeth-and-gums/how-to-keep-your-teeth-clean/"},{title_en:"Electric or manual toothbrush",title_ar:"فرشاة كهربائية ولا عادية",description_en:"Both types can clean teeth well with good technique.\nAn electric brush may make thorough cleaning easier for some people.\nCleaning every surface matters more than choosing by price alone.",description_ar:"النوعين يقدروا ينضفوا كويس بالطريقة الصحيحة.\nالكهربائية ممكن تسهل التنظيف الجيد لبعض الناس.\nتنظيف كل سطح أهم من الاختيار بالسعر بس.",symptoms:{en:"No symptoms are needed to review your cleaning routine.",ar:"مش لازم أعراض عشان تراجع روتين التنظيف."},treatment:{en:"Ask a professional which brush is easiest for you to use.",ar:"اسأل مختص عن الفرشاة الأسهل ليك في الاستخدام."},prevention:{en:"Brush twice daily with fluoride toothpaste and clean between teeth.",ar:"اغسل مرتين بمعجون فلورايد ونضف بين الأسنان."},category:"Prevention",source_name:"NHS",source_url:"https://www.nhs.uk/live-well/healthy-teeth-and-gums/how-to-keep-your-teeth-clean/",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Electric or manual toothbrush",ar:"فرشاة كهربائية ولا عادية",cat:"Prevention",sen:"Both types can clean teeth well with good technique.\nAn electric brush may make thorough cleaning easier for some people.\nCleaning every surface matters more than choosing by price alone.",sar:"النوعين يقدروا ينضفوا كويس بالطريقة الصحيحة.\nالكهربائية ممكن تسهل التنظيف الجيد لبعض الناس.\nتنظيف كل سطح أهم من الاختيار بالسعر بس.",src:"https://www.nhs.uk/live-well/healthy-teeth-and-gums/how-to-keep-your-teeth-clean/"},{title_en:"Fluoride toothpaste labels",title_ar:"قراءة ملصق معجون الفلورايد",description_en:"The fluoride concentration is printed on toothpaste packaging.\nAdults should use at least 1350 ppm fluoride according to NHS advice.\nFor children, the amount of paste and concentration depend on age and risk.",description_ar:"تركيز الفلورايد مكتوب على عبوة المعجون.\nنصيحة NHS للكبار معجون فيه على الأقل 1350 جزء في المليون فلورايد.\nللأطفال كمية المعجون وتركيزه حسب العمر والخطورة.",symptoms:{en:"Prevention applies before cavities become painful.",ar:"الوقاية قبل ما التسوس يبقى مؤلم."},treatment:{en:"Ask your dentist about an age-appropriate fluoride product.",ar:"اسأل دكتورك عن منتج فلورايد مناسب للعمر."},prevention:{en:"Do not let children eat paste; supervise their brushing.",ar:"متخليش الطفل ياكل المعجون واشرف على الغسيل."},category:"Prevention",source_name:"NHS",source_url:"https://www.nhs.uk/live-well/healthy-teeth-and-gums/how-to-keep-your-teeth-clean/",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Fluoride toothpaste labels",ar:"قراءة ملصق معجون الفلورايد",cat:"Prevention",sen:"The fluoride concentration is printed on toothpaste packaging.\nAdults should use at least 1350 ppm fluoride according to NHS advice.\nFor children, the amount of paste and concentration depend on age and risk.",sar:"تركيز الفلورايد مكتوب على عبوة المعجون.\nنصيحة NHS للكبار معجون فيه على الأقل 1350 جزء في المليون فلورايد.\nللأطفال كمية المعجون وتركيزه حسب العمر والخطورة.",src:"https://www.nhs.uk/live-well/healthy-teeth-and-gums/how-to-keep-your-teeth-clean/"},{title_en:"Dental checkup frequency",title_ar:"مواعيد كشف الأسنان الدوري",description_en:"Routine checkups are based on your individual risk.\nSome people need frequent visits while lower-risk adults may wait longer.\nDo not wait for the next routine visit if a new problem develops.",description_ar:"مواعيد الكشف الدوري حسب عوامل الخطورة عندك.\nناس محتاجة زيارات متقاربة والكبار الأقل خطورة ممكن ينتظروا أكتر.\nمتستناش المعاد الدوري لو ظهرت مشكلة جديدة.",symptoms:{en:"A checkup is useful even without pain or visible problems.",ar:"الكشف مفيد حتى من غير ألم أو مشاكل ظاهرة."},treatment:{en:"Your dentist examines teeth, gums and mouth and agrees the next visit.",ar:"الدكتور يفحص الأسنان واللثة والفم ويحدد معاك الزيارة الجاية."},prevention:{en:"Follow your personalised recall interval rather than a fixed rule for everyone.",ar:"التزم بالمدة المناسبة ليك بدل قاعدة ثابتة لكل الناس."},category:"Prevention",source_name:"NHS",source_url:"https://www.nhs.uk/Live-well/healthy-teeth-and-gums/dental-check-ups/",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Dental checkup frequency",ar:"مواعيد كشف الأسنان الدوري",cat:"Prevention",sen:"Routine checkups are based on your individual risk.\nSome people need frequent visits while lower-risk adults may wait longer.\nDo not wait for the next routine visit if a new problem develops.",sar:"مواعيد الكشف الدوري حسب عوامل الخطورة عندك.\nناس محتاجة زيارات متقاربة والكبار الأقل خطورة ممكن ينتظروا أكتر.\nمتستناش المعاد الدوري لو ظهرت مشكلة جديدة.",src:"https://www.nhs.uk/Live-well/healthy-teeth-and-gums/dental-check-ups/"},{title_en:"Post-filling sensitivity",title_ar:"حساسية بعد الحشو",description_en:"Mild cold sensitivity for days to two weeks after a filling is normal as the nerve settles. Pain on biting or worsening pain means the bite needs adjustment or the tooth needs review.",description_ar:"حساسية بسيطة للبارد لأيام أو أسبوعين بعد الحشو حاجة طبيعية لحد ما العصب يهدى. ألم عند المضغ أو ألم بيزيد معناه إن الإطباقة محتاجة تعديل أو السن محتاجة مراجعة.",symptoms:{en:"",ar:""},treatment:{en:"",ar:""},prevention:{en:"",ar:""},category:"Restorative",source_name:null,source_url:null,last_updated:null,verification_status:"pending_review",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",legacy_source_url:"https://www.mouthhealthy.org/all-topics-a-z/fillings",en:"Post-filling sensitivity",ar:"حساسية بعد الحشو",sen:"Mild cold sensitivity for days to two weeks after a filling is normal as the nerve settles. Pain on biting or worsening pain means the bite needs adjustment or the tooth needs review.",sar:"حساسية بسيطة للبارد لأيام أو أسبوعين بعد الحشو حاجة طبيعية لحد ما العصب يهدى. ألم عند المضغ أو ألم بيزيد معناه إن الإطباقة محتاجة تعديل أو السن محتاجة مراجعة.",cat:"Restorative",src:null},{title_en:"Cracked tooth syndrome",title_ar:"متلازمة السن المشروخة",description_en:"Sharp pain on biting or release, often on a back tooth with a large filling. Early crowns protect cracks; untreated cracks can split the tooth beyond saving.",description_ar:"ألم حاد عند المضغ أو وقت فك الضغط، غالبًا على ضرس خلفي عليه حشو كبير. التلبيس المبكر بيحمي الشرخ؛ الشرخ المهمل ممكن يشق السن لدرجة ماتتعالجش.",symptoms:{en:"",ar:""},treatment:{en:"",ar:""},prevention:{en:"",ar:""},category:"Symptoms",source_name:null,source_url:null,last_updated:null,verification_status:"pending_review",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",legacy_source_url:"https://www.mouthhealthy.org/all-topics-a-z/cracked-tooth",en:"Cracked tooth syndrome",ar:"متلازمة السن المشروخة",sen:"Sharp pain on biting or release, often on a back tooth with a large filling. Early crowns protect cracks; untreated cracks can split the tooth beyond saving.",sar:"ألم حاد عند المضغ أو وقت فك الضغط، غالبًا على ضرس خلفي عليه حشو كبير. التلبيس المبكر بيحمي الشرخ؛ الشرخ المهمل ممكن يشق السن لدرجة ماتتعالجش.",cat:"Symptoms",src:null},{title_en:"Root canal or extraction",title_ar:"علاج جذور ولا خلع",description_en:"Advanced pulp inflammation may need root canal treatment or extraction.\nA root canal treats the inside of a tooth; extraction removes it.\nThe dentist explains whether the tooth can be saved and replacement options.",description_ar:"التهاب اللب المتقدم ممكن يحتاج علاج جذور أو خلع.\nعلاج الجذور بيعالج جوه السن والخلع بيشيله.\nالدكتور يشرح قابلية إنقاذ السن واختيارات تعويضه.",symptoms:{en:"Lingering sensitivity or toothache needs an examination.",ar:"حساسية مستمرة أو ألم سن محتاجين كشف."},treatment:{en:"An individual choice after clinical tests and imaging when needed.",ar:"اختيار حسب الحالة بعد الفحوصات وأشعة عند الاحتياج."},prevention:{en:"Do not delay care while comparing options; ask for the risks of each.",ar:"متأجلش الرعاية وانت بتقارن واسأل عن مخاطر كل اختيار."},category:"Treatment",source_name:"Cleveland Clinic",source_url:"https://my.clevelandclinic.org/health/diseases/23536-pulpitis",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Root canal or extraction",ar:"علاج جذور ولا خلع",cat:"Treatment",sen:"Advanced pulp inflammation may need root canal treatment or extraction.\nA root canal treats the inside of a tooth; extraction removes it.\nThe dentist explains whether the tooth can be saved and replacement options.",sar:"التهاب اللب المتقدم ممكن يحتاج علاج جذور أو خلع.\nعلاج الجذور بيعالج جوه السن والخلع بيشيله.\nالدكتور يشرح قابلية إنقاذ السن واختيارات تعويضه.",src:"https://my.clevelandclinic.org/health/diseases/23536-pulpitis"},{title_en:"After root canal care",title_ar:"العناية بعد علاج الجذور",description_en:"Mild soreness may follow root canal treatment.\nFollow the plan for the final restoration and protect the treated tooth.\nContact the dentist for worsening or throbbing pain.",description_ar:"ممكن يحصل وجع بسيط بعد علاج الجذور.\nاتبع خطة الترميم النهائي واحمي السن المعالج.\nكلم الدكتور لو الألم بيزيد أو بقى نابض.",symptoms:{en:"Temporary soreness may occur; persistent pain needs review.",ar:"ممكن وجع مؤقت والألم المستمر محتاج مراجعة."},treatment:{en:"Keep review appointments and complete the definitive restoration.",ar:"حافظ على المراجعات وكمل الترميم النهائي."},prevention:{en:"Clean as instructed and avoid biting on the tooth until your dentist allows it.",ar:"نضف حسب التعليمات ومتعضش على السن قبل سماح الدكتور."},category:"Treatment",source_name:"Cleveland Clinic",source_url:"https://my.clevelandclinic.org/health/treatments/21759-root-canal",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"After root canal care",ar:"العناية بعد علاج الجذور",cat:"Treatment",sen:"Mild soreness may follow root canal treatment.\nFollow the plan for the final restoration and protect the treated tooth.\nContact the dentist for worsening or throbbing pain.",sar:"ممكن يحصل وجع بسيط بعد علاج الجذور.\nاتبع خطة الترميم النهائي واحمي السن المعالج.\nكلم الدكتور لو الألم بيزيد أو بقى نابض.",src:"https://my.clevelandclinic.org/health/treatments/21759-root-canal"},{title_en:"Dental implant aftercare",title_ar:"العناية بعد زراعة الأسنان",description_en:"Early gum healing and bonding of an implant to bone take different times.\nFollow the surgeon’s plan and attend checks before the final tooth is fitted.\nCall the dentist for a loose implant, pus, fever or swollen bleeding gums.",description_ar:"التئام اللثة الأولي والتحام الزرعة بالعظم مش نفس المدة.\nاتبع خطة الجراح والمتابعة قبل تركيب السن النهائي.\nكلم الدكتور لو الزرعة بتتحرك أو فيه صديد أو حرارة أو لثة متورمة وبتنزف.",symptoms:{en:"Some early discomfort can occur; worrying changes need assessment.",ar:"ممكن يحصل انزعاج أولي؛ التغيرات المقلقة محتاجة تقييم."},treatment:{en:"The dental team monitors healing and plans the restoration.",ar:"فريق الأسنان يتابع الالتئام ويخطط التعويض."},prevention:{en:"Maintain the prescribed cleaning routine and avoid smoking.",ar:"حافظ على روتين التنظيف المحدد وتجنب التدخين."},category:"Surgery",source_name:"Cleveland Clinic",source_url:"https://my.clevelandclinic.org/health/treatments/10903-dental-implants",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Dental implant aftercare",ar:"العناية بعد زراعة الأسنان",cat:"Surgery",sen:"Early gum healing and bonding of an implant to bone take different times.\nFollow the surgeon’s plan and attend checks before the final tooth is fitted.\nCall the dentist for a loose implant, pus, fever or swollen bleeding gums.",sar:"التئام اللثة الأولي والتحام الزرعة بالعظم مش نفس المدة.\nاتبع خطة الجراح والمتابعة قبل تركيب السن النهائي.\nكلم الدكتور لو الزرعة بتتحرك أو فيه صديد أو حرارة أو لثة متورمة وبتنزف.",src:"https://my.clevelandclinic.org/health/treatments/10903-dental-implants"},{title_en:"How long dental implants last",title_ar:"العمر المتوقع لزرعات الأسنان",description_en:"Implants can last a long time with good care, but outcomes vary.\nThe crown, bridge or denture on top may need replacement sooner.\nRegular checks help assess the implant and surrounding gums.",description_ar:"الزرعات ممكن تعيش فترة طويلة بالعناية لكن النتائج بتختلف.\nالتلبيسة أو الجسر أو الطقم فوقها ممكن يحتاج تغيير قبلها.\nالمتابعة بتساعد تقيم الزرعة واللثة حوالينها.",symptoms:{en:"Looseness, bleeding, swelling or pus should prompt a dental check.",ar:"الحركة أو النزيف أو الورم أو الصديد يستدعوا كشف."},treatment:{en:"A dentist assesses the cause of changes and the condition of each component.",ar:"الدكتور يقيم سبب التغيرات وحالة كل جزء."},prevention:{en:"Brush, clean between teeth and follow ongoing dental reviews.",ar:"اغسل ونضف بين الأسنان والتزم بالمتابعة المستمرة."},category:"Treatment",source_name:"Cleveland Clinic",source_url:"https://my.clevelandclinic.org/health/treatments/10903-dental-implants",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"How long dental implants last",ar:"العمر المتوقع لزرعات الأسنان",cat:"Treatment",sen:"Implants can last a long time with good care, but outcomes vary.\nThe crown, bridge or denture on top may need replacement sooner.\nRegular checks help assess the implant and surrounding gums.",sar:"الزرعات ممكن تعيش فترة طويلة بالعناية لكن النتائج بتختلف.\nالتلبيسة أو الجسر أو الطقم فوقها ممكن يحتاج تغيير قبلها.\nالمتابعة بتساعد تقيم الزرعة واللثة حوالينها.",src:"https://my.clevelandclinic.org/health/treatments/10903-dental-implants"},{title_en:"Whitening safety",title_ar:"أمان تبييض الأسنان",description_en:"Healthy teeth and gums should be checked before whitening.\nProducts can cause sensitive teeth, sore gums or temporary white gum patches.\nAsk a dentist about suitability and report side effects that bother you.",description_ar:"لازم تتأكد بالكشف إن الأسنان واللثة سليمة قبل التبييض.\nالمنتجات ممكن تسبب حساسية أو وجع لثة أو بقع مؤقتة عليها.\nاسأل الدكتور عن ملاءمتها وكلمه لو الأعراض مضايقاك.",symptoms:{en:"Sensitivity to cold or sweet foods, or sore gums after whitening.",ar:"حساسية للبارد أو الحلو أو وجع لثة بعد التبييض."},treatment:{en:"A dentist reviews side effects and advises on safe treatment.",ar:"الدكتور بيراجع الأعراض وينصح بالعلاج الآمن."},prevention:{en:"Use dentist-supervised products and the prescribed schedule.",ar:"استخدم منتجات بإشراف الدكتور وبالجدول المحدد."},category:"Cosmetic",source_name:"NHS",source_url:"https://www.nhs.uk/tests-and-treatments/teeth-whitening/",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Whitening safety",ar:"أمان تبييض الأسنان",cat:"Cosmetic",sen:"Healthy teeth and gums should be checked before whitening.\nProducts can cause sensitive teeth, sore gums or temporary white gum patches.\nAsk a dentist about suitability and report side effects that bother you.",sar:"لازم تتأكد بالكشف إن الأسنان واللثة سليمة قبل التبييض.\nالمنتجات ممكن تسبب حساسية أو وجع لثة أو بقع مؤقتة عليها.\nاسأل الدكتور عن ملاءمتها وكلمه لو الأعراض مضايقاك.",src:"https://www.nhs.uk/tests-and-treatments/teeth-whitening/"},{title_en:"Whitening for sensitive teeth",title_ar:"التبييض لأصحاب الأسنان الحساسة",description_en:"Use lower-concentration gel for shorter sessions, with a desensitizing toothpaste for two weeks before. Custom trays keep gel off the gums.",description_ar:"استخدم جل بتركيز أقل لجلسات أقصر، مع معجون مضاد للحساسية أسبوعين قبلها. القوالب المخصصة بتبعد الجل عن اللثة.",symptoms:{en:"",ar:""},treatment:{en:"",ar:""},prevention:{en:"",ar:""},category:"Cosmetic",source_name:null,source_url:null,last_updated:null,verification_status:"pending_review",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",legacy_source_url:"https://www.mouthhealthy.org/all-topics-a-z/teeth-whitening",en:"Whitening for sensitive teeth",ar:"التبييض لأصحاب الأسنان الحساسة",sen:"Use lower-concentration gel for shorter sessions, with a desensitizing toothpaste for two weeks before. Custom trays keep gel off the gums.",sar:"استخدم جل بتركيز أقل لجلسات أقصر، مع معجون مضاد للحساسية أسبوعين قبلها. القوالب المخصصة بتبعد الجل عن اللثة.",cat:"Cosmetic",src:null},{title_en:"Stained teeth causes",title_ar:"أسباب تصبغ الأسنان",description_en:"Surface stains come from coffee, tea, smoking and dark foods; internal discoloration from trauma, medications (tetracycline) or fluorosis. Surface stains polish off; internal ones need whitening, bonding or veneers.",description_ar:"التصبغات السطحية من القهوة والشاي والتدخين والأكل الغامق؛ التلون الداخلي من إصابات أو أدوية (تتراسيكلين) أو تفلور. السطحية بتتشال بالتلميع؛ الداخلية محتاجة تبييض أو لصق تجميلي أو فينير.",symptoms:{en:"",ar:""},treatment:{en:"",ar:""},prevention:{en:"",ar:""},category:"Cosmetic",source_name:null,source_url:null,last_updated:null,verification_status:"pending_review",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",legacy_source_url:"https://www.mouthhealthy.org/all-topics-a-z/tooth-discoloration",en:"Stained teeth causes",ar:"أسباب تصبغ الأسنان",sen:"Surface stains come from coffee, tea, smoking and dark foods; internal discoloration from trauma, medications (tetracycline) or fluorosis. Surface stains polish off; internal ones need whitening, bonding or veneers.",sar:"التصبغات السطحية من القهوة والشاي والتدخين والأكل الغامق؛ التلون الداخلي من إصابات أو أدوية (تتراسيكلين) أو تفلور. السطحية بتتشال بالتلميع؛ الداخلية محتاجة تبييض أو لصق تجميلي أو فينير.",cat:"Cosmetic",src:null},{title_en:"Gap between front teeth",title_ar:"الفلجة بين الأسنان الأمامية",description_en:"A gap between teeth may be a cosmetic concern.\nBonding can close some spaces, but it is not right for every case.\nA dentist should assess the cause and discuss suitable options.",description_ar:"الفراغ بين الأسنان ممكن يكون مصدر قلق من ناحية الشكل.\nالبوندنج يقدر يقفل بعض الفراغات لكنه مش مناسب لكل حالة.\nالدكتور يقيم السبب ويناقش الاختيارات المناسبة.",symptoms:{en:"A visible space between teeth.",ar:"فراغ واضح بين الأسنان."},treatment:{en:"Tooth-coloured bonding may be an option after assessment.",ar:"البوندنج بلون الأسنان ممكن يكون اختيار بعد التقييم."},prevention:{en:"Keep the area clean and avoid biting objects that could chip bonding.",ar:"حافظ على نظافة المكان ومتعضش على حاجات ممكن تكسر البوندنج."},category:"Cosmetic",source_name:"Cleveland Clinic",source_url:"https://my.clevelandclinic.org/health/treatments/10922-dental-bonding",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Gap between front teeth",ar:"الفلجة بين الأسنان الأمامية",cat:"Cosmetic",sen:"A gap between teeth may be a cosmetic concern.\nBonding can close some spaces, but it is not right for every case.\nA dentist should assess the cause and discuss suitable options.",sar:"الفراغ بين الأسنان ممكن يكون مصدر قلق من ناحية الشكل.\nالبوندنج يقدر يقفل بعض الفراغات لكنه مش مناسب لكل حالة.\nالدكتور يقيم السبب ويناقش الاختيارات المناسبة.",src:"https://my.clevelandclinic.org/health/treatments/10922-dental-bonding"},{title_en:"Gummy smile",title_ar:"الابتسامة اللثوية",description_en:"Extra gum tissue can make teeth appear short.\nLip position, tooth wear and bone levels also matter in planning.\nGum contouring is one option for suitable patients, not a universal fix.",description_ar:"زيادة نسيج اللثة ممكن تخلي الأسنان تبان قصيرة.\nوضع الشفة وتآكل الأسنان ومستوى العظم مهمين في التخطيط.\nتجميل اللثة اختيار لحالات مناسبة ومش حل لكل الحالات.",symptoms:{en:"A large amount of visible gum or an uneven gum line.",ar:"ظهور جزء كبير من اللثة أو خط لثة غير منتظم."},treatment:{en:"A dentist or gum specialist checks teeth, gums and bone first.",ar:"الدكتور أو أخصائي اللثة بيفحص الأسنان واللثة والعظم الأول."},prevention:{en:"Treat decay or gum disease before cosmetic procedures.",ar:"عالج التسوس أو مرض اللثة قبل إجراءات التجميل."},category:"Cosmetic",source_name:"Cleveland Clinic",source_url:"https://my.clevelandclinic.org/health/treatments/25208-gum-contouring",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Gummy smile",ar:"الابتسامة اللثوية",cat:"Cosmetic",sen:"Extra gum tissue can make teeth appear short.\nLip position, tooth wear and bone levels also matter in planning.\nGum contouring is one option for suitable patients, not a universal fix.",sar:"زيادة نسيج اللثة ممكن تخلي الأسنان تبان قصيرة.\nوضع الشفة وتآكل الأسنان ومستوى العظم مهمين في التخطيط.\nتجميل اللثة اختيار لحالات مناسبة ومش حل لكل الحالات.",src:"https://my.clevelandclinic.org/health/treatments/25208-gum-contouring"},{title_en:"Wisdom tooth pain",title_ar:"ألم ضرس العقل",description_en:"Pain around a wisdom tooth needs an examination to find the cause.\nAn impacted tooth or surrounding inflammation can be involved.\nTreatment is based on examination and imaging when needed.",description_ar:"ألم حوالين ضرس العقل محتاج كشف عشان نعرف السبب.\nالانطمار أو التهاب المنطقة حواليه ممكن يكونوا السبب.\nالعلاج حسب الكشف وأشعة عند الاحتياج.",symptoms:{en:"Back-of-mouth pain, swollen gums, bad taste or limited opening.",ar:"ألم آخر الفم أو ورم اللثة أو طعم سيئ أو فتح محدود."},treatment:{en:"The dentist assesses infection and whether monitoring or removal is appropriate.",ar:"الدكتور يقيم العدوى ومدى مناسبة المتابعة أو الخلع."},prevention:{en:"Keep the area clean and seek care for new or worsening symptoms.",ar:"حافظ على نظافة المنطقة واكشف لو الأعراض جديدة أو بتزيد."},category:"Emergency",source_name:"Cleveland Clinic",source_url:"https://my.clevelandclinic.org/health/diseases/impacted-tooth",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Wisdom tooth pain",ar:"ألم ضرس العقل",cat:"Emergency",sen:"Pain around a wisdom tooth needs an examination to find the cause.\nAn impacted tooth or surrounding inflammation can be involved.\nTreatment is based on examination and imaging when needed.",sar:"ألم حوالين ضرس العقل محتاج كشف عشان نعرف السبب.\nالانطمار أو التهاب المنطقة حواليه ممكن يكونوا السبب.\nالعلاج حسب الكشف وأشعة عند الاحتياج.",src:"https://my.clevelandclinic.org/health/diseases/impacted-tooth"},{title_en:"Pericoronitis",title_ar:"التهاب ما حول تاج ضرس العقل",description_en:"Gum tissue around a partly erupted wisdom tooth can become inflamed.\nFood and bacteria may collect beneath the gum flap.\nPrompt dental care helps prevent the infection from worsening.",description_ar:"اللثة حوالين ضرس عقل طالع جزئياً ممكن تلتهب.\nالأكل والبكتيريا ممكن يتجمعوا تحت غطاء اللثة.\nالرعاية السريعة بتساعد تمنع تدهور العدوى.",symptoms:{en:"Pain, gum swelling, bad taste, pus, fever or difficulty opening the mouth.",ar:"ألم أو ورم لثة أو طعم سيئ أو صديد أو حرارة أو صعوبة فتح الفم."},treatment:{en:"Cleaning, selected prescribed medicines or surgery according to severity.",ar:"تنظيف وأدوية موصوفة لحالات مختارة أو جراحة حسب الشدة."},prevention:{en:"Clean carefully and attend follow-up; hygiene cannot prevent every case.",ar:"نضف بعناية والتزم بالمتابعة والنظافة مش بتمنع كل الحالات."},category:"Surgery",source_name:"Cleveland Clinic",source_url:"https://my.clevelandclinic.org/health/diseases/24142-pericoronitis",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Pericoronitis",ar:"التهاب ما حول تاج ضرس العقل",cat:"Surgery",sen:"Gum tissue around a partly erupted wisdom tooth can become inflamed.\nFood and bacteria may collect beneath the gum flap.\nPrompt dental care helps prevent the infection from worsening.",sar:"اللثة حوالين ضرس عقل طالع جزئياً ممكن تلتهب.\nالأكل والبكتيريا ممكن يتجمعوا تحت غطاء اللثة.\nالرعاية السريعة بتساعد تمنع تدهور العدوى.",src:"https://my.clevelandclinic.org/health/diseases/24142-pericoronitis"},{title_en:"Antibiotics for dental pain",title_ar:"المضاد الحيوي لألم الأسنان",description_en:"Antibiotics do not cure tooth pain - the source (decay, nerve infection) must be treated. They are added only for spreading infection: facial swelling, fever, difficulty swallowing.",description_ar:"المضاد الحيوي مبيعالجش ألم الأسنان - لازم علاج المصدر (تسوس، التهاب عصب). بيتضاف بس لما العدوى بتنتشر: ورم في الوش، سخونية، صعوبة بلع.",symptoms:{en:"",ar:""},treatment:{en:"",ar:""},prevention:{en:"",ar:""},category:"Emergencies",source_name:null,source_url:null,last_updated:null,verification_status:"pending_review",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",legacy_source_url:"https://www.mouthhealthy.org/all-topics-a-z/antibiotics",en:"Antibiotics for dental pain",ar:"المضاد الحيوي لألم الأسنان",sen:"Antibiotics do not cure tooth pain - the source (decay, nerve infection) must be treated. They are added only for spreading infection: facial swelling, fever, difficulty swallowing.",sar:"المضاد الحيوي مبيعالجش ألم الأسنان - لازم علاج المصدر (تسوس، التهاب عصب). بيتضاف بس لما العدوى بتنتشر: ورم في الوش، سخونية، صعوبة بلع.",cat:"Emergencies",src:null},{title_en:"Facial swelling from a tooth",title_ar:"ورم الوجه بسبب الأسنان",description_en:"Dental infection can spread beyond a tooth into nearby tissues.\nFacial swelling needs prompt assessment, especially with fever.\nDifficulty breathing or swallowing needs immediate emergency care.",description_ar:"عدوى الأسنان ممكن تنتشر من السن للأنسجة حواليه.\nورم الوجه محتاج تقييم سريع خصوصاً مع الحرارة.\nصعوبة التنفس أو البلع محتاجة طوارئ فوراً.",symptoms:{en:"Expanding swelling, tooth pain, fever or trouble swallowing or breathing.",ar:"ورم بيزيد أو وجع سن أو حرارة أو صعوبة بلع أو تنفس."},treatment:{en:"Urgent clinical assessment and treatment of the source.",ar:"تقييم عاجل وعلاج مصدر العدوى."},prevention:{en:"Treat dental infections early rather than waiting for swelling to spread.",ar:"عالج عدوى الأسنان بدري ومتستناش الورم ينتشر."},category:"Emergency",source_name:"Cleveland Clinic",source_url:"https://my.clevelandclinic.org/health/articles/16959-endodontics",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Facial swelling from a tooth",ar:"ورم الوجه بسبب الأسنان",cat:"Emergency",sen:"Dental infection can spread beyond a tooth into nearby tissues.\nFacial swelling needs prompt assessment, especially with fever.\nDifficulty breathing or swallowing needs immediate emergency care.",sar:"عدوى الأسنان ممكن تنتشر من السن للأنسجة حواليه.\nورم الوجه محتاج تقييم سريع خصوصاً مع الحرارة.\nصعوبة التنفس أو البلع محتاجة طوارئ فوراً.",src:"https://my.clevelandclinic.org/health/articles/16959-endodontics"},{title_en:"Burning mouth",title_ar:"حرقان الفم",description_en:"A burning sensation without visible cause, linked to dry mouth, nutritional deficiencies, diabetes or anxiety. Blood tests and a review of medications are the usual first steps.",description_ar:"إحساس حرقان بدون سبب ظاهر، مرتبط بجفاف الفم أو نقص فيتامينات أو سكر أو توتر. تحاليل دم ومراجعة الأدوية هي أول خطوة عادة.",symptoms:{en:"",ar:""},treatment:{en:"",ar:""},prevention:{en:"",ar:""},category:"Soft tissue",source_name:null,source_url:null,last_updated:null,verification_status:"pending_review",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",legacy_source_url:"https://www.mouthhealthy.org/all-topics-a-z/burning-mouth",en:"Burning mouth",ar:"حرقان الفم",sen:"A burning sensation without visible cause, linked to dry mouth, nutritional deficiencies, diabetes or anxiety. Blood tests and a review of medications are the usual first steps.",sar:"إحساس حرقان بدون سبب ظاهر، مرتبط بجفاف الفم أو نقص فيتامينات أو سكر أو توتر. تحاليل دم ومراجعة الأدوية هي أول خطوة عادة.",cat:"Soft tissue",src:null},{title_en:"White patches in the mouth",title_ar:"بقع بيضاء في الفم",description_en:"White patches can have several causes, including thrush and other conditions.\nAppearance alone is not enough for self-diagnosis.\nSee a dentist or doctor for white patches or worsening tongue pain.",description_ar:"البقع البيضاء ليها أسباب مختلفة منها الفطريات وحالات تانية.\nالشكل لوحده مش كفاية للتشخيص الذاتي.\nاكشف عند دكتور أسنان أو طبيب لو فيه بقع بيضاء أو ألم لسان بيزيد.",symptoms:{en:"White areas on the tongue or inside the cheeks.",ar:"مناطق بيضاء على اللسان أو داخل الخد."},treatment:{en:"Treatment depends on the cause found during examination.",ar:"العلاج حسب السبب اللي الكشف يحدده."},prevention:{en:"Clean gently and avoid foods, smoking or alcohol that irritate the mouth.",ar:"نضف برفق وتجنب الأكل والتدخين والكحول اللي بيهيجوا الفم."},category:"Oral health",source_name:"NHS",source_url:"https://www.nhs.uk/symptoms/sore-or-white-tongue/",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"White patches in the mouth",ar:"بقع بيضاء في الفم",cat:"Oral health",sen:"White patches can have several causes, including thrush and other conditions.\nAppearance alone is not enough for self-diagnosis.\nSee a dentist or doctor for white patches or worsening tongue pain.",sar:"البقع البيضاء ليها أسباب مختلفة منها الفطريات وحالات تانية.\nالشكل لوحده مش كفاية للتشخيص الذاتي.\nاكشف عند دكتور أسنان أو طبيب لو فيه بقع بيضاء أو ألم لسان بيزيد.",src:"https://www.nhs.uk/symptoms/sore-or-white-tongue/"},{title_en:"Geographic tongue",title_ar:"اللسان الجغرافي",description_en:"Blotchy red tongue patches with a pale border may be geographic tongue.\nOther conditions can cause tongue changes too.\nAsk a clinician about patches or pain rather than diagnosing from a photo.",description_ar:"بقع حمرا غير منتظمة بحد فاتح على اللسان ممكن تكون لسان جغرافي.\nحالات تانية ممكن تسبب تغيرات في اللسان برضه.\nاسأل مختص عن البقع أو الألم بدل التشخيص من صورة.",symptoms:{en:"Red tongue patches with a white or light-coloured edge.",ar:"بقع حمرا على اللسان بحافة بيضاء أو فاتحة."},treatment:{en:"A clinician checks the tongue and advises care based on the cause.",ar:"المختص يفحص اللسان وينصح بالعناية حسب السبب."},prevention:{en:"Avoid hot, acidic or spicy foods if they irritate your tongue.",ar:"تجنب الأكل السخن أو الحمضي أو الحار لو بيهيج لسانك."},category:"Oral health",source_name:"NHS",source_url:"https://www.nhs.uk/symptoms/sore-or-white-tongue/",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Geographic tongue",ar:"اللسان الجغرافي",cat:"Oral health",sen:"Blotchy red tongue patches with a pale border may be geographic tongue.\nOther conditions can cause tongue changes too.\nAsk a clinician about patches or pain rather than diagnosing from a photo.",sar:"بقع حمرا غير منتظمة بحد فاتح على اللسان ممكن تكون لسان جغرافي.\nحالات تانية ممكن تسبب تغيرات في اللسان برضه.\nاسأل مختص عن البقع أو الألم بدل التشخيص من صورة.",src:"https://www.nhs.uk/symptoms/sore-or-white-tongue/"},{title_en:"Child's first dental visit",title_ar:"أول زيارة أسنان للطفل",description_en:"Take your child when the first teeth appear or before age one.\nEarly visits help children get used to the dentist.\nKeep the experience positive and ask about preventing decay.",description_ar:"خد طفلك للدكتور مع ظهور الأسنان الأولى أو قبل سنة.\nالزيارة المبكرة بتعود الطفل على دكتور الأسنان.\nخلي التجربة إيجابية واسأل عن الوقاية من التسوس.",symptoms:{en:"A first visit is useful even with no symptoms.",ar:"أول زيارة مهمة حتى من غير أعراض."},treatment:{en:"A gentle early examination and advice for the parent.",ar:"كشف مبكر برفق ونصائح للأهل."},prevention:{en:"Follow the check-up schedule recommended for your child.",ar:"التزم بمواعيد المتابعة اللي الدكتور ينصح بيها لطفلك."},category:"Pediatric",source_name:"NHS",source_url:"https://www.nhs.uk/live-well/healthy-teeth-and-gums/taking-care-of-childrens-teeth/",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",legacy_source_url:"https://www.mouthhealthy.org/all-topics-a-z/first-dental-visit",en:"Child's first dental visit",ar:"أول زيارة أسنان للطفل",sen:"Take your child when the first teeth appear or before age one.\nEarly visits help children get used to the dentist.\nKeep the experience positive and ask about preventing decay.",sar:"خد طفلك للدكتور مع ظهور الأسنان الأولى أو قبل سنة.\nالزيارة المبكرة بتعود الطفل على دكتور الأسنان.\nخلي التجربة إيجابية واسأل عن الوقاية من التسوس.",cat:"Pediatric",src:"https://www.nhs.uk/live-well/healthy-teeth-and-gums/taking-care-of-childrens-teeth/"},{title_en:"Bottle-related tooth decay",title_ar:"التسوس المرتبط بالببرونة",description_en:"Sweet drinks in a bottle keep sugar in contact with teeth.\nFrequent or prolonged exposure raises the risk of decay.\nA dentist should check suspected cavities in baby teeth.",description_ar:"المشروبات المحلاة في الببرونة بتخلي السكر يلامس الأسنان.\nالتعرض المتكرر أو الطويل بيزود خطورة التسوس.\nالدكتور لازم يفحص أي تسوس مشتبه في الأسنان اللبنية.",symptoms:{en:"Early decay may have no pain; later cavities can hurt.",ar:"التسوس المبكر ممكن ميوجعش والحفر بعد كده ممكن توجع."},treatment:{en:"Dental assessment and age-appropriate care.",ar:"كشف وعناية أسنان مناسبة للعمر."},prevention:{en:"Avoid sugary bottle drinks and start fluoride brushing with the first tooth.",ar:"تجنب المشروبات السكرية بالببرونة وابدأ غسيل فلورايد من أول سن."},category:"Pediatric",source_name:"NHS",source_url:"https://www.nhs.uk/baby/babys-development/teething/looking-after-your-babys-teeth/",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Bottle-related tooth decay",ar:"التسوس المرتبط بالببرونة",cat:"Pediatric",sen:"Sweet drinks in a bottle keep sugar in contact with teeth.\nFrequent or prolonged exposure raises the risk of decay.\nA dentist should check suspected cavities in baby teeth.",sar:"المشروبات المحلاة في الببرونة بتخلي السكر يلامس الأسنان.\nالتعرض المتكرر أو الطويل بيزود خطورة التسوس.\nالدكتور لازم يفحص أي تسوس مشتبه في الأسنان اللبنية.",src:"https://www.nhs.uk/baby/babys-development/teething/looking-after-your-babys-teeth/"},{title_en:"Space maintainers",title_ar:"حافظ المسافة للأطفال",description_en:"A small device holding the gap when a baby tooth is lost early, preventing neighbors from drifting into the space the permanent tooth needs.",description_ar:"جهاز صغير بيحافظ على الفراغ لما سن لبنية تتخلع بدري، بيمنع الأسنان المجاورة تميل في المسافة اللي السن الدائمة محتاجاها.",symptoms:{en:"",ar:""},treatment:{en:"",ar:""},prevention:{en:"",ar:""},category:"Kids",source_name:null,source_url:null,last_updated:null,verification_status:"pending_review",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",legacy_source_url:"https://www.mouthhealthy.org/all-topics-a-z/space-maintainers",en:"Space maintainers",ar:"حافظ المسافة للأطفال",sen:"A small device holding the gap when a baby tooth is lost early, preventing neighbors from drifting into the space the permanent tooth needs.",sar:"جهاز صغير بيحافظ على الفراغ لما سن لبنية تتخلع بدري، بيمنع الأسنان المجاورة تميل في المسافة اللي السن الدائمة محتاجاها.",cat:"Kids",src:null},{title_en:"Fissure sealants for children",title_ar:"الحشو الوقائي للأطفال",description_en:"A sealant is a thin protective coating over the grooves of back teeth.\nIt helps keep food and germs out of these grooves.\nAsk your dentist whether your child would benefit when permanent molars appear.",description_ar:"الحشو الوقائي طبقة رفيعة بتحمي شقوق الضروس الخلفية.\nبتساعد تمنع الأكل والميكروبات من دخول الشقوق.\nاسأل الدكتور إذا كان مناسب لطفلك مع ظهور الضروس الدائمة.",symptoms:{en:"Prevention for tooth grooves; pain is not needed to consider it.",ar:"وقاية لشقوق الضروس؛ مش لازم يكون فيه وجع عشان تناقشها."},treatment:{en:"A dentist applies a protective coating to suitable chewing surfaces.",ar:"الدكتور بيحط طبقة حماية على أسطح المضغ المناسبة."},prevention:{en:"Keep brushing with fluoride toothpaste; sealants do not replace cleaning.",ar:"كمل غسيل بمعجون فلورايد؛ الحشو الوقائي مش بديل للتنظيف."},category:"Pediatric",source_name:"NHS",source_url:"https://www.nhs.uk/live-well/healthy-teeth-and-gums/taking-care-of-childrens-teeth/",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",legacy_source_url:"https://www.mouthhealthy.org/all-topics-a-z/sealants",en:"Fissure sealants for children",ar:"الحشو الوقائي للأطفال",sen:"A sealant is a thin protective coating over the grooves of back teeth.\nIt helps keep food and germs out of these grooves.\nAsk your dentist whether your child would benefit when permanent molars appear.",sar:"الحشو الوقائي طبقة رفيعة بتحمي شقوق الضروس الخلفية.\nبتساعد تمنع الأكل والميكروبات من دخول الشقوق.\nاسأل الدكتور إذا كان مناسب لطفلك مع ظهور الضروس الدائمة.",cat:"Pediatric",src:"https://www.nhs.uk/live-well/healthy-teeth-and-gums/taking-care-of-childrens-teeth/"},{title_en:"Braces for adults",title_ar:"تقويم الأسنان للكبار",description_en:"Adults can have orthodontic treatment.\nBraces or aligners move teeth gradually, and treatment time varies.\nAn orthodontist checks the bite and oral health before planning.",description_ar:"الكبار يقدروا يعملوا تقويم أسنان.\nالتقويم أو القوالب بيحركوا الأسنان تدريجياً ومدة العلاج بتختلف.\nالأخصائي بيفحص العضة وصحة الفم قبل التخطيط.",symptoms:{en:"Crowded, spaced or misaligned teeth and bite concerns.",ar:"تزاحم أو فراغات أو عدم انتظام الأسنان ومشاكل العضة."},treatment:{en:"Fixed braces or removable aligners when suitable.",ar:"تقويم ثابت أو قوالب متحركة حسب الملاءمة."},prevention:{en:"Clean carefully around appliances and attend follow-up visits.",ar:"نضف بعناية حوالين الجهاز والتزم بالمتابعة."},category:"Orthodontics",source_name:"Cleveland Clinic",source_url:"https://my.clevelandclinic.org/health/treatments/24601-teeth-braces",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Braces for adults",ar:"تقويم الأسنان للكبار",cat:"Orthodontics",sen:"Adults can have orthodontic treatment.\nBraces or aligners move teeth gradually, and treatment time varies.\nAn orthodontist checks the bite and oral health before planning.",sar:"الكبار يقدروا يعملوا تقويم أسنان.\nالتقويم أو القوالب بيحركوا الأسنان تدريجياً ومدة العلاج بتختلف.\nالأخصائي بيفحص العضة وصحة الفم قبل التخطيط.",src:"https://my.clevelandclinic.org/health/treatments/24601-teeth-braces"},{title_en:"Braces discomfort",title_ar:"ألم التقويم",description_en:"Mild soreness is common after fitting or tightening braces.\nBrackets or wires can irritate the cheeks and lips.\nAsk your orthodontist about persistent pain or a broken appliance.",description_ar:"ألم بسيط شائع بعد تركيب التقويم أو شده.\nالحاصرات والأسلاك ممكن تهيج الخدود والشفتين.\nاسأل الأخصائي عن الألم المستمر أو أي كسر في الجهاز.",symptoms:{en:"Temporary tenderness and irritation inside the mouth.",ar:"حساسية مؤقتة وتهيج داخل الفم."},treatment:{en:"Orthodontic wax may help rough spots; ask about safe pain relief.",ar:"شمع التقويم ممكن يساعد مع الأجزاء الخشنة؛ اسأل عن مسكن مناسب."},prevention:{en:"Choose soft foods initially and avoid hard or sticky foods.",ar:"اختار أكل طري في الأول وتجنب الصلب واللزق."},category:"Orthodontics",source_name:"Cleveland Clinic",source_url:"https://my.clevelandclinic.org/health/treatments/24601-teeth-braces",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Braces discomfort",ar:"ألم التقويم",cat:"Orthodontics",sen:"Mild soreness is common after fitting or tightening braces.\nBrackets or wires can irritate the cheeks and lips.\nAsk your orthodontist about persistent pain or a broken appliance.",sar:"ألم بسيط شائع بعد تركيب التقويم أو شده.\nالحاصرات والأسلاك ممكن تهيج الخدود والشفتين.\nاسأل الأخصائي عن الألم المستمر أو أي كسر في الجهاز.",src:"https://my.clevelandclinic.org/health/treatments/24601-teeth-braces"},{title_en:"Water flossers",title_ar:"خيط الأسنان المائي",description_en:"A pressurized water jet that cleans between teeth and around braces, implants and bridges. Excellent add-on for hard-to-floss areas; it complements rather than fully replaces string floss.",description_ar:"نفث مية مضغوطة بينضف بين الأسنان وحوالين التقويم والزراعة والكباري. إضافة ممتازة للأماكن الصعبة؛ بيكمل الخيط العادي أكتر ما بيغني عنه.",symptoms:{en:"",ar:""},treatment:{en:"",ar:""},prevention:{en:"",ar:""},category:"Prevention",source_name:null,source_url:null,last_updated:null,verification_status:"pending_review",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",legacy_source_url:"https://www.mouthhealthy.org/all-topics-a-z/water-flossers",en:"Water flossers",ar:"خيط الأسنان المائي",sen:"A pressurized water jet that cleans between teeth and around braces, implants and bridges. Excellent add-on for hard-to-floss areas; it complements rather than fully replaces string floss.",sar:"نفث مية مضغوطة بينضف بين الأسنان وحوالين التقويم والزراعة والكباري. إضافة ممتازة للأماكن الصعبة؛ بيكمل الخيط العادي أكتر ما بيغني عنه.",cat:"Prevention",src:null},{title_en:"Interdental brushes",title_ar:"فرش التنظيف بين الأسنان",description_en:"Small interdental brushes clean spaces a normal brush may miss.\nThey can be an alternative to floss, especially where gaps allow a snug fit.\nA dentist or hygienist can help choose a suitable size.",description_ar:"الفرش الصغيرة بتنضف فراغات الفرشاة العادية ممكن متوصلهاش.\nممكن تكون بديل للخيط خصوصاً لو الفراغ يسمح بمقاس مناسب.\nالدكتور أو أخصائي النظافة يساعد يختار الحجم المناسب.",symptoms:{en:"Food or plaque may collect between teeth.",ar:"الأكل أو البلاك ممكن يتجمعوا بين الأسنان."},treatment:{en:"Use a properly fitting brush without forcing it.",ar:"استخدم مقاس مناسب من غير ضغط بالعنف."},prevention:{en:"Clean between teeth daily; avoid wooden toothpicks that can injure gums.",ar:"نضف بين الأسنان يومياً وتجنب الخلة الخشبية اللي ممكن تجرح اللثة."},category:"Prevention",source_name:"NHS",source_url:"https://www.nhs.uk/live-well/healthy-teeth-and-gums/how-to-keep-your-teeth-clean/",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Interdental brushes",ar:"فرش التنظيف بين الأسنان",cat:"Prevention",sen:"Small interdental brushes clean spaces a normal brush may miss.\nThey can be an alternative to floss, especially where gaps allow a snug fit.\nA dentist or hygienist can help choose a suitable size.",sar:"الفرش الصغيرة بتنضف فراغات الفرشاة العادية ممكن متوصلهاش.\nممكن تكون بديل للخيط خصوصاً لو الفراغ يسمح بمقاس مناسب.\nالدكتور أو أخصائي النظافة يساعد يختار الحجم المناسب.",src:"https://www.nhs.uk/live-well/healthy-teeth-and-gums/how-to-keep-your-teeth-clean/"},{title_en:"Acid-related tooth wear",title_ar:"تآكل الأسنان من الأحماض",description_en:"Frequent acid exposure can weaken the protective enamel.\nAcidic foods, drinks and stomach reflux are possible contributors.\nAsk your dentist about wear and seek medical advice for ongoing reflux.",description_ar:"التعرض المتكرر للأحماض ممكن يضعف طبقة المينا.\nالأكل والمشروبات الحمضية وارتجاع المعدة عوامل محتملة.\nاسأل الدكتور عن التآكل وراجع طبيب لو الارتجاع مستمر.",symptoms:{en:"Sensitivity, chips, pitting or changes in colour.",ar:"حساسية أو تكسر أو حفر صغيرة أو تغير لون."},treatment:{en:"Treatment depends on damage and controlling the contributing cause.",ar:"العلاج حسب الضرر والسيطرة على السبب المساهم."},prevention:{en:"Limit acidic drinks, rinse with water and wait before brushing after acid exposure.",ar:"قلل المشروبات الحمضية واشطف بميه واستنى قبل الغسيل بعد الأحماض."},category:"Prevention",source_name:"Cleveland Clinic",source_url:"https://my.clevelandclinic.org/health/diseases/tooth-erosion",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Acid-related tooth wear",ar:"تآكل الأسنان من الأحماض",cat:"Prevention",sen:"Frequent acid exposure can weaken the protective enamel.\nAcidic foods, drinks and stomach reflux are possible contributors.\nAsk your dentist about wear and seek medical advice for ongoing reflux.",sar:"التعرض المتكرر للأحماض ممكن يضعف طبقة المينا.\nالأكل والمشروبات الحمضية وارتجاع المعدة عوامل محتملة.\nاسأل الدكتور عن التآكل وراجع طبيب لو الارتجاع مستمر.",src:"https://my.clevelandclinic.org/health/diseases/tooth-erosion"},{title_en:"Attrition and worn teeth",title_ar:"تآكل الأسنان من الاحتكاك",description_en:"Flattened biting surfaces from years of grinding. Worn teeth can be rebuilt with bonding or crowns after controlling the grinding with a night guard.",description_ar:"تسطّح أسطح المضغ من سنين الصرير. الأسنان المتآكلة ممكن تتبني تاني باللصق التجميلي أو التلبيس بعد السيطرة على الصرير بواقي ليلي.",symptoms:{en:"",ar:""},treatment:{en:"",ar:""},prevention:{en:"",ar:""},category:"Tooth wear",source_name:null,source_url:null,last_updated:null,verification_status:"pending_review",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",legacy_source_url:"https://www.mouthhealthy.org/all-topics-a-z/bruxism",en:"Attrition and worn teeth",ar:"تآكل الأسنان من الاحتكاك",sen:"Flattened biting surfaces from years of grinding. Worn teeth can be rebuilt with bonding or crowns after controlling the grinding with a night guard.",sar:"تسطّح أسطح المضغ من سنين الصرير. الأسنان المتآكلة ممكن تتبني تاني باللصق التجميلي أو التلبيس بعد السيطرة على الصرير بواقي ليلي.",cat:"Tooth wear",src:null},{title_en:"Missing teeth options",title_ar:"اختيارات تعويض الأسنان المفقودة",description_en:"Missing teeth may be replaced with dentures, bridges or implants.\nThe options differ in support, removability and cleaning needs.\nA dentist checks your mouth and discusses preferences before recommending one.",description_ar:"الأسنان المفقودة ممكن تتعوض بطقم أو جسر أو زرعات.\nالاختيارات بتختلف في الدعم وقابلية الإزالة والتنظيف.\nالدكتور يفحص الفم ويناقش تفضيلاتك قبل الترشيح.",symptoms:{en:"Missing teeth can affect eating, speech or appearance.",ar:"فقدان الأسنان ممكن يأثر على الأكل أو الكلام أو الشكل."},treatment:{en:"Choose an individual replacement plan after examination.",ar:"اختار خطة تعويض حسب الحالة بعد الكشف."},prevention:{en:"Clean remaining teeth and any replacement daily.",ar:"نضف الأسنان المتبقية وأي تعويض يومياً."},category:"Treatment",source_name:"Cleveland Clinic",source_url:"https://my.clevelandclinic.org/health/treatments/10900-dentures",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Missing teeth options",ar:"اختيارات تعويض الأسنان المفقودة",cat:"Treatment",sen:"Missing teeth may be replaced with dentures, bridges or implants.\nThe options differ in support, removability and cleaning needs.\nA dentist checks your mouth and discusses preferences before recommending one.",sar:"الأسنان المفقودة ممكن تتعوض بطقم أو جسر أو زرعات.\nالاختيارات بتختلف في الدعم وقابلية الإزالة والتنظيف.\nالدكتور يفحص الفم ويناقش تفضيلاتك قبل الترشيح.",src:"https://my.clevelandclinic.org/health/treatments/10900-dentures"},{title_en:"Full mouth rehabilitation",title_ar:"إعادة تأهيل الفم بالكامل",description_en:"Rebuilding most or all teeth when wear, decay and missing teeth combine. Done in phases after a full diagnosis; a documented case plan sequences gum, root and restorative work.",description_ar:"إعادة بناء أغلب أو كل الأسنان لما التآكل والتسوس والفقد يتجمعوا. بتتعمل على مراحل بعد تشخيص كامل؛ خطة حالة موثقة بترتب شغل اللثة والعصب والتركيبات.",symptoms:{en:"",ar:""},treatment:{en:"",ar:""},prevention:{en:"",ar:""},category:"Prosthodontics",source_name:null,source_url:null,last_updated:null,verification_status:"pending_review",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",legacy_source_url:"https://www.mouthhealthy.org/all-topics-a-z/full-mouth-reconstruction",en:"Full mouth rehabilitation",ar:"إعادة تأهيل الفم بالكامل",sen:"Rebuilding most or all teeth when wear, decay and missing teeth combine. Done in phases after a full diagnosis; a documented case plan sequences gum, root and restorative work.",sar:"إعادة بناء أغلب أو كل الأسنان لما التآكل والتسوس والفقد يتجمعوا. بتتعمل على مراحل بعد تشخيص كامل؛ خطة حالة موثقة بترتب شغل اللثة والعصب والتركيبات.",cat:"Prosthodontics",src:null},{title_en:"Immediate dentures",title_ar:"أطقم الأسنان الفورية",description_en:"An immediate denture is worn after teeth are removed.\nIt may be temporary or may later become the final appliance.\nHealing changes the fit, so follow-up adjustments are important.",description_ar:"الطقم الفوري بيتلبس بعد خلع الأسنان.\nممكن يكون مؤقت أو يبقى التعويض النهائي بعد كده.\nالالتئام بيغير المقاس فالتعديلات والمتابعة مهمين.",symptoms:{en:"Planned tooth removal followed by replacement.",ar:"خلع مخطط وبعده تعويض الأسنان."},treatment:{en:"A dentist plans the denture and monitors fit as tissues heal.",ar:"الدكتور يخطط الطقم ويراجع المقاس مع الالتئام."},prevention:{en:"Follow specific post-extraction and denture-wearing instructions.",ar:"اتبع تعليمات ما بعد الخلع ولبس الطقم الخاصة بحالتك."},category:"Treatment",source_name:"Cleveland Clinic",source_url:"https://my.clevelandclinic.org/health/treatments/10900-dentures",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Immediate dentures",ar:"أطقم الأسنان الفورية",cat:"Treatment",sen:"An immediate denture is worn after teeth are removed.\nIt may be temporary or may later become the final appliance.\nHealing changes the fit, so follow-up adjustments are important.",sar:"الطقم الفوري بيتلبس بعد خلع الأسنان.\nممكن يكون مؤقت أو يبقى التعويض النهائي بعد كده.\nالالتئام بيغير المقاس فالتعديلات والمتابعة مهمين.",src:"https://my.clevelandclinic.org/health/treatments/10900-dentures"},{title_en:"Denture sore spots",title_ar:"أماكن الألم تحت طقم الأسنان",description_en:"A denture can rub or pinch gums if its fit changes.\nIt may need professional adjustment or relining.\nSee a dentist for sore gums, a loose appliance or clicking during speech.",description_ar:"الطقم ممكن يحتك باللثة أو يضغط عليها لما المقاس يتغير.\nممكن يحتاج تعديل عند مختص أو تبطين.\nاكشف لو اللثة مؤلمة أو الطقم بيتحرك أو بيعمل صوت مع الكلام.",symptoms:{en:"Pain, pinching, looseness or clicking.",ar:"ألم أو ضغط أو حركة أو صوت طقطقة."},treatment:{en:"A dentist checks fit and adjusts or replaces the appliance as needed.",ar:"الدكتور يراجع المقاس ويعدل أو يغير الطقم حسب الاحتياج."},prevention:{en:"Keep dentures clean and remove them as instructed to rest gums.",ar:"حافظ على نظافة الطقم وشيله حسب التعليمات عشان تريح اللثة."},category:"Oral health",source_name:"Cleveland Clinic",source_url:"https://my.clevelandclinic.org/health/treatments/10900-dentures",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Denture sore spots",ar:"أماكن الألم تحت طقم الأسنان",cat:"Oral health",sen:"A denture can rub or pinch gums if its fit changes.\nIt may need professional adjustment or relining.\nSee a dentist for sore gums, a loose appliance or clicking during speech.",sar:"الطقم ممكن يحتك باللثة أو يضغط عليها لما المقاس يتغير.\nممكن يحتاج تعديل عند مختص أو تبطين.\nاكشف لو اللثة مؤلمة أو الطقم بيتحرك أو بيعمل صوت مع الكلام.",src:"https://my.clevelandclinic.org/health/treatments/10900-dentures"},{title_en:"Crown fell off",title_ar:"التلبيسة وقعت",description_en:"Keep the crown, do not glue it with household adhesives. A dentist can often re-cement it if the tooth underneath is intact; see them within days.",description_ar:"احتفظ بالتلبيسة، ومتلزقهاش بلزق البيت. الدكتور غالبًا يقدر يسمنتها تاني لو السن تحتها سليمة؛ روحله خلال أيام.",symptoms:{en:"",ar:""},treatment:{en:"",ar:""},prevention:{en:"",ar:""},category:"Emergencies",source_name:null,source_url:null,last_updated:null,verification_status:"pending_review",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",legacy_source_url:"https://www.mouthhealthy.org/all-topics-a-z/crowns",en:"Crown fell off",ar:"التلبيسة وقعت",sen:"Keep the crown, do not glue it with household adhesives. A dentist can often re-cement it if the tooth underneath is intact; see them within days.",sar:"احتفظ بالتلبيسة، ومتلزقهاش بلزق البيت. الدكتور غالبًا يقدر يسمنتها تاني لو السن تحتها سليمة؛ روحله خلال أيام.",cat:"Emergencies",src:null},{title_en:"Food stuck between teeth",title_ar:"أكل بيتحشر بين الأسنان",description_en:"Regular food impaction signals a cavity, a failing filling or gum recession creating a gap. It is worth a visit - the trapped food accelerates decay and gum inflammation.",description_ar:"تحشّر الأكل المتكرر بيشير لتسوس أو حشوة بتبوظ أو انحسار لثة بيخلي فراغ. يستاهل زيارة - الأكل المحشور بيسرع التسوس والتهاب اللثة.",symptoms:{en:"",ar:""},treatment:{en:"",ar:""},prevention:{en:"",ar:""},category:"Symptoms",source_name:null,source_url:null,last_updated:null,verification_status:"pending_review",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",legacy_source_url:"https://www.mouthhealthy.org/all-topics-a-z/food-impaction",en:"Food stuck between teeth",ar:"أكل بيتحشر بين الأسنان",sen:"Regular food impaction signals a cavity, a failing filling or gum recession creating a gap. It is worth a visit - the trapped food accelerates decay and gum inflammation.",sar:"تحشّر الأكل المتكرر بيشير لتسوس أو حشوة بتبوظ أو انحسار لثة بيخلي فراغ. يستاهل زيارة - الأكل المحشور بيسرع التسوس والتهاب اللثة.",cat:"Symptoms",src:null},{title_en:"Pain when biting",title_ar:"ألم عند العض",description_en:"Pain when biting has several possible dental causes.\nA crack or inflammation around a tooth may need specialist testing.\nAn examination is needed before choosing treatment.",description_ar:"ألم العض ليه أسباب مختلفة في الأسنان.\nشرخ أو التهاب حوالين السن ممكن يحتاج اختبارات مختص.\nلازم كشف قبل اختيار العلاج.",symptoms:{en:"Pain on chewing, touching or tapping a tooth.",ar:"ألم مع المضغ أو لمس السن أو الطرق عليه."},treatment:{en:"The dentist checks the tooth, bite and surrounding tissues.",ar:"الدكتور يفحص السن والعضة والأنسجة حواليه."},prevention:{en:"Report new pain promptly and avoid delaying a dental visit.",ar:"بلغ عن الألم الجديد بسرعة ومتأجلش الكشف."},category:"Oral health",source_name:"Cleveland Clinic",source_url:"https://my.clevelandclinic.org/health/articles/16959-endodontics",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Pain when biting",ar:"ألم عند العض",cat:"Oral health",sen:"Pain when biting has several possible dental causes.\nA crack or inflammation around a tooth may need specialist testing.\nAn examination is needed before choosing treatment.",sar:"ألم العض ليه أسباب مختلفة في الأسنان.\nشرخ أو التهاب حوالين السن ممكن يحتاج اختبارات مختص.\nلازم كشف قبل اختيار العلاج.",src:"https://my.clevelandclinic.org/health/articles/16959-endodontics"},{title_en:"Throbbing tooth pain at night",title_ar:"وجع سن نابض بالليل",description_en:"Throbbing or lingering tooth pain may come from inflamed pulp.\nSymptoms alone cannot identify the exact cause.\nArrange dental assessment rather than repeatedly masking the pain.",description_ar:"وجع السن النابض أو المستمر ممكن ييجي من التهاب اللب.\nالأعراض لوحدها متحددش السبب بالضبط.\nرتب كشف أسنان بدل الاكتفاء بإخفاء الألم كل مرة.",symptoms:{en:"Throbbing, sharp or aching tooth pain and lingering sensitivity.",ar:"وجع نابض أو حاد أو مستمر وحساسية مبتروحش بسرعة."},treatment:{en:"A dentist examines and tests the tooth before treating the cause.",ar:"الدكتور يفحص ويختبر السن قبل علاج السبب."},prevention:{en:"Treat decay early and tell the dentist about new sensitivity.",ar:"عالج التسوس بدري وبلغ الدكتور بأي حساسية جديدة."},category:"Emergency",source_name:"Cleveland Clinic",source_url:"https://my.clevelandclinic.org/health/diseases/23536-pulpitis",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Throbbing tooth pain at night",ar:"وجع سن نابض بالليل",cat:"Emergency",sen:"Throbbing or lingering tooth pain may come from inflamed pulp.\nSymptoms alone cannot identify the exact cause.\nArrange dental assessment rather than repeatedly masking the pain.",sar:"وجع السن النابض أو المستمر ممكن ييجي من التهاب اللب.\nالأعراض لوحدها متحددش السبب بالضبط.\nرتب كشف أسنان بدل الاكتفاء بإخفاء الألم كل مرة.",src:"https://my.clevelandclinic.org/health/diseases/23536-pulpitis"},{title_en:"Pulpitis",title_ar:"التهاب لب السن",description_en:"Pulpitis is inflammation of the soft tissue inside a tooth.\nDecay, cracks or other irritation can cause it.\nA dentist tests the tooth to decide whether the pulp can recover.",description_ar:"التهاب اللب بيصيب النسيج الطري جوه السن.\nالتسوس أو الشروخ أو تهيج تاني ممكن يسببوه.\nالدكتور بيختبر السن عشان يحدد إذا كان اللب يقدر يتعافى.",symptoms:{en:"Toothache or sensitivity, which may be brief or lingering.",ar:"وجع سن أو حساسية ممكن تكون سريعة أو مستمرة."},treatment:{en:"Removing decay and sealing the tooth, or root canal treatment/extraction if needed.",ar:"إزالة تسوس وقفل السن أو علاج جذور أو خلع حسب الاحتياج."},prevention:{en:"Seek care for new pain and maintain daily cleaning.",ar:"اكشف مع الألم الجديد وحافظ على التنظيف اليومي."},category:"Oral health",source_name:"Cleveland Clinic",source_url:"https://my.clevelandclinic.org/health/diseases/23536-pulpitis",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Pulpitis",ar:"التهاب لب السن",cat:"Oral health",sen:"Pulpitis is inflammation of the soft tissue inside a tooth.\nDecay, cracks or other irritation can cause it.\nA dentist tests the tooth to decide whether the pulp can recover.",sar:"التهاب اللب بيصيب النسيج الطري جوه السن.\nالتسوس أو الشروخ أو تهيج تاني ممكن يسببوه.\nالدكتور بيختبر السن عشان يحدد إذا كان اللب يقدر يتعافى.",src:"https://my.clevelandclinic.org/health/diseases/23536-pulpitis"},{title_en:"Root canal retreatment",title_ar:"إعادة علاج الجذور",description_en:"A previously root-treated tooth may sometimes fail to heal properly.\nRetreatment removes and replaces materials inside the root canals.\nA dentist or endodontist checks whether this can save the tooth.",description_ar:"سن اتعمله علاج جذور ممكن أحياناً ميلتئمش كويس.\nإعادة العلاج بتشيل وتستبدل المواد جوه قنوات الجذر.\nالدكتور أو أخصائي الجذور يقيم إمكانية إنقاذ السن.",symptoms:{en:"Persistent or recurring pain or inflammation after previous treatment.",ar:"ألم أو التهاب مستمر أو راجع بعد علاج سابق."},treatment:{en:"Specialist assessment followed by retreatment or another suitable option.",ar:"تقييم مختص وبعده إعادة علاج أو اختيار مناسب تاني."},prevention:{en:"Complete restorations and return for ongoing dental checks.",ar:"كمل الترميمات وارجع لكشف الأسنان المستمر."},category:"Treatment",source_name:"Cleveland Clinic",source_url:"https://my.clevelandclinic.org/health/articles/16959-endodontics",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Root canal retreatment",ar:"إعادة علاج الجذور",cat:"Treatment",sen:"A previously root-treated tooth may sometimes fail to heal properly.\nRetreatment removes and replaces materials inside the root canals.\nA dentist or endodontist checks whether this can save the tooth.",sar:"سن اتعمله علاج جذور ممكن أحياناً ميلتئمش كويس.\nإعادة العلاج بتشيل وتستبدل المواد جوه قنوات الجذر.\nالدكتور أو أخصائي الجذور يقيم إمكانية إنقاذ السن.",src:"https://my.clevelandclinic.org/health/articles/16959-endodontics"},{title_en:"Apicoectomy",title_ar:"استئصال قمة الجذر",description_en:"Apicoectomy is surgery that removes the tip of a tooth root.\nIt is one of the procedures an endodontist may use to save a tooth.\nSuitability depends on a detailed examination of the root problem.",description_ar:"استئصال قمة الجذر جراحة بتشيل طرف جذر السن.\nواحد من الإجراءات اللي أخصائي الجذور ممكن يستخدمها لإنقاذ السن.\nالملاءمة حسب فحص مفصل لمشكلة الجذر.",symptoms:{en:"Persistent root-related pain or inflammation may need specialist assessment.",ar:"ألم أو التهاب مستمر مرتبط بالجذر ممكن يحتاج تقييم أخصائي."},treatment:{en:"Endodontic assessment and a tailored surgical plan when indicated.",ar:"تقييم أخصائي جذور وخطة جراحة حسب الحالة لما تلزم."},prevention:{en:"Follow surgical instructions and restoration follow-up.",ar:"اتبع تعليمات الجراحة ومتابعة الترميم."},category:"Surgery",source_name:"Cleveland Clinic",source_url:"https://my.clevelandclinic.org/health/articles/16959-endodontics",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Apicoectomy",ar:"استئصال قمة الجذر",cat:"Surgery",sen:"Apicoectomy is surgery that removes the tip of a tooth root.\nIt is one of the procedures an endodontist may use to save a tooth.\nSuitability depends on a detailed examination of the root problem.",sar:"استئصال قمة الجذر جراحة بتشيل طرف جذر السن.\nواحد من الإجراءات اللي أخصائي الجذور ممكن يستخدمها لإنقاذ السن.\nالملاءمة حسب فحص مفصل لمشكلة الجذر.",src:"https://my.clevelandclinic.org/health/articles/16959-endodontics"},{title_en:"Dental seal of fillings",title_ar:"تسرب الحشوات",description_en:"Fillings age: edges leak, bacteria get underneath (secondary decay). Regular checkups catch leaking fillings before the decay reaches the nerve.",description_ar:"الحشوات بتتقادم: الحواف بتسرب والبكتيريا بتدخل تحتها (تسوس ثانوي). الكشف الدوري بيلقط الحشوة المسربة قبل ما التسوس يوصل للعصب.",symptoms:{en:"",ar:""},treatment:{en:"",ar:""},prevention:{en:"",ar:""},category:"Restorative",source_name:null,source_url:null,last_updated:null,verification_status:"pending_review",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",legacy_source_url:"https://www.mouthhealthy.org/all-topics-a-z/fillings",en:"Dental seal of fillings",ar:"تسرب الحشوات",sen:"Fillings age: edges leak, bacteria get underneath (secondary decay). Regular checkups catch leaking fillings before the decay reaches the nerve.",sar:"الحشوات بتتقادم: الحواف بتسرب والبكتيريا بتدخل تحتها (تسوس ثانوي). الكشف الدوري بيلقط الحشوة المسربة قبل ما التسوس يوصل للعصب.",cat:"Restorative",src:null},{title_en:"Amalgam vs composite",title_ar:"الحشو الفضي والأبيض",description_en:"Composite matches tooth color and bonds to the tooth; amalgam is durable but silver and being phased down. The right choice depends on the cavity size and location.",description_ar:"الأبيض بنفس لون السن وبيلتصق بيها؛ الفضي متين لكن لونه فضي واستخدامه بيقل. الاختيار الصح بيعتمد على حجم التسوس ومكانه.",symptoms:{en:"",ar:""},treatment:{en:"",ar:""},prevention:{en:"",ar:""},category:"Restorative",source_name:null,source_url:null,last_updated:null,verification_status:"pending_review",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",legacy_source_url:"https://www.mouthhealthy.org/all-topics-a-z/fillings",en:"Amalgam vs composite",ar:"الحشو الفضي والأبيض",sen:"Composite matches tooth color and bonds to the tooth; amalgam is durable but silver and being phased down. The right choice depends on the cavity size and location.",sar:"الأبيض بنفس لون السن وبيلتصق بيها؛ الفضي متين لكن لونه فضي واستخدامه بيقل. الاختيار الصح بيعتمد على حجم التسوس ومكانه.",cat:"Restorative",src:null},{title_en:"Bite adjustment",title_ar:"تعديل الإطباقة",description_en:"If a new filling or crown feels high when you close, a one-minute polish fixes it. Leaving it high can bruise the ligament and mimic nerve pain.",description_ar:"لو حشوة أو تلبيسة جديدة حاسس إنها عالية لما تقفل، تلميعة دقيقة بتحلها. سيبها عالية ممكن تكدم الرباط وتقلد ألم العصب.",symptoms:{en:"",ar:""},treatment:{en:"",ar:""},prevention:{en:"",ar:""},category:"Restorative",source_name:null,source_url:null,last_updated:null,verification_status:"pending_review",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",legacy_source_url:"https://www.mouthhealthy.org/all-topics-a-z/fillings",en:"Bite adjustment",ar:"تعديل الإطباقة",sen:"If a new filling or crown feels high when you close, a one-minute polish fixes it. Leaving it high can bruise the ligament and mimic nerve pain.",sar:"لو حشوة أو تلبيسة جديدة حاسس إنها عالية لما تقفل، تلميعة دقيقة بتحلها. سيبها عالية ممكن تكدم الرباط وتقلد ألم العصب.",cat:"Restorative",src:null},{title_en:"Sensitivity after whitening",title_ar:"حساسية بعد التبييض",description_en:"Teeth may become temporarily sensitive after whitening.\nGum soreness can also occur, even with professional treatment.\nSpeak to your dentist if the effects are painful or worrying.",description_ar:"الأسنان ممكن تبقى حساسة مؤقتاً بعد التبييض.\nممكن كمان يحصل وجع لثة حتى مع العلاج عند مختص.\nكلم دكتورك لو الأعراض مؤلمة أو مقلقاك.",symptoms:{en:"Cold or sweet sensitivity and sore gums.",ar:"حساسية للبارد أو الحلو ووجع في اللثة."},treatment:{en:"Ask the dentist who supervised the whitening for advice.",ar:"ارجع للدكتور المشرف على التبييض للنصيحة المناسبة."},prevention:{en:"Have a dental check before whitening and follow the instructions.",ar:"اكشف قبل التبييض والتزم بالتعليمات."},category:"Oral health",source_name:"NHS",source_url:"https://www.nhs.uk/tests-and-treatments/teeth-whitening/",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Sensitivity after whitening",ar:"حساسية بعد التبييض",cat:"Oral health",sen:"Teeth may become temporarily sensitive after whitening.\nGum soreness can also occur, even with professional treatment.\nSpeak to your dentist if the effects are painful or worrying.",sar:"الأسنان ممكن تبقى حساسة مؤقتاً بعد التبييض.\nممكن كمان يحصل وجع لثة حتى مع العلاج عند مختص.\nكلم دكتورك لو الأعراض مؤلمة أو مقلقاك.",src:"https://www.nhs.uk/tests-and-treatments/teeth-whitening/"},{title_en:"Smile design",title_ar:"تصميم الابتسامة",description_en:"Smile planning starts with your goals and a dental examination.\nWhitening, bonding, veneers or contouring may change appearance.\nDiscuss risks, maintenance and irreversible steps before choosing.",description_ar:"تخطيط الابتسامة بيبدأ بأهدافك وكشف أسنان.\nالتبييض أو البوندنج أو القشور أو التجميل ممكن يغيروا الشكل.\nناقش المخاطر والعناية وأي خطوات لا يمكن الرجوع فيها قبل الاختيار.",symptoms:{en:"Concerns about tooth colour, shape, gaps or gum appearance.",ar:"قلق من لون أو شكل الأسنان أو الفراغات أو شكل اللثة."},treatment:{en:"An individual plan after checking oral health.",ar:"خطة حسب الحالة بعد تقييم صحة الفم."},prevention:{en:"Continue routine dental checks and daily cleaning.",ar:"كمل كشوف الأسنان والتنظيف اليومي."},category:"Cosmetic",source_name:"Cleveland Clinic",source_url:"https://my.clevelandclinic.org/health/treatments/23914-cosmetic-dentistry",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Smile design",ar:"تصميم الابتسامة",cat:"Cosmetic",sen:"Smile planning starts with your goals and a dental examination.\nWhitening, bonding, veneers or contouring may change appearance.\nDiscuss risks, maintenance and irreversible steps before choosing.",sar:"تخطيط الابتسامة بيبدأ بأهدافك وكشف أسنان.\nالتبييض أو البوندنج أو القشور أو التجميل ممكن يغيروا الشكل.\nناقش المخاطر والعناية وأي خطوات لا يمكن الرجوع فيها قبل الاختيار.",src:"https://my.clevelandclinic.org/health/treatments/23914-cosmetic-dentistry"},{title_en:"Oral hygiene with braces",title_ar:"النظافة مع التقويم",description_en:"Braces need careful daily cleaning around brackets and wires.\nUse fluoride toothpaste and an interdental brush as advised.\nContact your orthodontist for broken braces or gums that become very sore or swollen.",description_ar:"التقويم محتاج تنظيف يومي بعناية حوالين الحاصرات والسلك.\nاستخدم معجون فلورايد وفرشاة بين الأسنان حسب تعليمات الأخصائي.\nكلمه لو التقويم اتكسر أو اللثة بقت وارمة أو بتوجع بشدة.",symptoms:{en:"Red, sore or swollen gums need attention.",ar:"احمرار أو وجع أو ورم اللثة محتاج اهتمام."},treatment:{en:"The orthodontist checks problems with the appliance or gum health.",ar:"أخصائي التقويم بيفحص مشاكل الجهاز أو صحة اللثة."},prevention:{en:"Keep regular dental checks and limit sugary, hard and sticky foods.",ar:"تابع كشوف الأسنان وقلل السكريات والأكل الصلب واللزق."},category:"Orthodontics",source_name:"NHS",source_url:"https://www.nhs.uk/tests-and-treatments/braces/",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",legacy_source_url:"https://www.mouthhealthy.org/all-topics-a-z/braces",en:"Oral hygiene with braces",ar:"النظافة مع التقويم",sen:"Braces need careful daily cleaning around brackets and wires.\nUse fluoride toothpaste and an interdental brush as advised.\nContact your orthodontist for broken braces or gums that become very sore or swollen.",sar:"التقويم محتاج تنظيف يومي بعناية حوالين الحاصرات والسلك.\nاستخدم معجون فلورايد وفرشاة بين الأسنان حسب تعليمات الأخصائي.\nكلمه لو التقويم اتكسر أو اللثة بقت وارمة أو بتوجع بشدة.",cat:"Orthodontics",src:"https://www.nhs.uk/tests-and-treatments/braces/"},{title_en:"Canker sore relief",title_ar:"تخفيف قرح الفم",description_en:"Salt-water rinses, avoiding spicy and acidic food, and protective pastes ease the pain while the sore heals over 1-2 weeks. See a dentist for frequent or large ulcers.",description_ar:"مضمضة بمية وملح، وتجنب الحار والحامض، ومعاجين حماية بتهدي الألم لحد ما القرحة تتقفل في أسبوع-أسبوعين. روح للدكتور لو القرح كتير أو كبيرة.",symptoms:{en:"",ar:""},treatment:{en:"",ar:""},prevention:{en:"",ar:""},category:"Soft tissue",source_name:null,source_url:null,last_updated:null,verification_status:"pending_review",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",legacy_source_url:"https://www.mouthhealthy.org/all-topics-a-z/canker-sores",en:"Canker sore relief",ar:"تخفيف قرح الفم",sen:"Salt-water rinses, avoiding spicy and acidic food, and protective pastes ease the pain while the sore heals over 1-2 weeks. See a dentist for frequent or large ulcers.",sar:"مضمضة بمية وملح، وتجنب الحار والحامض، ومعاجين حماية بتهدي الألم لحد ما القرحة تتقفل في أسبوع-أسبوعين. روح للدكتور لو القرح كتير أو كبيرة.",cat:"Soft tissue",src:null},{title_en:"Cold sore transmission",title_ar:"عدوى قرح البرد",description_en:"A cold sore is contagious from the first tingling until fully healed.\nIt can spread through close contact and to other body areas.\nKissing a newborn with a cold sore can cause dangerous neonatal herpes.",description_ar:"قرحة البرد معدية من أول وخز لحد الالتئام الكامل.\nممكن تنتقل بالمخالطة القريبة ولمناطق تانية بالجسم.\nتقبيل مولود مع وجود قرحة برد ممكن يسبب هربس خطير للرضيع.",symptoms:{en:"Tingling can precede visible blisters.",ar:"الوخز ممكن يسبق الفقاقيع الظاهرة."},treatment:{en:"Ask a clinician for advice for severe, recurrent sores or weak immunity.",ar:"اسأل الطبيب لو القرح شديدة أو بتتكرر أو المناعة ضعيفة."},prevention:{en:"No kissing or oral sex until healed; wash hands and avoid touching sores.",ar:"تجنب التقبيل والجنس الفموي لحد الالتئام واغسل إيدك ومتلمسش القرح."},category:"Prevention",source_name:"NHS",source_url:"https://www.nhs.uk/conditions/cold-sores/",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Cold sore transmission",ar:"عدوى قرح البرد",cat:"Prevention",sen:"A cold sore is contagious from the first tingling until fully healed.\nIt can spread through close contact and to other body areas.\nKissing a newborn with a cold sore can cause dangerous neonatal herpes.",sar:"قرحة البرد معدية من أول وخز لحد الالتئام الكامل.\nممكن تنتقل بالمخالطة القريبة ولمناطق تانية بالجسم.\nتقبيل مولود مع وجود قرحة برد ممكن يسبب هربس خطير للرضيع.",src:"https://www.nhs.uk/conditions/cold-sores/"},{title_en:"Zirconia crowns",title_ar:"تركيبات الزيركون",description_en:"Zirconia is a strong ceramic material used to make dental crowns.\nA crown covers a prepared tooth to restore its shape and function.\nYour dentist checks your bite and tooth before recommending a material.",description_ar:"الزيركون مادة سيراميك قوية بتستخدم في تلبيسات الأسنان.\nالتلبيسة بتغطي السن بعد تحضيره عشان ترجع شكله ووظيفته.\nالدكتور بيفحص السن والعضة قبل اختيار المادة.",symptoms:{en:"A weak, broken or damaged tooth may need a crown.",ar:"السن الضعيف أو المكسور أو المتضرر ممكن يحتاج تلبيسة."},treatment:{en:"Tooth preparation, impressions and fitting a custom crown.",ar:"تحضير السن ومقاسات وبعدها تركيب تلبيسة مناسبة."},prevention:{en:"Clean around the crown and avoid biting very hard objects.",ar:"نضف حوالين التلبيسة ومتعضش على حاجات شديدة الصلابة."},category:"Cosmetic",source_name:"Cleveland Clinic",source_url:"https://my.clevelandclinic.org/health/treatments/10923-dental-crowns",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Zirconia crowns",ar:"تركيبات الزيركون",cat:"Cosmetic",sen:"Zirconia is a strong ceramic material used to make dental crowns.\nA crown covers a prepared tooth to restore its shape and function.\nYour dentist checks your bite and tooth before recommending a material.",sar:"الزيركون مادة سيراميك قوية بتستخدم في تلبيسات الأسنان.\nالتلبيسة بتغطي السن بعد تحضيره عشان ترجع شكله ووظيفته.\nالدكتور بيفحص السن والعضة قبل اختيار المادة.",src:"https://my.clevelandclinic.org/health/treatments/10923-dental-crowns"},{title_en:"Surgical wisdom tooth extraction",title_ar:"خلع ضرس العقل جراحياً",description_en:"A problem wisdom tooth may need a surgical removal.\nThe dentist may open the gum and divide the tooth before removing it.\nAsk about the procedure, healing and nerve-injury risk before treatment.",description_ar:"ضرس العقل اللي مسبب مشكلة ممكن يحتاج خلع جراحي.\nالدكتور ممكن يفتح اللثة ويقسم الضرس قبل إخراجه.\nاسأل عن الخطوات والالتئام واحتمال إصابة الأعصاب قبل العلاج.",symptoms:{en:"Pain, infection or other problems around a wisdom tooth.",ar:"ألم أو التهاب أو مشاكل تانية حوالين ضرس العقل."},treatment:{en:"Assessment, sometimes X-rays, then removal with appropriate anaesthesia.",ar:"تقييم وأحياناً أشعة وبعدها الخلع بالتخدير المناسب."},prevention:{en:"Follow the surgeon’s cleaning and aftercare instructions; avoid smoking.",ar:"التزم بتعليمات الجراح للتنظيف والعناية وتجنب التدخين."},category:"Surgery",source_name:"NHS",source_url:"https://www.nhs.uk/tests-and-treatments/wisdom-tooth-removal/",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Surgical wisdom tooth extraction",ar:"خلع ضرس العقل جراحياً",cat:"Surgery",sen:"A problem wisdom tooth may need a surgical removal.\nThe dentist may open the gum and divide the tooth before removing it.\nAsk about the procedure, healing and nerve-injury risk before treatment.",sar:"ضرس العقل اللي مسبب مشكلة ممكن يحتاج خلع جراحي.\nالدكتور ممكن يفتح اللثة ويقسم الضرس قبل إخراجه.\nاسأل عن الخطوات والالتئام واحتمال إصابة الأعصاب قبل العلاج.",src:"https://www.nhs.uk/tests-and-treatments/wisdom-tooth-removal/"},{title_en:"Dental crown materials",title_ar:"مواد تلبيسات الأسنان",description_en:"Crowns can be made from metal, resin or different ceramics.\nEach option has advantages and limitations in strength and appearance.\nDiscuss your tooth, bite, preferences and budget with the dentist.",description_ar:"التلبيسات ممكن تتعمل من معدن أو راتنج أو أنواع سيراميك.\nكل اختيار ليه مميزات وحدود في القوة والشكل.\nناقش مع الدكتور السن والعضة وتفضيلاتك والميزانية.",symptoms:{en:"A damaged or weak tooth may need coverage.",ar:"سن ضعيف أو متضرر ممكن يحتاج تغطية."},treatment:{en:"The dentist selects a suitable crown design and material.",ar:"الدكتور بيختار تصميم ومادة مناسبة للتلبيسة."},prevention:{en:"Regular cleaning and checks help maintain any crown type.",ar:"التنظيف والمتابعة بيساعدوا في الحفاظ على أي نوع تلبيسة."},category:"Treatment",source_name:"Cleveland Clinic",source_url:"https://my.clevelandclinic.org/health/treatments/10923-dental-crowns",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Dental crown materials",ar:"مواد تلبيسات الأسنان",cat:"Treatment",sen:"Crowns can be made from metal, resin or different ceramics.\nEach option has advantages and limitations in strength and appearance.\nDiscuss your tooth, bite, preferences and budget with the dentist.",sar:"التلبيسات ممكن تتعمل من معدن أو راتنج أو أنواع سيراميك.\nكل اختيار ليه مميزات وحدود في القوة والشكل.\nناقش مع الدكتور السن والعضة وتفضيلاتك والميزانية.",src:"https://my.clevelandclinic.org/health/treatments/10923-dental-crowns"},{title_en:"Temporary crowns",title_ar:"التلبيسة المؤقتة",description_en:"A temporary crown may protect a prepared tooth while the final crown is made.\nIt is not the final restoration.\nContact your dentist if it loosens, breaks or causes a sharp edge.",description_ar:"التلبيسة المؤقتة ممكن تحمي السن المحضر لحد ما النهائية تجهز.\nهي مش التعويض النهائي.\nكلم الدكتور لو اتحركت أو اتكسرت أو بقت حادة.",symptoms:{en:"A prepared tooth waiting for its final crown.",ar:"سن محضر ومستني التلبيسة النهائية."},treatment:{en:"Temporary coverage followed by the final crown fitting.",ar:"تغطية مؤقتة وبعدها تركيب التلبيسة النهائية."},prevention:{en:"Avoid very sticky or hard foods and follow cleaning advice.",ar:"تجنب الأكل الشديد اللزوجة أو الصلابة واتبع تعليمات التنظيف."},category:"Treatment",source_name:"Cleveland Clinic",source_url:"https://my.clevelandclinic.org/health/treatments/10923-dental-crowns",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Temporary crowns",ar:"التلبيسة المؤقتة",cat:"Treatment",sen:"A temporary crown may protect a prepared tooth while the final crown is made.\nIt is not the final restoration.\nContact your dentist if it loosens, breaks or causes a sharp edge.",sar:"التلبيسة المؤقتة ممكن تحمي السن المحضر لحد ما النهائية تجهز.\nهي مش التعويض النهائي.\nكلم الدكتور لو اتحركت أو اتكسرت أو بقت حادة.",src:"https://my.clevelandclinic.org/health/treatments/10923-dental-crowns"},{title_en:"Tongue cleaning",title_ar:"تنظيف اللسان",description_en:"Gentle tongue cleaning is part of caring for bad breath.\nUse a tongue scraper or cleaner once daily.\nDo not scrub so hard that the tongue bleeds; persistent odour needs a dental check.",description_ar:"تنظيف اللسان برفق جزء من العناية برائحة الفم.\nاستخدم منظف أو مكشطة لسان مرة يومياً.\nمتدعكش لحد النزيف؛ الرائحة المستمرة محتاجة كشف.",symptoms:{en:"Unpleasant breath may improve with better oral cleaning.",ar:"رائحة الفم ممكن تتحسن مع تنظيف الفم بشكل أحسن."},treatment:{en:"A dentist checks persistent bad breath for other causes.",ar:"الدكتور بيفحص الرائحة المستمرة عشان أسباب تانية."},prevention:{en:"Combine gentle tongue care with toothbrushing and cleaning between teeth.",ar:"اجمع تنظيف اللسان برفق مع غسيل الأسنان والتنظيف بينها."},category:"Prevention",source_name:"NHS",source_url:"https://www.nhs.uk/symptoms/bad-breath/",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Tongue cleaning",ar:"تنظيف اللسان",cat:"Prevention",sen:"Gentle tongue cleaning is part of caring for bad breath.\nUse a tongue scraper or cleaner once daily.\nDo not scrub so hard that the tongue bleeds; persistent odour needs a dental check.",sar:"تنظيف اللسان برفق جزء من العناية برائحة الفم.\nاستخدم منظف أو مكشطة لسان مرة يومياً.\nمتدعكش لحد النزيف؛ الرائحة المستمرة محتاجة كشف.",src:"https://www.nhs.uk/symptoms/bad-breath/"},{title_en:"Bruxism and sleep habits",title_ar:"الجز على الأسنان وعادات النوم",description_en:"Grinding during sleep may be noticed by a partner before you notice symptoms.\nA regular bedtime and a quiet, dark bedroom can support better sleep.\nSee a dentist for damage or pain, and a clinician for persistent sleep problems.",description_ar:"الجز أثناء النوم ممكن شريكك يلاحظه قبل ما تحس بأعراض.\nميعاد نوم منتظم وغرفة هادية وضلمة بيساعدوا النوم.\nاكشف أسنان لو فيه ضرر أو وجع وراجع طبيب لو مشاكل النوم مستمرة.",symptoms:{en:"Grinding sounds, disturbed sleep or sore jaw on waking.",ar:"صوت جز أو نوم متقطع أو وجع فك عند الاستيقاظ."},treatment:{en:"A dentist assesses protection needs and a clinician can address sleep issues.",ar:"الدكتور يقيم الحاجة لحماية الأسنان والطبيب يراجع مشاكل النوم."},prevention:{en:"Relax before bed and avoid excess caffeine and alcohol.",ar:"استرخي قبل النوم وتجنب زيادة الكافيين والكحول."},category:"Oral health",source_name:"NHS",source_url:"https://www.nhs.uk/symptoms/teeth-grinding/",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Bruxism and sleep habits",ar:"الجز على الأسنان وعادات النوم",cat:"Oral health",sen:"Grinding during sleep may be noticed by a partner before you notice symptoms.\nA regular bedtime and a quiet, dark bedroom can support better sleep.\nSee a dentist for damage or pain, and a clinician for persistent sleep problems.",sar:"الجز أثناء النوم ممكن شريكك يلاحظه قبل ما تحس بأعراض.\nميعاد نوم منتظم وغرفة هادية وضلمة بيساعدوا النوم.\nاكشف أسنان لو فيه ضرر أو وجع وراجع طبيب لو مشاكل النوم مستمرة.",src:"https://www.nhs.uk/symptoms/teeth-grinding/"},{title_en:"Sugar and tooth decay",title_ar:"السكر وتسوس الأسنان",description_en:"Plaque bacteria turn free sugars into acids that damage teeth.\nFrequent high sugar intake increases the risk of decay.\nChoose a balanced diet and ask your dentist about personal risk.",description_ar:"بكتيريا البلاك بتحول السكريات الحرة لأحماض بتضر الأسنان.\nاستهلاك سكر كتير باستمرار بيزود احتمال التسوس.\nاختار أكل متوازن واسأل دكتورك عن عوامل الخطورة عندك.",symptoms:{en:"Early decay can be painless; a dental check can identify it.",ar:"التسوس المبكر ممكن ميوجعش؛ الكشف يقدر يكتشفه."},treatment:{en:"Dental care depends on the stage of decay.",ar:"علاج الأسنان حسب مرحلة التسوس."},prevention:{en:"Reduce free sugars and brush twice daily with fluoride toothpaste.",ar:"قلل السكريات الحرة واغسل مرتين بمعجون فلورايد."},category:"Prevention",source_name:"WHO",source_url:"https://www.who.int/news-room/fact-sheets/detail/oral-health",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Sugar and tooth decay",ar:"السكر وتسوس الأسنان",cat:"Prevention",sen:"Plaque bacteria turn free sugars into acids that damage teeth.\nFrequent high sugar intake increases the risk of decay.\nChoose a balanced diet and ask your dentist about personal risk.",sar:"بكتيريا البلاك بتحول السكريات الحرة لأحماض بتضر الأسنان.\nاستهلاك سكر كتير باستمرار بيزود احتمال التسوس.\nاختار أكل متوازن واسأل دكتورك عن عوامل الخطورة عندك.",src:"https://www.who.int/news-room/fact-sheets/detail/oral-health"},{title_en:"Water and oral health",title_ar:"المياه وصحة الفم",description_en:"Water is a good main drink in a tooth-friendly diet.\nIt avoids the free sugars found in many sweetened drinks.\nDrinking water does not replace fluoride brushing or dental care.",description_ar:"المياه اختيار مناسب كمشروب أساسي في أكل يحافظ على الأسنان.\nبتجنبك السكريات الحرة الموجودة في مشروبات محلاة كتير.\nشرب المياه مش بديل لغسيل الفلورايد أو علاج الأسنان.",symptoms:{en:"This is prevention advice, not a treatment for tooth pain.",ar:"دي نصيحة وقاية مش علاج لوجع الأسنان."},treatment:{en:"See a dentist for pain or signs of decay.",ar:"اكشف لو فيه وجع أو علامات تسوس."},prevention:{en:"Prefer water and limit sugary drinks.",ar:"فضل المياه وقلل المشروبات السكرية."},category:"Prevention",source_name:"WHO",source_url:"https://www.who.int/news-room/fact-sheets/detail/oral-health",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Water and oral health",ar:"المياه وصحة الفم",cat:"Prevention",sen:"Water is a good main drink in a tooth-friendly diet.\nIt avoids the free sugars found in many sweetened drinks.\nDrinking water does not replace fluoride brushing or dental care.",sar:"المياه اختيار مناسب كمشروب أساسي في أكل يحافظ على الأسنان.\nبتجنبك السكريات الحرة الموجودة في مشروبات محلاة كتير.\nشرب المياه مش بديل لغسيل الفلورايد أو علاج الأسنان.",src:"https://www.who.int/news-room/fact-sheets/detail/oral-health"},{title_en:"Ceramic braces",title_ar:"التقويم السيراميك",description_en:"Ceramic braces use tooth-coloured parts to be less noticeable.\nThey move teeth similarly to metal braces but can be more fragile.\nDiscuss appearance, care and suitability with an orthodontist.",description_ar:"التقويم السيراميك أجزاؤه بلون الأسنان عشان يكون أقل ظهوراً.\nبيحرك الأسنان زي المعدني لكن ممكن يكون أكثر قابلية للكسر.\nناقش الشكل والعناية والملاءمة مع أخصائي التقويم.",symptoms:{en:"Crowding, gaps or bite concerns need an assessment.",ar:"التزاحم والفراغات ومشاكل العضة محتاجة تقييم."},treatment:{en:"Custom orthodontic planning and regular adjustments.",ar:"خطة تقويم مناسبة وتعديلات منتظمة."},prevention:{en:"Clean around brackets and avoid hard or sticky foods.",ar:"نضف حوالين الحاصرات وتجنب الأكل الصلب واللزق."},category:"Orthodontics",source_name:"Cleveland Clinic",source_url:"https://my.clevelandclinic.org/health/treatments/24601-teeth-braces",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Ceramic braces",ar:"التقويم السيراميك",cat:"Orthodontics",sen:"Ceramic braces use tooth-coloured parts to be less noticeable.\nThey move teeth similarly to metal braces but can be more fragile.\nDiscuss appearance, care and suitability with an orthodontist.",sar:"التقويم السيراميك أجزاؤه بلون الأسنان عشان يكون أقل ظهوراً.\nبيحرك الأسنان زي المعدني لكن ممكن يكون أكثر قابلية للكسر.\nناقش الشكل والعناية والملاءمة مع أخصائي التقويم.",src:"https://my.clevelandclinic.org/health/treatments/24601-teeth-braces"},{title_en:"Lingual braces",title_ar:"التقويم الداخلي خلف الأسنان",description_en:"Lingual braces attach to the back surfaces of teeth.\nThey are less visible from the front than conventional braces.\nAn orthodontist can explain whether they suit your teeth and goals.",description_ar:"التقويم الداخلي بيتركب على السطح الخلفي للأسنان.\nبيكون أقل ظهوراً من قدام مقارنة بالتقويم المعتاد.\nالأخصائي يشرح إذا كان مناسب لأسنانك وأهدافك.",symptoms:{en:"Misaligned teeth or bite concerns require evaluation.",ar:"عدم انتظام الأسنان أو مشاكل العضة محتاجة تقييم."},treatment:{en:"Brackets and wires placed behind the teeth by a clinician.",ar:"حاصرات وأسلاك خلف الأسنان عند المختص."},prevention:{en:"Follow the orthodontist’s cleaning and diet instructions.",ar:"اتبع تعليمات الأخصائي للتنظيف والأكل."},category:"Orthodontics",source_name:"Cleveland Clinic",source_url:"https://my.clevelandclinic.org/health/treatments/24601-teeth-braces",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Lingual braces",ar:"التقويم الداخلي خلف الأسنان",cat:"Orthodontics",sen:"Lingual braces attach to the back surfaces of teeth.\nThey are less visible from the front than conventional braces.\nAn orthodontist can explain whether they suit your teeth and goals.",sar:"التقويم الداخلي بيتركب على السطح الخلفي للأسنان.\nبيكون أقل ظهوراً من قدام مقارنة بالتقويم المعتاد.\nالأخصائي يشرح إذا كان مناسب لأسنانك وأهدافك.",src:"https://my.clevelandclinic.org/health/treatments/24601-teeth-braces"},{title_en:"Self-ligating braces",title_ar:"التقويم ذاتي الربط",description_en:"Self-ligating braces have a built-in system holding the wire.\nThey do not use the same small ties as standard metal braces.\nYour orthodontist chooses an appliance for your needs, not a guaranteed faster result.",description_ar:"التقويم ذاتي الربط فيه نظام مدمج لتثبيت السلك.\nمش بيستخدم نفس الرباط الصغير الموجود في التقويم المعدني التقليدي.\nالأخصائي يختار الجهاز لاحتياجك، مش لضمان نتيجة أسرع.",symptoms:{en:"Crowded, gapped or misaligned teeth.",ar:"تزاحم أو فراغات أو أسنان غير منتظمة."},treatment:{en:"Individual orthodontic assessment and treatment planning.",ar:"تقييم وخطة علاج تقويم حسب الحالة."},prevention:{en:"Maintain cleaning and attend scheduled adjustments.",ar:"حافظ على التنظيف والتزم بمواعيد التعديل."},category:"Orthodontics",source_name:"Cleveland Clinic",source_url:"https://my.clevelandclinic.org/health/treatments/24601-teeth-braces",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Self-ligating braces",ar:"التقويم ذاتي الربط",cat:"Orthodontics",sen:"Self-ligating braces have a built-in system holding the wire.\nThey do not use the same small ties as standard metal braces.\nYour orthodontist chooses an appliance for your needs, not a guaranteed faster result.",sar:"التقويم ذاتي الربط فيه نظام مدمج لتثبيت السلك.\nمش بيستخدم نفس الرباط الصغير الموجود في التقويم المعدني التقليدي.\nالأخصائي يختار الجهاز لاحتياجك، مش لضمان نتيجة أسرع.",src:"https://my.clevelandclinic.org/health/treatments/24601-teeth-braces"},{title_en:"Bone graft recovery",title_ar:"التعافي بعد ترقيع عظم الفك",description_en:"Tenderness, swelling and bruising can occur after grafting.\nThe early recovery and bone healing times are different.\nContact the provider for severe pain, fever, pus or increasing swelling.",description_ar:"ممكن يحصل ألم بسيط وورم وكدمات بعد الترقيع.\nالتعافي الأولي ووقت التئام العظم مش نفس المدة.\nكلم الطبيب لو الألم شديد أو فيه حرارة أو صديد أو ورم بيزيد.",symptoms:{en:"Early tenderness or swelling; worsening symptoms need review.",ar:"ألم أو ورم أولي؛ زيادة الأعراض محتاجة مراجعة."},treatment:{en:"Follow the surgeon’s aftercare and attend follow-up visits.",ar:"اتبع تعليمات الجراح والتزم بالمتابعة."},prevention:{en:"Keep the area clean, avoid smoking and do not disturb the graft.",ar:"حافظ على نظافة المكان وتجنب التدخين ومتعبثش بالطعم."},category:"Surgery",source_name:"Cleveland Clinic",source_url:"https://my.clevelandclinic.org/health/treatments/21727-dental-bone-graft",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Bone graft recovery",ar:"التعافي بعد ترقيع عظم الفك",cat:"Surgery",sen:"Tenderness, swelling and bruising can occur after grafting.\nThe early recovery and bone healing times are different.\nContact the provider for severe pain, fever, pus or increasing swelling.",sar:"ممكن يحصل ألم بسيط وورم وكدمات بعد الترقيع.\nالتعافي الأولي ووقت التئام العظم مش نفس المدة.\nكلم الطبيب لو الألم شديد أو فيه حرارة أو صديد أو ورم بيزيد.",src:"https://my.clevelandclinic.org/health/treatments/21727-dental-bone-graft"},{title_en:"Dental bonding",title_ar:"البوندنج التجميلي للأسنان",description_en:"A dentist shapes tooth-coloured resin on a tooth.\nBonding can cover small chips, close gaps or change shape and colour.\nIt can chip or stain and may need repair or replacement.",description_ar:"الدكتور بيشكل راتنج بلون السن على سطحه.\nالبوندنج ممكن يغطي كسور صغيرة أو يقفل فراغات أو يغير الشكل واللون.\nممكن يتكسر أو يتصبغ ويحتاج إصلاح أو تغيير.",symptoms:{en:"Small chips, gaps, discolouration or shape concerns.",ar:"كسور بسيطة أو فراغات أو تصبغات أو مشكلة في الشكل."},treatment:{en:"A dentist selects resin, shapes it, hardens it with light and polishes it.",ar:"الدكتور يختار الراتنج ويشكله ويصلبه بالضوء ويلمعه."},prevention:{en:"Brush and floss; do not chew pens, nails or packages.",ar:"اغسل ونضف بين الأسنان ومتعضش أقلام أو أظافر ومتفتحش عبوات بأسنانك."},category:"Cosmetic",source_name:"Cleveland Clinic",source_url:"https://my.clevelandclinic.org/health/treatments/10922-dental-bonding",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Dental bonding",ar:"البوندنج التجميلي للأسنان",cat:"Cosmetic",sen:"A dentist shapes tooth-coloured resin on a tooth.\nBonding can cover small chips, close gaps or change shape and colour.\nIt can chip or stain and may need repair or replacement.",sar:"الدكتور بيشكل راتنج بلون السن على سطحه.\nالبوندنج ممكن يغطي كسور صغيرة أو يقفل فراغات أو يغير الشكل واللون.\nممكن يتكسر أو يتصبغ ويحتاج إصلاح أو تغيير.",src:"https://my.clevelandclinic.org/health/treatments/10922-dental-bonding"},{title_en:"Tooth contouring",title_ar:"إعادة تشكيل حواف الأسنان",description_en:"Tooth contouring removes a small amount of enamel to change shape.\nThere is a limit to how much enamel can safely be removed.\nDiscuss whether an irreversible change fits your needs.",description_ar:"إعادة التشكيل بتشيل كمية صغيرة من المينا لتغيير الشكل.\nفيه حد لكمية المينا اللي ممكن تتشال بأمان.\nناقش إذا كان التغيير غير القابل للرجوع مناسب لاحتياجك.",symptoms:{en:"Minor concerns about tooth shape.",ar:"ملاحظات بسيطة على شكل السن."},treatment:{en:"A dentist assesses enamel and suitability before reshaping.",ar:"الدكتور يقيم المينا والملاءمة قبل إعادة التشكيل."},prevention:{en:"Do not file teeth at home; keep daily cleaning and dental checks.",ar:"متبردش أسنانك في البيت؛ حافظ على التنظيف والكشف."},category:"Cosmetic",source_name:"Cleveland Clinic",source_url:"https://my.clevelandclinic.org/health/treatments/23914-cosmetic-dentistry",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Tooth contouring",ar:"إعادة تشكيل حواف الأسنان",cat:"Cosmetic",sen:"Tooth contouring removes a small amount of enamel to change shape.\nThere is a limit to how much enamel can safely be removed.\nDiscuss whether an irreversible change fits your needs.",sar:"إعادة التشكيل بتشيل كمية صغيرة من المينا لتغيير الشكل.\nفيه حد لكمية المينا اللي ممكن تتشال بأمان.\nناقش إذا كان التغيير غير القابل للرجوع مناسب لاحتياجك.",src:"https://my.clevelandclinic.org/health/treatments/23914-cosmetic-dentistry"},{title_en:"Gum contouring",title_ar:"تجميل وإعادة تشكيل اللثة",description_en:"Gum contouring removes extra tissue and reshapes the gum line.\nSome cases also need a small amount of bone removed.\nThe dentist explains recovery, infection risk and possible regrowth.",description_ar:"تجميل اللثة بيشيل النسيج الزائد ويعدل خط اللثة.\nبعض الحالات محتاجة كمان إزالة كمية صغيرة من العظم.\nالدكتور يشرح التعافي وخطر العدوى واحتمال رجوع النسيج.",symptoms:{en:"Uneven gum line or excessive visible gum.",ar:"خط لثة غير منتظم أو ظهور لثة زيادة."},treatment:{en:"A trained provider reshapes tissue with local anaesthesia.",ar:"مختص مدرب بيعيد تشكيل النسيج بتخدير موضعي."},prevention:{en:"Keep the site clean and follow soft-food and activity advice.",ar:"حافظ على نظافة المكان واتبع تعليمات الأكل الطري والمجهود."},category:"Cosmetic",source_name:"Cleveland Clinic",source_url:"https://my.clevelandclinic.org/health/treatments/25208-gum-contouring",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Gum contouring",ar:"تجميل وإعادة تشكيل اللثة",cat:"Cosmetic",sen:"Gum contouring removes extra tissue and reshapes the gum line.\nSome cases also need a small amount of bone removed.\nThe dentist explains recovery, infection risk and possible regrowth.",sar:"تجميل اللثة بيشيل النسيج الزائد ويعدل خط اللثة.\nبعض الحالات محتاجة كمان إزالة كمية صغيرة من العظم.\nالدكتور يشرح التعافي وخطر العدوى واحتمال رجوع النسيج.",src:"https://my.clevelandclinic.org/health/treatments/25208-gum-contouring"},{title_en:"Bonding aftercare",title_ar:"العناية بعد البوندنج",description_en:"Bonding often needs no recovery downtime.\nShort-term sensitivity can happen after treatment.\nCall the dentist if a sharp edge appears or your bite feels wrong.",description_ar:"البوندنج غالباً مش محتاج توقف عن النشاط اليومي.\nممكن تحصل حساسية لفترة قصيرة بعد العلاج.\nكلم الدكتور لو ظهرت حافة حادة أو العضة مش مظبوطة.",symptoms:{en:"Temporary sensitivity or a new rough edge.",ar:"حساسية مؤقتة أو حافة خشنة جديدة."},treatment:{en:"The dentist can adjust rough areas or assess bite discomfort.",ar:"الدكتور يقدر يعدل الأجزاء الخشنة أو يقيم عدم راحة العضة."},prevention:{en:"Brush twice daily, floss daily and avoid chewing hard objects.",ar:"اغسل مرتين ونضف بين الأسنان يومياً ومتعضش حاجات صلبة."},category:"Cosmetic",source_name:"Cleveland Clinic",source_url:"https://my.clevelandclinic.org/health/treatments/10922-dental-bonding",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Bonding aftercare",ar:"العناية بعد البوندنج",cat:"Cosmetic",sen:"Bonding often needs no recovery downtime.\nShort-term sensitivity can happen after treatment.\nCall the dentist if a sharp edge appears or your bite feels wrong.",sar:"البوندنج غالباً مش محتاج توقف عن النشاط اليومي.\nممكن تحصل حساسية لفترة قصيرة بعد العلاج.\nكلم الدكتور لو ظهرت حافة حادة أو العضة مش مظبوطة.",src:"https://my.clevelandclinic.org/health/treatments/10922-dental-bonding"},{title_en:"Gum contouring recovery",title_ar:"التعافي بعد تجميل اللثة",description_en:"Mild soreness can occur after gum reshaping.\nSoft foods and careful cleaning help during recovery.\nContact the provider for severe pain, persistent bleeding, pus or fever.",description_ar:"ممكن يحصل وجع بسيط بعد تجميل اللثة.\nالأكل الطري والتنظيف بحذر بيساعدوا خلال التعافي.\nكلم الطبيب لو الألم شديد أو النزيف مستمر أو فيه صديد أو حرارة.",symptoms:{en:"Expected mild tenderness; worsening symptoms need review.",ar:"ألم بسيط متوقع؛ زيادة الأعراض محتاجة مراجعة."},treatment:{en:"Follow the provider’s instructions and attend review visits.",ar:"اتبع تعليمات الطبيب والتزم بزيارات المراجعة."},prevention:{en:"Avoid strenuous activity and hard or spicy foods as directed.",ar:"تجنب المجهود الشديد والأكل الصلب أو الحار حسب التعليمات."},category:"Surgery",source_name:"Cleveland Clinic",source_url:"https://my.clevelandclinic.org/health/treatments/25208-gum-contouring",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Gum contouring recovery",ar:"التعافي بعد تجميل اللثة",cat:"Surgery",sen:"Mild soreness can occur after gum reshaping.\nSoft foods and careful cleaning help during recovery.\nContact the provider for severe pain, persistent bleeding, pus or fever.",sar:"ممكن يحصل وجع بسيط بعد تجميل اللثة.\nالأكل الطري والتنظيف بحذر بيساعدوا خلال التعافي.\nكلم الطبيب لو الألم شديد أو النزيف مستمر أو فيه صديد أو حرارة.",src:"https://my.clevelandclinic.org/health/treatments/25208-gum-contouring"},{title_en:"Bitewing X-rays",title_ar:"أشعة بايت وينج",description_en:"Bitewing images show selected upper and lower teeth together.\nThey help detect decay between teeth and near the gum line.\nYour dentist decides whether this view will help your examination.",description_ar:"أشعة بايت وينج بتوضح أسنان مختارة فوق وتحت مع بعض.\nبتساعد في اكتشاف التسوس بين الأسنان وقرب خط اللثة.\nدكتورك يحدد إذا كانت الصورة هتفيد في الكشف.",symptoms:{en:"Hidden decay may cause no early symptoms.",ar:"التسوس المخفي ممكن ميعملش أعراض في البداية."},treatment:{en:"A small sensor or film is positioned inside the mouth for imaging.",ar:"حساس صغير أو فيلم بيتحط داخل الفم للتصوير."},prevention:{en:"Continue prevention and have images only when clinically needed.",ar:"كمل الوقاية واعمل الأشعة وقت الاحتياج الطبي."},category:"Treatment",source_name:"Cleveland Clinic",source_url:"https://my.clevelandclinic.org/health/diagnostics/11199-dental-x-rays",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Bitewing X-rays",ar:"أشعة بايت وينج",cat:"Treatment",sen:"Bitewing images show selected upper and lower teeth together.\nThey help detect decay between teeth and near the gum line.\nYour dentist decides whether this view will help your examination.",sar:"أشعة بايت وينج بتوضح أسنان مختارة فوق وتحت مع بعض.\nبتساعد في اكتشاف التسوس بين الأسنان وقرب خط اللثة.\nدكتورك يحدد إذا كانت الصورة هتفيد في الكشف.",src:"https://my.clevelandclinic.org/health/diagnostics/11199-dental-x-rays"},{title_en:"Panoramic dental X-ray",title_ar:"أشعة بانوراما الأسنان",description_en:"A panoramic image shows the mouth and jaws in a broad view.\nIt can include teeth, jawbone, nerves and sinuses.\nIt complements other checks and does not replace every detailed tooth image.",description_ar:"البانوراما بتوضح الفم والفكين في صورة واسعة.\nممكن تشمل الأسنان وعظم الفك والأعصاب والجيوب.\nبتكمل الفحوصات ومش بديل لكل صورة تفصيلية للسن.",symptoms:{en:"Used for selected diagnostic or treatment-planning needs.",ar:"بتستخدم لاحتياجات تشخيص أو تخطيط علاج معينة."},treatment:{en:"The imaging machine captures the view with the sensor outside the mouth.",ar:"جهاز التصوير بياخد الصورة والحساس خارج الفم."},prevention:{en:"Tell your provider about previous imaging and follow positioning instructions.",ar:"بلغ المختص بالأشعة السابقة واتبع تعليمات الوقفة."},category:"Treatment",source_name:"Cleveland Clinic",source_url:"https://my.clevelandclinic.org/health/diagnostics/11199-dental-x-rays",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Panoramic dental X-ray",ar:"أشعة بانوراما الأسنان",cat:"Treatment",sen:"A panoramic image shows the mouth and jaws in a broad view.\nIt can include teeth, jawbone, nerves and sinuses.\nIt complements other checks and does not replace every detailed tooth image.",sar:"البانوراما بتوضح الفم والفكين في صورة واسعة.\nممكن تشمل الأسنان وعظم الفك والأعصاب والجيوب.\nبتكمل الفحوصات ومش بديل لكل صورة تفصيلية للسن.",src:"https://my.clevelandclinic.org/health/diagnostics/11199-dental-x-rays"},{title_en:"Dental cone beam CT",title_ar:"الأشعة المقطعية المخروطية للأسنان",description_en:"Cone beam CT produces three-dimensional dental and jaw images.\nIt may help selected cases such as implant planning.\nA dentist weighs the information needed against radiation exposure.",description_ar:"الأشعة المخروطية بتعمل صور تلاتية الأبعاد للأسنان والفكين.\nممكن تفيد حالات مختارة زي تخطيط الزراعة.\nالدكتور يوازن المعلومات المطلوبة مع التعرض للأشعة.",symptoms:{en:"A planning test, not a symptom-based diagnosis.",ar:"فحص للتخطيط ومش تشخيص بالأعراض."},treatment:{en:"Three-dimensional imaging when a clinician considers it necessary.",ar:"تصوير تلاتي الأبعاد لما المختص يشوفه ضروري."},prevention:{en:"Do not request repeat scans without a clinical reason.",ar:"متطلبش تكرار الأشعة من غير سبب طبي."},category:"Treatment",source_name:"Cleveland Clinic",source_url:"https://my.clevelandclinic.org/health/diagnostics/11199-dental-x-rays",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Dental cone beam CT",ar:"الأشعة المقطعية المخروطية للأسنان",cat:"Treatment",sen:"Cone beam CT produces three-dimensional dental and jaw images.\nIt may help selected cases such as implant planning.\nA dentist weighs the information needed against radiation exposure.",sar:"الأشعة المخروطية بتعمل صور تلاتية الأبعاد للأسنان والفكين.\nممكن تفيد حالات مختارة زي تخطيط الزراعة.\nالدكتور يوازن المعلومات المطلوبة مع التعرض للأشعة.",src:"https://my.clevelandclinic.org/health/diagnostics/11199-dental-x-rays"},{title_en:"Sealants for children",title_ar:"المادة الوقائية لشقوق أسنان الأطفال",description_en:"New back teeth can have deep grooves that trap food and bacteria.\nSealants may protect suitable permanent or sometimes baby teeth.\nA dentist checks eruption, decay risk and tooth condition first.",description_ar:"الأسنان الخلفية الجديدة ممكن يكون فيها شقوق عميقة بتحبس الأكل والبكتيريا.\nالمادة الوقائية ممكن تحمي أسنان دائمة مناسبة وأحياناً لبنية.\nالدكتور بيفحص طلوع السن وخطر التسوس وحالة السن الأول.",symptoms:{en:"Deep grooves or increased risk of back-tooth decay.",ar:"شقوق عميقة أو قابلية أعلى لتسوس الأسنان الخلفية."},treatment:{en:"A dental professional applies a protective coating to a suitable tooth.",ar:"مختص أسنان بيحط طبقة حماية على السن المناسب."},prevention:{en:"Help children brush and have sealants checked at dental visits.",ar:"ساعد الطفل في الغسيل وراجع المادة في زيارات الأسنان."},category:"Pediatric",source_name:"Cleveland Clinic",source_url:"https://my.clevelandclinic.org/health/treatments/10912-sealants",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Sealants for children",ar:"المادة الوقائية لشقوق أسنان الأطفال",cat:"Pediatric",sen:"New back teeth can have deep grooves that trap food and bacteria.\nSealants may protect suitable permanent or sometimes baby teeth.\nA dentist checks eruption, decay risk and tooth condition first.",sar:"الأسنان الخلفية الجديدة ممكن يكون فيها شقوق عميقة بتحبس الأكل والبكتيريا.\nالمادة الوقائية ممكن تحمي أسنان دائمة مناسبة وأحياناً لبنية.\nالدكتور بيفحص طلوع السن وخطر التسوس وحالة السن الأول.",src:"https://my.clevelandclinic.org/health/treatments/10912-sealants"},{title_en:"Oral thrush in babies",title_ar:"فطريات الفم عند الرضع",description_en:"Babies with thrush may have a white tongue coating or mouth spots.\nSome babies become reluctant to feed.\nA baby under four months with suspected thrush needs medical advice.",description_ar:"الرضيع المصاب بالفطريات ممكن يكون عنده طبقة بيضاء على اللسان أو بقع بالفم.\nبعض الأطفال ممكن يرفضوا الرضاعة.\nالرضيع أقل من أربع شهور مع اشتباه فطريات محتاج نصيحة طبيب.",symptoms:{en:"White mouth patches or feeding reluctance.",ar:"بقع بيضاء بالفم أو قلة الرغبة في الرضاعة."},treatment:{en:"Ask a clinician about age-appropriate treatment; do not choose a gel without advice.",ar:"اسأل الطبيب عن علاج مناسب للعمر ومتختارش جل من غير نصيحة."},prevention:{en:"Clean feeding equipment and sterilise bottles after use.",ar:"نضف أدوات الرضاعة وعقم الببرونات بعد الاستخدام."},category:"Pediatric",source_name:"NHS",source_url:"https://www.nhs.uk/conditions/oral-thrush-mouth-thrush/",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Oral thrush in babies",ar:"فطريات الفم عند الرضع",cat:"Pediatric",sen:"Babies with thrush may have a white tongue coating or mouth spots.\nSome babies become reluctant to feed.\nA baby under four months with suspected thrush needs medical advice.",sar:"الرضيع المصاب بالفطريات ممكن يكون عنده طبقة بيضاء على اللسان أو بقع بالفم.\nبعض الأطفال ممكن يرفضوا الرضاعة.\nالرضيع أقل من أربع شهور مع اشتباه فطريات محتاج نصيحة طبيب.",src:"https://www.nhs.uk/conditions/oral-thrush-mouth-thrush/"},{title_en:"Knocked-out baby tooth",title_ar:"خروج سن لبني بالكامل بعد إصابة",description_en:"Do not put a knocked-out baby tooth back into the socket.\nReinsertion can damage the permanent tooth developing underneath.\nArrange emergency dental assessment even if the tooth cannot be found.",description_ar:"مترجعش السن اللبني اللي خرج بالكامل لمكانه.\nإرجاعه ممكن يضر السن الدائم اللي بيتكون تحته.\nرتب كشف طوارئ أسنان حتى لو السن مش موجود.",symptoms:{en:"A baby tooth completely knocked out by an injury.",ar:"سن لبني خرج بالكامل بسبب إصابة."},treatment:{en:"A dentist assesses the injury and the developing teeth.",ar:"الدكتور يقيم الإصابة والأسنان اللي بتتكون."},prevention:{en:"Never reinsert a baby tooth; seek professional care promptly.",ar:"مترجعش السن اللبني مكانه واطلب رعاية مختص بسرعة."},category:"Pediatric",source_name:"NHS",source_url:"https://www.nhs.uk/conditions/knocked-out-tooth/",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Knocked-out baby tooth",ar:"خروج سن لبني بالكامل بعد إصابة",cat:"Pediatric",sen:"Do not put a knocked-out baby tooth back into the socket.\nReinsertion can damage the permanent tooth developing underneath.\nArrange emergency dental assessment even if the tooth cannot be found.",sar:"مترجعش السن اللبني اللي خرج بالكامل لمكانه.\nإرجاعه ممكن يضر السن الدائم اللي بيتكون تحته.\nرتب كشف طوارئ أسنان حتى لو السن مش موجود.",src:"https://www.nhs.uk/conditions/knocked-out-tooth/"},{title_en:"Gum graft recovery",title_ar:"التعافي بعد ترقيع اللثة",description_en:"Mild bleeding, swelling and soreness can follow gum grafting.\nDo not brush or floss directly on the graft until the surgeon allows it.\nSeek urgent advice for heavy bleeding, pus, fever or concerns about graft loss.",description_ar:"نزيف بسيط وورم ووجع ممكن يحصلوا بعد ترقيع اللثة.\nمتغسلش أو تنضف بالخيط فوق الطعم لحد سماح الجراح.\nاطلب نصيحة عاجلة لو النزيف شديد أو فيه صديد أو حرارة أو قلق من فقد الطعم.",symptoms:{en:"Early soreness and swelling; severe or worsening problems need review.",ar:"ألم وورم أولي؛ المشاكل الشديدة أو اللي بتزيد محتاجة مراجعة."},treatment:{en:"Follow the surgeon’s medicines, cleaning plan and review schedule.",ar:"اتبع أدوية الجراح وخطة التنظيف ومواعيد المراجعة."},prevention:{en:"Use soft foods and avoid strenuous activity until cleared.",ar:"كل أكل طري وتجنب المجهود الشديد لحد السماح."},category:"Surgery",source_name:"Cleveland Clinic",source_url:"https://my.clevelandclinic.org/health/treatments/23504-gum-graft-surgery",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Gum graft recovery",ar:"التعافي بعد ترقيع اللثة",cat:"Surgery",sen:"Mild bleeding, swelling and soreness can follow gum grafting.\nDo not brush or floss directly on the graft until the surgeon allows it.\nSeek urgent advice for heavy bleeding, pus, fever or concerns about graft loss.",sar:"نزيف بسيط وورم ووجع ممكن يحصلوا بعد ترقيع اللثة.\nمتغسلش أو تنضف بالخيط فوق الطعم لحد سماح الجراح.\nاطلب نصيحة عاجلة لو النزيف شديد أو فيه صديد أو حرارة أو قلق من فقد الطعم.",src:"https://my.clevelandclinic.org/health/treatments/23504-gum-graft-surgery"},{title_en:"Cold sore self-care",title_ar:"العناية بقرح البرد",description_en:"Cold sores usually start healing within ten days.\nAntiviral cream may work best at the early tingling stage.\nSeek medical advice for a very painful sore or one not starting to heal.",description_ar:"قرح البرد غالباً تبدأ تلتئم خلال عشرة أيام.\nكريم مضاد الفيروسات ممكن يكون أنفع في مرحلة الوخز المبكرة.\nاطلب نصيحة طبيب لو القرحة مؤلمة جداً أو مش بتبدأ تلتئم.",symptoms:{en:"Painful blisters or crusts near the mouth.",ar:"فقاقيع مؤلمة أو قشور قرب الفم."},treatment:{en:"A pharmacist can advise symptom relief and suitable products.",ar:"الصيدلي ينصح بتخفيف الأعراض والمنتجات المناسبة."},prevention:{en:"Avoid touching, use sun-protective lip balm and avoid personal triggers.",ar:"تجنب اللمس واستخدم مرطب شفايف واقي شمس وتجنب محفزاتك."},category:"Oral health",source_name:"NHS",source_url:"https://www.nhs.uk/conditions/cold-sores/",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Cold sore self-care",ar:"العناية بقرح البرد",cat:"Oral health",sen:"Cold sores usually start healing within ten days.\nAntiviral cream may work best at the early tingling stage.\nSeek medical advice for a very painful sore or one not starting to heal.",sar:"قرح البرد غالباً تبدأ تلتئم خلال عشرة أيام.\nكريم مضاد الفيروسات ممكن يكون أنفع في مرحلة الوخز المبكرة.\nاطلب نصيحة طبيب لو القرحة مؤلمة جداً أو مش بتبدأ تلتئم.",src:"https://www.nhs.uk/conditions/cold-sores/"},{title_en:"Full dentures",title_ar:"أطقم الأسنان الكاملة",description_en:"A full denture replaces all teeth in one upper or lower arch.\nIt rests on the gums and underlying supporting tissues.\nIt can take time and adjustments to become comfortable.",description_ar:"الطقم الكامل بيعوض كل الأسنان في فك علوي أو سفلي.\nبيستند على اللثة والأنسجة الداعمة تحتها.\nممكن يحتاج وقت وتعديلات لحد الراحة.",symptoms:{en:"Loss of all teeth in an arch.",ar:"فقدان كل الأسنان في فك."},treatment:{en:"Impressions, bite assessment and fittings create an individual appliance.",ar:"مقاسات وتقييم عضة وتجارب لعمل طقم مناسب."},prevention:{en:"Clean the denture and mouth daily and remove it for tissue rest.",ar:"نضف الطقم والفم يومياً وشيله لإراحة الأنسجة."},category:"Treatment",source_name:"Cleveland Clinic",source_url:"https://my.clevelandclinic.org/health/treatments/10900-dentures",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Full dentures",ar:"أطقم الأسنان الكاملة",cat:"Treatment",sen:"A full denture replaces all teeth in one upper or lower arch.\nIt rests on the gums and underlying supporting tissues.\nIt can take time and adjustments to become comfortable.",sar:"الطقم الكامل بيعوض كل الأسنان في فك علوي أو سفلي.\nبيستند على اللثة والأنسجة الداعمة تحتها.\nممكن يحتاج وقت وتعديلات لحد الراحة.",src:"https://my.clevelandclinic.org/health/treatments/10900-dentures"},{title_en:"Partial dentures",title_ar:"أطقم الأسنان الجزئية",description_en:"Partial dentures replace several missing teeth.\nThey rest on gum tissues and may use clasps around remaining teeth.\nA dentist checks support and fit before and after placement.",description_ar:"الطقم الجزئي بيعوض أكتر من سن مفقود.\nبيستند على اللثة وممكن يستخدم مشابك حوالين أسنان متبقية.\nالدكتور يفحص الدعم والمقاس قبل وبعد التركيب.",symptoms:{en:"Several missing teeth with some natural teeth remaining.",ar:"أسنان مفقودة مع بقاء بعض الأسنان الطبيعية."},treatment:{en:"A custom removable appliance fitted by a dental team.",ar:"طقم متحرك مناسب بيتركب عند فريق الأسنان."},prevention:{en:"Clean the appliance and remaining teeth daily.",ar:"نضف الطقم والأسنان المتبقية يومياً."},category:"Treatment",source_name:"Cleveland Clinic",source_url:"https://my.clevelandclinic.org/health/treatments/10900-dentures",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Partial dentures",ar:"أطقم الأسنان الجزئية",cat:"Treatment",sen:"Partial dentures replace several missing teeth.\nThey rest on gum tissues and may use clasps around remaining teeth.\nA dentist checks support and fit before and after placement.",sar:"الطقم الجزئي بيعوض أكتر من سن مفقود.\nبيستند على اللثة وممكن يستخدم مشابك حوالين أسنان متبقية.\nالدكتور يفحص الدعم والمقاس قبل وبعد التركيب.",src:"https://my.clevelandclinic.org/health/treatments/10900-dentures"},{title_en:"Snap-in dentures",title_ar:"الأطقم المتحركة المثبتة على زرعات",description_en:"Some dentures snap onto implants for added stability.\nThey can still be removed for daily cleaning.\nThe dentist checks bone, oral health and whether surgery is suitable.",description_ar:"فيه أطقم بتثبت على الزرعات لثبات أكتر.\nلسه ممكن تتشال للتنظيف اليومي.\nالدكتور يقيم العظم وصحة الفم وملاءمة الجراحة.",symptoms:{en:"Missing teeth with a need for improved denture stability.",ar:"فقدان أسنان مع احتياج لثبات أحسن للطقم."},treatment:{en:"Implant planning followed by a removable denture attachment.",ar:"تخطيط زرعات وبعدها توصيل طقم متحرك."},prevention:{en:"Remove and clean the denture and attachments as instructed.",ar:"شيل ونضف الطقم والوصلات حسب التعليمات."},category:"Treatment",source_name:"Cleveland Clinic",source_url:"https://my.clevelandclinic.org/health/treatments/10900-dentures",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Snap-in dentures",ar:"الأطقم المتحركة المثبتة على زرعات",cat:"Treatment",sen:"Some dentures snap onto implants for added stability.\nThey can still be removed for daily cleaning.\nThe dentist checks bone, oral health and whether surgery is suitable.",sar:"فيه أطقم بتثبت على الزرعات لثبات أكتر.\nلسه ممكن تتشال للتنظيف اليومي.\nالدكتور يقيم العظم وصحة الفم وملاءمة الجراحة.",src:"https://my.clevelandclinic.org/health/treatments/10900-dentures"},{title_en:"Fixed implant dentures",title_ar:"الأطقم الثابتة على زرعات",description_en:"A fixed implant denture is attached to dental implants.\nUnlike a snap-in appliance, only a dentist removes it.\nIt needs careful daily cleaning underneath.",description_ar:"الطقم الثابت بيتثبت على زرعات الأسنان.\nعلى عكس المتحرك المثبت على زرعات الدكتور بس اللي بيشيله.\nمحتاج تنظيف يومي دقيق من تحته.",symptoms:{en:"Extensive tooth loss and a preference for a fixed replacement.",ar:"فقدان أسنان كتير مع تفضيل تعويض ثابت."},treatment:{en:"A dental team assesses suitability and plans implants and the appliance.",ar:"فريق الأسنان يقيم الملاءمة ويخطط الزرعات والطقم."},prevention:{en:"Follow the taught cleaning method and professional maintenance visits.",ar:"اتبع طريقة التنظيف اللي اتعلمتها وزيارات الصيانة."},category:"Treatment",source_name:"Cleveland Clinic",source_url:"https://my.clevelandclinic.org/health/treatments/10900-dentures",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Fixed implant dentures",ar:"الأطقم الثابتة على زرعات",cat:"Treatment",sen:"A fixed implant denture is attached to dental implants.\nUnlike a snap-in appliance, only a dentist removes it.\nIt needs careful daily cleaning underneath.",sar:"الطقم الثابت بيتثبت على زرعات الأسنان.\nعلى عكس المتحرك المثبت على زرعات الدكتور بس اللي بيشيله.\nمحتاج تنظيف يومي دقيق من تحته.",src:"https://my.clevelandclinic.org/health/treatments/10900-dentures"},{title_en:"Maryland dental bridge",title_ar:"جسر ماريلاند اللاصق",description_en:"A Maryland bridge uses bonded wings to support a false tooth.\nIt is often considered for a missing front tooth.\nA dentist checks bite forces and neighbouring teeth before choosing it.",description_ar:"جسر ماريلاند بيستخدم أجنحة لاصقة لدعم سن صناعي.\nغالباً بيتاخد في الاعتبار لتعويض سن أمامي.\nالدكتور يقيم قوة العضة والأسنان المجاورة قبل اختياره.",symptoms:{en:"A missing tooth, commonly in the front of the mouth.",ar:"سن مفقود وغالباً في مقدمة الفم."},treatment:{en:"A custom false tooth is bonded to the backs of supporting teeth.",ar:"سن صناعي مناسب بيتلصق خلف الأسنان الداعمة."},prevention:{en:"Clean around and under the bridge and report looseness.",ar:"نضف حوالين الجسر وتحته وبلغ الدكتور لو بيتحرك."},category:"Treatment",source_name:"Cleveland Clinic",source_url:"https://my.clevelandclinic.org/health/treatments/10921-dental-bridges",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Maryland dental bridge",ar:"جسر ماريلاند اللاصق",cat:"Treatment",sen:"A Maryland bridge uses bonded wings to support a false tooth.\nIt is often considered for a missing front tooth.\nA dentist checks bite forces and neighbouring teeth before choosing it.",sar:"جسر ماريلاند بيستخدم أجنحة لاصقة لدعم سن صناعي.\nغالباً بيتاخد في الاعتبار لتعويض سن أمامي.\nالدكتور يقيم قوة العضة والأسنان المجاورة قبل اختياره.",src:"https://my.clevelandclinic.org/health/treatments/10921-dental-bridges"},{title_en:"Implant-supported bridge",title_ar:"جسر الأسنان المدعوم بزرعات",description_en:"This bridge rests on implants instead of natural teeth.\nThe implants need to bond with bone before the final bridge.\nThe treatment plan depends on bone, health and the missing teeth.",description_ar:"الجسر ده بيستند على زرعات بدل الأسنان الطبيعية.\nالزرعات محتاجة تلتحم بالعظم قبل الجسر النهائي.\nالخطة حسب العظم والصحة والأسنان المفقودة.",symptoms:{en:"Several adjacent missing teeth.",ar:"أكتر من سن متجاور مفقود."},treatment:{en:"Implant surgery, healing checks and a custom bridge.",ar:"جراحة زرعات ومراجعة الالتئام وجسر مناسب."},prevention:{en:"Clean beneath the bridge daily and attend reviews.",ar:"نضف تحت الجسر يومياً والتزم بالمتابعة."},category:"Treatment",source_name:"Cleveland Clinic",source_url:"https://my.clevelandclinic.org/health/treatments/10921-dental-bridges",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Implant-supported bridge",ar:"جسر الأسنان المدعوم بزرعات",cat:"Treatment",sen:"This bridge rests on implants instead of natural teeth.\nThe implants need to bond with bone before the final bridge.\nThe treatment plan depends on bone, health and the missing teeth.",sar:"الجسر ده بيستند على زرعات بدل الأسنان الطبيعية.\nالزرعات محتاجة تلتحم بالعظم قبل الجسر النهائي.\nالخطة حسب العظم والصحة والأسنان المفقودة.",src:"https://my.clevelandclinic.org/health/treatments/10921-dental-bridges"},{title_en:"Cleaning under a dental bridge",title_ar:"تنظيف تحت جسر الأسنان",description_en:"Plaque can collect underneath and around a bridge.\nFloss threaders or small interdental brushes can help reach these areas.\nAsk your dentist to demonstrate a method that fits your bridge.",description_ar:"البلاك ممكن يتجمع تحت الجسر وحواليه.\nمدخل الخيط أو الفرش الصغيرة ممكن يساعدوا يوصلوا للمناطق دي.\nاطلب من دكتورك يوريك طريقة مناسبة للجسر بتاعك.",symptoms:{en:"Food trapping, sore gums or bleeding may prompt a review.",ar:"حشر أكل أو ألم لثة أو نزيف ممكن يستدعي مراجعة."},treatment:{en:"A dentist checks the bridge and gum condition if symptoms develop.",ar:"الدكتور يفحص الجسر وحالة اللثة لو ظهرت أعراض."},prevention:{en:"Clean under the bridge daily and avoid chewing very hard objects.",ar:"نضف تحت الجسر يومياً ومتعضش على حاجات شديدة الصلابة."},category:"Prevention",source_name:"Cleveland Clinic",source_url:"https://my.clevelandclinic.org/health/treatments/10921-dental-bridges",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Cleaning under a dental bridge",ar:"تنظيف تحت جسر الأسنان",cat:"Prevention",sen:"Plaque can collect underneath and around a bridge.\nFloss threaders or small interdental brushes can help reach these areas.\nAsk your dentist to demonstrate a method that fits your bridge.",sar:"البلاك ممكن يتجمع تحت الجسر وحواليه.\nمدخل الخيط أو الفرش الصغيرة ممكن يساعدوا يوصلوا للمناطق دي.\nاطلب من دكتورك يوريك طريقة مناسبة للجسر بتاعك.",src:"https://my.clevelandclinic.org/health/treatments/10921-dental-bridges"},{title_en:"Reversible pulpitis",title_ar:"التهاب لب السن القابل للرجوع",description_en:"Early pulp inflammation may settle when the cause is removed.\nCold or sweet sensitivity may disappear quickly after the trigger stops.\nOnly a dental examination can confirm the diagnosis.",description_ar:"التهاب اللب المبكر ممكن يهدأ لما السبب يتشال.\nحساسية البارد أو الحلو ممكن تروح بسرعة بعد توقف المؤثر.\nكشف الأسنان هو اللي يؤكد التشخيص.",symptoms:{en:"Brief sensitivity to cold or sweets.",ar:"حساسية قصيرة للبارد أو الحلو."},treatment:{en:"The dentist removes the cause and restores or seals the tooth.",ar:"الدكتور يشيل السبب ويرمم أو يقفل السن."},prevention:{en:"Treat cavities early and maintain routine dental visits.",ar:"عالج التسوس بدري والتزم بزيارات الأسنان."},category:"Oral health",source_name:"Cleveland Clinic",source_url:"https://my.clevelandclinic.org/health/diseases/23536-pulpitis",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Reversible pulpitis",ar:"التهاب لب السن القابل للرجوع",cat:"Oral health",sen:"Early pulp inflammation may settle when the cause is removed.\nCold or sweet sensitivity may disappear quickly after the trigger stops.\nOnly a dental examination can confirm the diagnosis.",sar:"التهاب اللب المبكر ممكن يهدأ لما السبب يتشال.\nحساسية البارد أو الحلو ممكن تروح بسرعة بعد توقف المؤثر.\nكشف الأسنان هو اللي يؤكد التشخيص.",src:"https://my.clevelandclinic.org/health/diseases/23536-pulpitis"},{title_en:"Irreversible pulpitis",title_ar:"التهاب لب السن غير القابل للرجوع",description_en:"Advanced pulp inflammation cannot heal simply by placing a filling.\nSensitivity may linger and pain may be throbbing or sharp.\nA dentist confirms the problem and discusses definitive treatment.",description_ar:"التهاب اللب المتقدم مش بيتعافى بمجرد حشوة.\nالحساسية ممكن تستمر والألم يبقى نابض أو حاد.\nالدكتور يؤكد المشكلة ويناقش العلاج النهائي.",symptoms:{en:"Lingering hot or cold pain, toothache or tenderness on biting or tapping.",ar:"ألم بارد أو سخن مستمر أو وجع سن أو ألم مع العض أو الطرق."},treatment:{en:"Root canal treatment or extraction may be needed.",ar:"ممكن يحتاج علاج جذور أو خلع."},prevention:{en:"Do not wait for severe pain to disappear on its own.",ar:"متستناش الألم الشديد يروح لوحده."},category:"Oral health",source_name:"Cleveland Clinic",source_url:"https://my.clevelandclinic.org/health/diseases/23536-pulpitis",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Irreversible pulpitis",ar:"التهاب لب السن غير القابل للرجوع",cat:"Oral health",sen:"Advanced pulp inflammation cannot heal simply by placing a filling.\nSensitivity may linger and pain may be throbbing or sharp.\nA dentist confirms the problem and discusses definitive treatment.",sar:"التهاب اللب المتقدم مش بيتعافى بمجرد حشوة.\nالحساسية ممكن تستمر والألم يبقى نابض أو حاد.\nالدكتور يؤكد المشكلة ويناقش العلاج النهائي.",src:"https://my.clevelandclinic.org/health/diseases/23536-pulpitis"},{title_en:"Pulp vitality tests",title_ar:"اختبارات حيوية لب السن",description_en:"A dentist may test how a tooth responds to cold, heat or electrical stimulation.\nThese results help assess the tissue inside the tooth.\nTests are interpreted with the examination and sometimes X-rays.",description_ar:"الدكتور ممكن يختبر استجابة السن للبارد أو السخن أو تنبيه كهربائي.\nالنتائج بتساعد تقيم النسيج جوه السن.\nالاختبارات بتتفسر مع الكشف وأحياناً الأشعة.",symptoms:{en:"Tooth pain or altered sensitivity may lead to testing.",ar:"وجع سن أو تغير الحساسية ممكن يستدعي الاختبار."},treatment:{en:"Testing guides treatment; it is not a treatment by itself.",ar:"الاختبار بيرشد العلاج ومش علاج في حد ذاته."},prevention:{en:"Tell the dentist about symptoms and recent dental work.",ar:"بلغ الدكتور بالأعراض وأي علاج أسنان قريب."},category:"Treatment",source_name:"Cleveland Clinic",source_url:"https://my.clevelandclinic.org/health/diseases/23536-pulpitis",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Pulp vitality tests",ar:"اختبارات حيوية لب السن",cat:"Treatment",sen:"A dentist may test how a tooth responds to cold, heat or electrical stimulation.\nThese results help assess the tissue inside the tooth.\nTests are interpreted with the examination and sometimes X-rays.",sar:"الدكتور ممكن يختبر استجابة السن للبارد أو السخن أو تنبيه كهربائي.\nالنتائج بتساعد تقيم النسيج جوه السن.\nالاختبارات بتتفسر مع الكشف وأحياناً الأشعة.",src:"https://my.clevelandclinic.org/health/diseases/23536-pulpitis"},{title_en:"Periodontitis staging",title_ar:"تحديد مرحلة التهاب دواعم الأسنان",description_en:"Dentists describe gum-disease severity using stages and grades.\nThey assess tissue loss and how quickly disease seems to progress.\nThe result helps plan treatment and long-term reviews.",description_ar:"الدكاترة بيوصفوا شدة مرض اللثة بمراحل ودرجات.\nبيقيموا فقدان الأنسجة وسرعة تقدم المرض.\nالنتيجة بتساعد تخطط العلاج والمتابعة المستمرة.",symptoms:{en:"Bleeding, recession or loose teeth may prompt periodontal assessment.",ar:"نزيف أو انحسار أو حركة أسنان ممكن يستدعوا تقييم دواعم الأسنان."},treatment:{en:"A gum examination, measurements and imaging when indicated.",ar:"فحص لثة وقياسات وأشعة لما تلزم."},prevention:{en:"Follow the maintenance schedule chosen for your risk.",ar:"اتبع جدول الصيانة المناسب لخطورتك."},category:"Gum disease",source_name:"Cleveland Clinic",source_url:"https://my.clevelandclinic.org/health/diseases/16620-periodontitis",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Periodontitis staging",ar:"تحديد مرحلة التهاب دواعم الأسنان",cat:"Gum disease",sen:"Dentists describe gum-disease severity using stages and grades.\nThey assess tissue loss and how quickly disease seems to progress.\nThe result helps plan treatment and long-term reviews.",sar:"الدكاترة بيوصفوا شدة مرض اللثة بمراحل ودرجات.\nبيقيموا فقدان الأنسجة وسرعة تقدم المرض.\nالنتيجة بتساعد تخطط العلاج والمتابعة المستمرة.",src:"https://my.clevelandclinic.org/health/diseases/16620-periodontitis"},{title_en:"Pocket reduction surgery",title_ar:"جراحة تقليل جيوب اللثة",description_en:"Some advanced gum disease needs surgery to reach deep deposits.\nThe specialist lifts gum tissue, cleans the roots and closes the area.\nThe plan may include regenerative treatment when suitable.",description_ar:"بعض أمراض اللثة المتقدمة محتاجة جراحة للوصول للترسبات العميقة.\nالأخصائي يرفع نسيج اللثة وينضف الجذور ويقفل المكان.\nالخطة ممكن تشمل علاج تجديد أنسجة لما يكون مناسب.",symptoms:{en:"Deep pockets or advanced periodontal disease found on assessment.",ar:"جيوب عميقة أو مرض دواعم متقدم ظهر بالتقييم."},treatment:{en:"Specialist planning and surgery after evaluating disease severity.",ar:"تخطيط وجراحة عند مختص بعد تقييم شدة المرض."},prevention:{en:"Follow surgical aftercare and ongoing cleaning visits.",ar:"اتبع عناية الجراحة وزيارات التنظيف المستمرة."},category:"Surgery",source_name:"Cleveland Clinic",source_url:"https://my.clevelandclinic.org/health/diseases/16620-periodontitis",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Pocket reduction surgery",ar:"جراحة تقليل جيوب اللثة",cat:"Surgery",sen:"Some advanced gum disease needs surgery to reach deep deposits.\nThe specialist lifts gum tissue, cleans the roots and closes the area.\nThe plan may include regenerative treatment when suitable.",sar:"بعض أمراض اللثة المتقدمة محتاجة جراحة للوصول للترسبات العميقة.\nالأخصائي يرفع نسيج اللثة وينضف الجذور ويقفل المكان.\nالخطة ممكن تشمل علاج تجديد أنسجة لما يكون مناسب.",src:"https://my.clevelandclinic.org/health/diseases/16620-periodontitis"},{title_en:"Guided tissue regeneration",title_ar:"تجديد الأنسجة الموجه حول الأسنان",description_en:"A membrane may be placed in selected areas of lost tooth support.\nIt keeps unwanted tissue out while supporting bone regrowth.\nA gum specialist decides whether the defect is suitable.",description_ar:"ممكن تتحط غشاء في مناطق مختارة فقدت دعم السن.\nبيمنع نسيج غير مرغوب فيه وبيساعد يسيب مساحة لنمو العظم.\nأخصائي اللثة يحدد ملاءمة مكان الفقد.",symptoms:{en:"Bone-support loss identified by a professional assessment.",ar:"فقدان عظم داعم اتحدد بتقييم مختص."},treatment:{en:"Regenerative periodontal surgery in selected cases.",ar:"جراحة تجديد دواعم أسنان لحالات مختارة."},prevention:{en:"Maintain hygiene and attend planned post-operative reviews.",ar:"حافظ على النظافة والتزم بمراجعات ما بعد الجراحة."},category:"Surgery",source_name:"Cleveland Clinic",source_url:"https://my.clevelandclinic.org/health/diseases/16620-periodontitis",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Guided tissue regeneration",ar:"تجديد الأنسجة الموجه حول الأسنان",cat:"Surgery",sen:"A membrane may be placed in selected areas of lost tooth support.\nIt keeps unwanted tissue out while supporting bone regrowth.\nA gum specialist decides whether the defect is suitable.",sar:"ممكن تتحط غشاء في مناطق مختارة فقدت دعم السن.\nبيمنع نسيج غير مرغوب فيه وبيساعد يسيب مساحة لنمو العظم.\nأخصائي اللثة يحدد ملاءمة مكان الفقد.",src:"https://my.clevelandclinic.org/health/diseases/16620-periodontitis"},{title_en:"After deep dental cleaning",title_ar:"العناية بعد تنظيف الأسنان العميق",description_en:"Gums may feel tender and teeth may be more sensitive after deep cleaning.\nThe dental team gives instructions for your own situation.\nCall for bleeding that will not stop, severe swelling or uncontrolled pain.",description_ar:"اللثة ممكن تبقى مؤلمة والأسنان أكثر حساسية بعد التنظيف العميق.\nفريق الأسنان بيديك تعليمات مناسبة لحالتك.\nاتصل لو النزيف مش بيقف أو الورم شديد أو الألم مش مسيطر عليه.",symptoms:{en:"Temporary tenderness or sensitivity can occur.",ar:"ممكن يحصل ألم بسيط أو حساسية مؤقتة."},treatment:{en:"Follow care instructions and arrange reassessment of gum healing.",ar:"اتبع تعليمات العناية ورتب تقييم التئام اللثة."},prevention:{en:"Keep up gentle cleaning as instructed and maintenance visits.",ar:"كمل التنظيف برفق حسب التعليمات وزيارات الصيانة."},category:"Treatment",source_name:"Cleveland Clinic",source_url:"https://my.clevelandclinic.org/health/treatments/23983-tooth-scaling-and-root-planing",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"After deep dental cleaning",ar:"العناية بعد تنظيف الأسنان العميق",cat:"Treatment",sen:"Gums may feel tender and teeth may be more sensitive after deep cleaning.\nThe dental team gives instructions for your own situation.\nCall for bleeding that will not stop, severe swelling or uncontrolled pain.",sar:"اللثة ممكن تبقى مؤلمة والأسنان أكثر حساسية بعد التنظيف العميق.\nفريق الأسنان بيديك تعليمات مناسبة لحالتك.\nاتصل لو النزيف مش بيقف أو الورم شديد أو الألم مش مسيطر عليه.",src:"https://my.clevelandclinic.org/health/treatments/23983-tooth-scaling-and-root-planing"},{title_en:"Impacted canine teeth",title_ar:"الأنياب المدفونة",description_en:"Canines can remain trapped instead of growing into their normal position.\nAn examination and X-rays help locate the tooth and assess space.\nSome children and teens need treatment to help the canine erupt.",description_ar:"الأنياب ممكن تفضل مدفونة بدل ما تطلع في مكانها الطبيعي.\nالكشف والأشعة بيساعدوا يحددوا مكان السن والمساحة.\nبعض الأطفال والمراهقين محتاجين علاج يساعد الناب يطلع.",symptoms:{en:"A canine that does not erupt as expected may be found at a checkup.",ar:"ناب مطلعش بالشكل المتوقع ممكن يظهر بالكشف."},treatment:{en:"A dental team plans monitoring or eruption assistance as appropriate.",ar:"فريق الأسنان يخطط متابعة أو مساعدة على البزوغ حسب الحالة."},prevention:{en:"Regular developmental dental checks help detect impaction early.",ar:"متابعة نمو الأسنان بتساعد تكشف الانطمار بدري."},category:"Orthodontics",source_name:"Cleveland Clinic",source_url:"https://my.clevelandclinic.org/health/diseases/impacted-tooth",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Impacted canine teeth",ar:"الأنياب المدفونة",cat:"Orthodontics",sen:"Canines can remain trapped instead of growing into their normal position.\nAn examination and X-rays help locate the tooth and assess space.\nSome children and teens need treatment to help the canine erupt.",sar:"الأنياب ممكن تفضل مدفونة بدل ما تطلع في مكانها الطبيعي.\nالكشف والأشعة بيساعدوا يحددوا مكان السن والمساحة.\nبعض الأطفال والمراهقين محتاجين علاج يساعد الناب يطلع.",src:"https://my.clevelandclinic.org/health/diseases/impacted-tooth"},{title_en:"Gum flap removal around wisdom teeth",title_ar:"إزالة غطاء اللثة حول ضرس العقل",description_en:"A gum flap can trap food and bacteria around a partly erupted tooth.\nIn suitable cases a dentist may remove the flap to manage inflammation.\nRemoving the tooth may be a better option when problems continue.",description_ar:"غطاء اللثة ممكن يحبس الأكل والبكتيريا حوالين سن طالع جزئياً.\nفي حالات مناسبة الدكتور ممكن يشيل الغطاء لعلاج الالتهاب.\nخلع السن ممكن يكون أنسب لو المشاكل مستمرة.",symptoms:{en:"Repeated inflammation, pain or food trapping under the flap.",ar:"التهاب متكرر أو ألم أو حشر أكل تحت الغطاء."},treatment:{en:"Assessment for operculectomy or wisdom tooth removal.",ar:"تقييم لإزالة غطاء اللثة أو خلع ضرس العقل."},prevention:{en:"Keep the area clean and follow the dentist’s review plan.",ar:"حافظ على نظافة المكان والتزم بخطة المراجعة."},category:"Surgery",source_name:"Cleveland Clinic",source_url:"https://my.clevelandclinic.org/health/diseases/24142-pericoronitis",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Gum flap removal around wisdom teeth",ar:"إزالة غطاء اللثة حول ضرس العقل",cat:"Surgery",sen:"A gum flap can trap food and bacteria around a partly erupted tooth.\nIn suitable cases a dentist may remove the flap to manage inflammation.\nRemoving the tooth may be a better option when problems continue.",sar:"غطاء اللثة ممكن يحبس الأكل والبكتيريا حوالين سن طالع جزئياً.\nفي حالات مناسبة الدكتور ممكن يشيل الغطاء لعلاج الالتهاب.\nخلع السن ممكن يكون أنسب لو المشاكل مستمرة.",src:"https://my.clevelandclinic.org/health/diseases/24142-pericoronitis"},{title_en:"Dental extraction aftercare",title_ar:"العناية بعد خلع الأسنان",description_en:"A blood clot protects the socket while it heals.\nAvoid disturbing the area and follow your own written aftercare plan.\nContact the dental team for fever, pus or severe uncontrolled pain.",description_ar:"الجلطة الدموية بتحمي مكان الخلع وهو بيلتئم.\nتجنب تحريك المكان واتبع تعليمات العناية المكتوبة ليك.\nكلم فريق الأسنان لو فيه حرارة أو صديد أو ألم شديد مش مسيطر عليه.",symptoms:{en:"Some soreness, swelling or slight oozing can occur early on.",ar:"ممكن يحصل وجع أو ورم أو نز دم بسيط في الأول."},treatment:{en:"Use prescribed care and attend review if recovery is not progressing.",ar:"استخدم العناية الموصوفة وراجع لو التعافي مش بيتحسن."},prevention:{en:"Avoid smoking, straws, forceful rinsing and poking the socket.",ar:"تجنب التدخين والشفاط والمضمضة القوية والعبث بمكان الخلع."},category:"Surgery",source_name:"Cleveland Clinic",source_url:"https://my.clevelandclinic.org/health/treatments/22120-tooth-extraction",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Dental extraction aftercare",ar:"العناية بعد خلع الأسنان",cat:"Surgery",sen:"A blood clot protects the socket while it heals.\nAvoid disturbing the area and follow your own written aftercare plan.\nContact the dental team for fever, pus or severe uncontrolled pain.",sar:"الجلطة الدموية بتحمي مكان الخلع وهو بيلتئم.\nتجنب تحريك المكان واتبع تعليمات العناية المكتوبة ليك.\nكلم فريق الأسنان لو فيه حرارة أو صديد أو ألم شديد مش مسيطر عليه.",src:"https://my.clevelandclinic.org/health/treatments/22120-tooth-extraction"},{title_en:"Socket healing after extraction",title_ar:"التئام مكان خلع السن",description_en:"A socket heals through clot formation and growth of new tissue.\nGum healing and deeper bone healing take different lengths of time.\nA pale healing surface alone does not prove infection.",description_ar:"مكان الخلع بيلتئم بتكوين جلطة ونمو أنسجة جديدة.\nالتئام اللثة والعظم العميق بياخدوا أوقات مختلفة.\nسطح الالتئام الفاتح لوحده مش دليل عدوى.",symptoms:{en:"Some early discomfort is expected; fever, pus or severe pain need review.",ar:"فيه انزعاج متوقع في الأول والحرارة أو الصديد أو الألم الشديد محتاجين مراجعة."},treatment:{en:"The dentist assesses healing if symptoms are worrying or worsening.",ar:"الدكتور يقيم الالتئام لو الأعراض مقلقة أو بتزيد."},prevention:{en:"Leave the clot undisturbed and follow the recovery instructions.",ar:"متعبثش بالجلطة واتبع تعليمات التعافي."},category:"Surgery",source_name:"Cleveland Clinic",source_url:"https://my.clevelandclinic.org/health/treatments/22120-tooth-extraction",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"Socket healing after extraction",ar:"التئام مكان خلع السن",cat:"Surgery",sen:"A socket heals through clot formation and growth of new tissue.\nGum healing and deeper bone healing take different lengths of time.\nA pale healing surface alone does not prove infection.",sar:"مكان الخلع بيلتئم بتكوين جلطة ونمو أنسجة جديدة.\nالتئام اللثة والعظم العميق بياخدوا أوقات مختلفة.\nسطح الالتئام الفاتح لوحده مش دليل عدوى.",src:"https://my.clevelandclinic.org/health/treatments/22120-tooth-extraction"},{title_en:"When to see an endodontist",title_ar:"إمتى تحتاج أخصائي علاج جذور",description_en:"Endodontists focus on the pulp and root tissues inside and around teeth.\nThey assess complex pain, damaged pulp and previously treated teeth.\nYour dentist may refer you when specialist care can help save a tooth.",description_ar:"أخصائي الجذور بيركز على اللب وأنسجة الجذور جوه وحوالين الأسنان.\nبيقيم الألم المعقد واللب التالف والأسنان المتعالجة قبل كده.\nدكتورك ممكن يحولك لما رعاية مختص تساعد تنقذ السن.",symptoms:{en:"Lingering tooth pain, sensitivity or inflammation.",ar:"وجع سن مستمر أو حساسية أو التهاب."},treatment:{en:"Specialised testing and treatment matched to the diagnosis.",ar:"اختبارات وعلاج متخصصين حسب التشخيص."},prevention:{en:"Keep records of earlier treatment and attend advised follow-up.",ar:"احتفظ بمعلومات العلاج السابق والتزم بالمتابعة المطلوبة."},category:"Treatment",source_name:"Cleveland Clinic",source_url:"https://my.clevelandclinic.org/health/articles/16959-endodontics",last_updated:"2026-11-23",verification_status:"verified",disclaimer:"المعلومات للتوعية فقط، استشر طبيبك للتشخيص الدقيق",en:"When to see an endodontist",ar:"إمتى تحتاج أخصائي علاج جذور",cat:"Treatment",sen:"Endodontists focus on the pulp and root tissues inside and around teeth.\nThey assess complex pain, damaged pulp and previously treated teeth.\nYour dentist may refer you when specialist care can help save a tooth.",sar:"أخصائي الجذور بيركز على اللب وأنسجة الجذور جوه وحوالين الأسنان.\nبيقيم الألم المعقد واللب التالف والأسنان المتعالجة قبل كده.\nدكتورك ممكن يحولك لما رعاية مختص تساعد تنقذ السن.",src:"https://my.clevelandclinic.org/health/articles/16959-endodontics"}];